INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('klemensms/mcp-consultant-tools/write-unit-tests', 'write-unit-tests', 'klemensms', 'mcp-consultant-tools', 'community', 'write-unit-tests klemensms mcp-consultant-tools community The write-unit-tests skill generates comprehensive unit tests for C# source code, covering business scenarios, edge cases, and error conditions. This skill benefits .NET testing specialists and developers. AI工具生成C#代码的单元测试，遵循项目的测试指南和标准 AIエージェントはC#コードの単体テストを生成し、プロジェクトのテスト指南と規格に従う AI 도구는 C# 코드의 유닛 테스트를 생성하며 프로젝트의 테스트 지침 및 표준을 따릅니다 Genera unit tests completos para C# y .NET con herramientas de AI, cubriendo escenarios de negocio y casos límite Générez des unit tests complets pour C# et .NET avec des outils d''IA, couvrant les scénarios métier et les cas limites Erstellen Sie umfassende Unit-Tests für C# und .NET mit KI-Tools, die Geschäftsszenarien und Grenzfälle abdecken O write-unit-tests é uma ferramenta que gera testes unitários abrangentes para código C#. Ele segue os padrões de teste definidos no projeto. ИИ Агент write-unit-tests генерирует комплексные юнит-тесты для кода C#. Он следует рекомендациям по тестированию, определенным в проекте. عميل الذكاء الاصطناعي write-unit-tests يولد اختبارات وحدة شاملة لкод C#. يتبع معايير الاختبار المحددة في المشروع. how to use write-unit-tests write-unit-tests for .NET generate unit tests for C# write-unit-tests alternative write-unit-tests setup guide write-unit-tests install 写单元测试的AI工具 C#代码测试 单元测试生成 AI工具 测试指南 测试标准 边缘情况 错误条件 Generates unit tests for C# source code files Follows testing patterns and standards defined in the project''s testing instructions Covers business scenarios, edge cases, and error conditions Extends or tweaks existing unit tests using defined standards Supports .NET testing specialists and developers write-unit-tests is a skill that analyzes C# source code files and generates complete unit test files following defined testing patterns and standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JaimeCernuda/abaqus-scripting/abaqus-export', 'community', 'JaimeCernuda', 'abaqus-scripting', 'JaimeCernuda/abaqus-scripting', 'abaqus-export', 0, 0, 44, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:15.885Z', '2800605475e72f4f9e218ea80111b77034ae33dbdeeafde668ca7fc1310ae6d0', '{"id":"JaimeCernuda/abaqus-scripting/abaqus-export","name":"abaqus-export","description":{"en":"The Abaqus-Export skill enables the export of geometry and results from Abaqus to external formats, benefiting developers and engineers working with 3D printing, CAD exchange, and data analysis.","zh":"Abaqus导出技能允许用户导出几何体和结果到外部格式，用于3D打印、CAD交换、数据分析或存档","ja":"Abaqusエクスポートスキルは、ユーザーが3Dプリンティング、CAD交換、データ分析、または保存のために外部形式で幾何学と結果をエクスポートできるようにします","ko":"Abaqus导出스킬은 사용자가 3D 프린팅, CAD 교환, 데이터 분석 또는 보관을 위해 외부 형식에서 기하학 및 결과를导出 할 수 있습니다","es":"Abaqus Export es una habilidad que permite exportar geometrías y resultados de Abaqus a formatos externos para impresión 3D, intercambio de CAD y análisis de datos","fr":"Abaqus Export est une compétence qui permet d''exporter des géométries et des résultats Abaqus vers des formats externes pour l''impression 3D, l''échange de CAD et l''analyse de données","de":"Abaqus Export ist eine Fähigkeit, die das Exportieren von Geometrien und Ergebnissen von Abaqus in externe Formate für 3D-Druck, CAD-Austausch und Datenanalyse ermöglicht","pt":"O Abaqus Export é uma habilidade que permite exportar geometrias e resultados do Abaqus para formatos externos para impressão 3D, troca de CAD e análise de dados","ru":"ИИ Агент Abaqus Export позволяет экспортировать геометрии и результаты из Abaqus в внешние форматы для 3D-печати, обмена CAD и анализа данных","ar":"يسمح Abaqus Export بتصدير الهندسة و النتائج من Abaqus إلى صيغ خارجية لطباعة 3D و تبادل CAD و تحليل البيانات"},"seo":{"title":{"en":"Abaqus-Export: 3D Printing and CAD Exchange Setup Guide |...","zh":"Abaqus导出技能设置指南 - 3D打印和CAD交换","ja":"Abaqusエクスポートスキルのベストプラクティス - 3DプリンティングとCAD交換","ko":"Abaqus导出스킬 설정 가이드 - 3D 프린팅 및 CAD 교환","es":"Guía de configuración de Abaqus Export para impresión 3D ...","fr":"Guide de mise en route d''Abaqus Export pour l''impression ...","de":"Einrichtungsleitfaden für Abaqus Export für 3D-Druck und ...","pt":"Guia de Configuração Abaqus Export para Impressão 3D e An...","ru":"Настройка ИИ Агента Abaqus Export для 3D-печати и анализа...","ar":"دليل إعداد Abaqus Export لطباعة 3D و تحليل البيانات"},"description":{"en":"Unlock seamless Abaqus data export to STL, STEP, and CSV. Learn how to set up Abaqus-Export for 3D printing, CAD exchange, and data analysis. Get started now!","zh":"了解Abaqus导出技能的功能和应用，实现3D打印、CAD交换、数据分析和存档","ja":"Abaqusエクスポートスキルの機能と応用について学び、3Dプリンティング、CAD交換、データ分析、保存を行う","ko":"Abaqus导出스킬의 기능과 적용에 대해 알아보고 3D 프린팅, CAD 교환, 데이터 분석, 보관을 수행합니다","es":"Aprende a exportar geometrías y resultados de Abaqus a formatos externos como STL, STEP y CSV para impresión 3D, intercambio de CAD y análisis de datos","fr":"Découvrez comment exporter des géométries et des résultats Abaqus vers des formats externes tels que STL, STEP et CSV pour l''impression 3D, l''échange de CAD ...","de":"Erfahren Sie, wie Sie Geometrien und Ergebnisse von Abaqus in externe Formate wie STL, STEP und CSV für 3D-Druck, CAD-Austausch und Datenanalyse exportieren","pt":"Aprenda a exportar geometrias e resultados do Abaqus para formatos externos como STL, STEP e CSV para impressão 3D, troca de CAD e análise de dados","ru":"Экспортируйте геометрии и результаты из Abaqus в внешние форматы, такие как STL, STEP и CSV, для 3D-печати, обмена CAD и анализа данных с помощью ИИ Агентов","ar":"تعلم كيفية تصدير الهندسة و النتائج من Abaqus إلى صيغ خارجية مثل STL و STEP و CSV لطباعة 3D و تبادل CAD و تحليل البيانات"},"definition":{"en":"Abaqus-export is a skill that allows users to export Abaqus data to various formats, including STL, STEP, and CSV, for applications such as 3D printing and CAD exchange.","zh":"Abaqus导出技能是一种将Abaqus数据导出到外部格式的工具","ja":"Abaqusエクスポートスキルは、Abaqusデータを外部形式でエクスポートするツールです","ko":"Abaqus导出스킬은 Abaqus 데이터를 외부 형식으로导出하는 도구입니다","es":"Abaqus Export es una habilidad que permite exportar datos de Abaqus a formatos como STL, STEP y CSV","fr":"Abaqus Export est une compétence qui permet d''exporter des données Abaqus vers des formats tels que STL, STEP et CSV","de":"Abaqus Export ist eine Fähigkeit, die das Exportieren von Abaqus-Daten in Formate wie STL, STEP und CSV ermöglicht","pt":"O que é Abaqus Export? É uma habilidade que permite exportar dados do Abaqus para formatos como STL, STEP e CSV","ru":"Что такое Abaqus Export? Это ИИ Агент, который позволяет экспортировать данные из Abaqus в форматы, такие как STL, STEP и CSV","ar":"ما هو Abaqus Export؟ إنه مهارة تسمح بتصدير البيانات من Abaqus إلى صيغ مثل STL و STEP و CSV"},"features":{"en":["Exports geometry to STL format for 3D printing","Converts data to STEP format for CAD exchange","Generates input files in INP format","Exports results to CSV format for data analysis","Saves mesh data for further processing","Exports deformed shape and topology results"],"zh":["导出几何体到STL格式","导出结果到CSV或Excel格式","生成输入文件（INP）","保存网格数据","导出变形形状或拓扑结果"],"ja":["幾何学をSTL形式でエクスポート","結果をCSVまたはExcel形式でエクスポート","入力ファイル（INP）を生成","メッシュデータを保存","変形形状またはトポロジー結果をエクスポート"],"ko":["기하학을 STL 형식으로导出","결과를 CSV 또는 Excel 형식으로导出","입력 파일（INP）을 생성","메쉬 데이터를 저장","변형 형상 또는 토폴로지 결과를导出"],"es":["Exportación de geometrías a STL para impresión 3D","Exportación de resultados a CSV para análisis de datos","Exportación de geometrías a STEP para intercambio de CAD","Generación de archivos de entrada para Abaqus","Exportación de mallas y datos de topología"],"fr":["Exportation de géométries vers STL pour l''impression 3D","Exportation de résultats vers CSV pour l''analyse de données","Exportation de géométries vers STEP pour l''échange de CAD","Génération de fichiers d''entrée pour Abaqus","Exportation de maillages et de données de topologie"],"de":["Export von Geometrien nach STL für 3D-Druck","Export von Ergebnissen nach CSV für Datenanalyse","Export von Geometrien nach STEP für CAD-Austausch","Erstellung von Eingabedateien für Abaqus","Export von Netzen und Topologie-Daten"],"pt":["Exportação de geometrias para STL","Conversão de dados para STEP","Geração de arquivos de entrada para impressão 3D","Exportação de resultados para CSV","Extração de dados de malha","Exportação de forma deformada"],"ru":["Экспорт геометрий в STL","Преобразование данных в STEP","Генерация входных файлов для 3D-печати","Экспорт результатов в CSV","Извлечение данных сетки","Экспорт деформированной формы"],"ar":["تصدير الهندسة إلى STL","تحويل البيانات إلى STEP","إنشاء ملفات إدخال لطباعة 3D","تصدير النتائج إلى CSV","استخراج بيانات الشبكة","تصدير الشكل المُشوه"]},"keywords":{"en":["how to use abaqus-export","abaqus-export alternative","abaqus-export setup guide","what is abaqus-export","abaqus-export vs other CAD tools","abaqus-export install","abaqus-export for 3D printing","abaqus-export for CAD exchange","abaqus-export tutorial"],"zh":["Abaqus导出","3D打印","CAD交换","数据分析","存档","STL格式","CSV格式","Excel格式","INP文件","网格数据"],"ja":["Abaqusエクスポート","3Dプリンティング","CAD交換","データ分析","保存","STL形式","CSV形式","Excel形式","INPファイル","メッシュデータ"],"ko":["Abaqus导出","3D 프린팅","CAD 교환","데이터 분석","보관","STL 형식","CSV 형식","Excel 형식","INP 파일","메쉬 데이터"],"es":["Abaqus Export","impresión 3D","análisis de datos","intercambio de CAD","exportar geometrías","exportar resultados","STL","STEP","CSV"],"fr":["Abaqus Export","impression 3D","analyse de données","échange de CAD","exporter des géométries","exporter des résultats","STL","STEP","CSV"],"de":["Abaqus Export","3D-Druck","Datenanalyse","CAD-Austausch","Geometrien exportieren","Ergebnisse exportieren","STL","STEP","CSV"],"pt":["Abaqus Export","Impressão 3D","Análise de dados","Troca de CAD","Exportação de geometrias","Conversão de dados","Geração de arquivos de entrada","Exportação de resultados","Extração de dados de malha"],"ru":["Abaus Export","3D-печать","Анализ данных","Обмен CAD","Экспорт геометрий","Преобразование данных","Генерация входных файлов","Экспорт результатов","Извлечение данных сетки"],"ar":["Abaqus Export","طباعة 3D","تحليل البيانات","تبادل CAD","تصدير الهندسة","تحويل البيانات","إنشاء ملفات إدخال","تصدير النتائج","استخراج بيانات الشبكة"]}},"owner":"JaimeCernuda","repo":"abaqus-scripting","repoPath":"JaimeCernuda/abaqus-scripting","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"abaqus-export","description":"Export Abaqus geometry and results. Use when user mentions exporting to STL, STEP, CSV, or generating input files for external use.","bodyPreview":"# Abaqus Export Skill\n\nExport geometry and results from Abaqus to external formats for 3D printing, CAD exchange, data analysis, or archival.\n\n## When to Use This Skill\n\n**Route here when user mentions:**\n- \"Export to STL\" / \"Convert to STL\" / \"3D printing\"\n- \"Save as STEP\" / \"Export to CAD\"\n- \"Generate input file\" / \"Write INP\"\n- \"Export results to CSV\" / \"Export to Excel\"\n- \"Save the mesh\" / \"Extract mesh data\"\n- \"Export deformed shape\" / \"Export topology result\"\n\n**Route elsewhere:**\n- Readin","body":"# Abaqus Export Skill\n\nExport geometry and results from Abaqus to external formats for 3D printing, CAD exchange, data analysis, or archival.\n\n## When to Use This Skill\n\n**Route here when user mentions:**\n- \"Export to STL\" / \"Convert to STL\" / \"3D printing\"\n- \"Save as STEP\" / \"Export to CAD\"\n- \"Generate input file\" / \"Write INP\"\n- \"Export results to CSV\" / \"Export to Excel\"\n- \"Save the mesh\" / \"Extract mesh data\"\n- \"Export deformed shape\" / \"Export topology result\"\n\n**Route elsewhere:**\n- Reading ODB results → `/abaqus-odb`\n- Importing CAD files → `/abaqus-geometry`\n- Running analysis → `/abaqus-job`\n\n## Key Decisions\n\n### What Format to Use?\n\n| Need | Format | Requires |\n|------|--------|----------|\n| 3D printing | STL (double precision) | Meshed part |\n| CAD exchange | STEP | Part geometry |\n| Legacy CAD | IGES | Part geometry |\n| Data analysis | CSV | ODB file |\n| Archive/HPC | INP | Complete model |\n| Reports/images | PNG/SVG | GUI session |\n\n### What to Export?\n\n| Source | Available Formats |\n|--------|------------------|\n| Part geometry | STL, STEP, IGES, SAT |\n| Assembly | STL, SAT |\n| Mesh data | CSV (nodes, elements) |\n| Results (U, S, RF) | CSV |\n| Time history | CSV |\n| Model definition | INP |\n| Topology result | STL (with density threshold) |\n\n## What to Ask User\n\nIf unclear, ask:\n1. **What format?** STL, STEP, CSV, INP?\n2. **What to export?** Geometry, mesh, or results?\n3. **Which parts/steps?** Specific part name, all parts, specific time step?\n4. **For TO results:** What density threshold? (0.3-0.5 typical)\n\n## Workflow\n\n### Exporting Geometry (STL/STEP/IGES)\n\n1. **Identify the part** - Get part name from model\n2. **Check if meshed** - STL requires mesh; STEP works on geometry\n3. **Call export method** - Use appropriate API call\n4. **Verify output** - Check file was created\n\n### Exporting Results to CSV\n\n1. **Open the ODB** - Use `openOdb()` with `readOnly=True`\n2. **Navigate to frame** - Find correct step and frame (typically last)\n3. **Extract field output** - U (displacement), S (stress), etc.\n4. **Write CSV** - Loop through values, write rows\n5. **Close ODB** - Always close when done\n\n### Generating Input File\n\n1. **Create job object** - Job needs model name\n2. **Call writeInput()** - Creates `JobName.inp`\n3. **Verify INP created** - Check file exists\n\n### Exporting TO Result\n\n1. **Locate TO ODB** - Usually `Optimization/TOSCA_POST/Optimization.odb`\n2. **Set density threshold** - 0.3-0.5 typical (lower = more material)\n3. **Export STL** - Use session method or GUI\n\n## Troubleshooting\n\n| Problem | Cause | Solution |\n|---------|-------|----------|\n| \"Cannot write STL - no mesh\" | Part not meshed | Mesh part first |\n| \"STEP export failed\" | Invalid geometry | Try IGES or SAT |\n| Large STL file | Fine mesh | Coarsen mesh for viz |\n| Permission denied | File open elsewhere | Close file first |\n| Image export fails | noGUI mode | Run with GUI |\n\n## Code Patterns\n\nFor API syntax and code examples, see:\n- [API Quick Reference](references/api-quick-ref.md)\n- [Common Patterns](references/common-patterns.md)\n- [Troubleshooting Guide](references/troubleshooting.md)\n"},"lastSynced":"2026-03-08T02:04:15.885Z","agentAnalysis":{"suitability":{"en":"Perfect for Engineering Agents needing advanced Abaqus data export capabilities for 3D printing and CAD exchange.","zh":"适用于需要高级Abaqus数据导出功能的工程代理，尤其是用于3D打印和CAD交换。","ja":"エンジニアリングエージェントがAbaqusの高度なデータエクスポート機能を必要とする場合に最適です。特に3DプリンティングとCAD交換に使用されます。","ko":"고급 Abaqus 데이터 내보내기 기능이 필요한 엔지니어링 에이전트에게 적합하며, 3D 프린팅 및 CAD 교환에 특히 유용합니다.","es":"Perfecto para Agentes de Ingeniería que necesitan capacidades avanzadas de exportación de datos de Abaqus para impresión 3D y exchange de CAD.","fr":"Parfait pour les agents d''ingénierie ayant besoin de capacités avancées d''exportation de données Abaqus pour l''impression 3D et l''échange de CAD.","de":"Perfekt für Ingenieursagenten, die erweiterte Abaqus-Datenexportfunktionen für 3D-Druck und CAD-Austausch benötigen.","pt":"Perfeito para Agentes de Engenharia que necessitam de capacidades avançadas de exportação de dados Abaqus para impressão 3D e troca de CAD.","ru":"Идеально подходит для инженеров-агентов, которым необходимы расширенные возможности экспорта данных Abaqus для 3D-печати и обмена данными CAD.","ar":"مثالي للوكلاء الهندسيين الذين يحتاجون إلى إمكانيات متقدمة لتصدير بيانات Abaqus لطباعة 3D وتبادل CAD."},"recommendation":{"en":"Empowers agents to export geometry and results from Abaqus to external formats like STL, STEP, and CSV, facilitating seamless data analysis, archival, and exchange using Abaqus INP files and mesh data.","zh":"赋予代理以从Abaqus导出几何形状和结果到外部格式，如STL、STEP和CSV的能力，实现无缝的数据分析、存档和交换，使用Abaqus INP文件和网格数据。","ja":"エージェントにAbaqusから外部形式（STL、STEP、CSVなど）への幾何学的形状と結果のエクスポート機能を提供し、Abaqus INPファイルとメッシュデータを使用してシームレスなデータ分析、保管、交換を実現します。","ko":"에이전트가 Abaqus에서 STL, STEP 및 CSV와 같은 외부 형식으로 기하학적 모양과 결과를 내보내는 기능을 제공하여 Abaqus INP 파일 및 메시 데이터를 사용한 무결점 데이터 분석, 보관 및 교환을 가능하게 합니다.","es":"Permite a los agentes exportar geometría y resultados de Abaqus a formatos externos como STL, STEP y CSV, facilitando un análisis, archivo y intercambio de datos sin problemas utilizando archivos Abaqus INP y datos de malla.","fr":"Permet aux agents d''exporter la géométrie et les résultats d''Abaqus vers des formats externes tels que STL, STEP et CSV, facilitant ainsi l''analyse, l''archivage et l''échange de données sans problème à l''aide de fichiers Abaqus INP et de données de maillage.","de":"Ermöglicht es Agents, Geometrie und Ergebnisse aus Abaqus in externe Formate wie STL, STEP und CSV zu exportieren, wodurch eine nahtlose Datenanalyse, Archivierung und den Austausch mithilfe von Abaqus-INP-Dateien und Mesh-Daten ermöglicht wird.","pt":"Habilita os agentes a exportar geometria e resultados do Abaqus para formatos externos como STL, STEP e CSV, facilitando a análise, arquivamento e troca de dados sem problemas usando arquivos Abaqus INP e dados de malha.","ru":"Наделяет агентов возможностью экспортировать геометрию и результаты Abaqus в внешние форматы, такие как STL, STEP и CSV, обеспечивая беспрепятственную анализ, архивирование и обмен данными с использованием файлов Abaqus INP и сеточных данных.","ar":"تمكّن الوكلاء من تصدير الهندسة والنتائج من Abaqus إلى صيغ خارجية مثل STL و STEP و CSV، مما يسهل تحليل البيانات وترشيحها وتبادلها بدون مشاكل باستخدام ملفات Abaqus INP وبيانات الشبكة."},"useCases":{"en":["Exporting deformed shapes for topology analysis","Generating input files for 3D printing","Converting Abaqus results to Excel for data visualization"],"zh":["导出变形形状进行拓扑分析","生成3D打印的输入文件","将Abaqus结果转换为Excel进行数据可视化"],"ja":["トポロジー分析のための変形形状のエクスポート","3Dプリンティングの入力ファイルの生成","Abaqusの結果をExcelに変換してデータを視覚化"],"ko":["拓扑 분석을 위한 변형된 모양 내보내기","3D 프린팅을 위한 입력 파일 생성","데이터 시각화를 위한 Abaqus 결과를 Excel로 변환"],"es":["Exportar formas deformadas para análisis de topología","Generar archivos de entrada para impresión 3D","Convertir resultados de Abaqus a Excel para visualización de datos"],"fr":["Exporter des formes déformées pour l''analyse de topologie","Générer des fichiers d''entrée pour l''impression 3D","Convertir les résultats d''Abaqus en Excel pour la visualisation de données"],"de":["Deformierte Formen für Topologieanalysen exportieren","Eingabedateien für 3D-Druck generieren","Abaqus-Ergebnisse in Excel für Datenvisualisierung umwandeln"],"pt":["Exportar formas deformadas para análise de topologia","Gerar arquivos de entrada para impressão 3D","Converter resultados Abaqus para Excel para visualização de dados"],"ru":["Экспорт деформированных форм для топологического анализа","Генерация входных файлов для 3D-печати","Преобразование результатов Abaqus в Excel для визуализации данных"],"ar":["تصدير الأشكال المشوهة لتحليل الطبوغرافيا","إنشاء ملفات الإدخال لطباعة 3D","تحويل نتائج Abaqus إلى Excel للرؤية البيانية للبيانات"]},"limitations":{"en":["Requires Abaqus software installation","Limited to Abaqus-compatible file formats"],"zh":["需要安装Abaqus软件","仅限于Abaqus兼容的文件格式"],"ja":["Abaqusソフトウェアのインストールが必要","Abaqusと互換性のあるファイル形式に限定される"],"ko":["Abaqus 소프트웨어 설치가 필요함","Abaqus와 호환되는 파일 형식으로 제한됨"],"es":["Requiere instalación de software Abaqus","Limitado a formatos de archivo compatibles con Abaqus"],"fr":["Nécessite l''installation du logiciel Abaqus","Limité aux formats de fichiers compatibles Abaqus"],"de":["Benötigt Abaqus-Software-Installation","Begrenzt auf Abaqus-kompatible Dateiformate"],"pt":["Requer instalação do software Abaqus","Limitado a formatos de arquivo compatíveis com Abaqus"],"ru":["Требуется установка программного обеспечения Abaqus","Ограничен форматами файлов, совместимыми с Abaqus"],"ar":["يحتاج إلى تثبيت برنامج Abaqus","محدود بالصيغ الملفية المتوافقة مع Abaqus"]},"version":4},"contentHash":"2800605475e72f4f9e218ea80111b77034ae33dbdeeafde668ca7fc1310ae6d0","qualityScore":44}');
DELETE FROM skills_fts WHERE id = 'JaimeCernuda/abaqus-scripting/abaqus-export';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JaimeCernuda/abaqus-scripting/abaqus-export', 'abaqus-export', 'JaimeCernuda', 'abaqus-scripting', 'community', 'abaqus-export JaimeCernuda abaqus-scripting community The Abaqus-Export skill enables the export of geometry and results from Abaqus to external formats, benefiting developers and engineers working with 3D printing, CAD exchange, and data analysis. Abaqus导出技能允许用户导出几何体和结果到外部格式，用于3D打印、CAD交换、数据分析或存档 Abaqusエクスポートスキルは、ユーザーが3Dプリンティング、CAD交換、データ分析、または保存のために外部形式で幾何学と結果をエクスポートできるようにします Abaqus导出스킬은 사용자가 3D 프린팅, CAD 교환, 데이터 분석 또는 보관을 위해 외부 형식에서 기하학 및 결과를导出 할 수 있습니다 Abaqus Export es una habilidad que permite exportar geometrías y resultados de Abaqus a formatos externos para impresión 3D, intercambio de CAD y análisis de datos Abaqus Export est une compétence qui permet d''exporter des géométries et des résultats Abaqus vers des formats externes pour l''impression 3D, l''échange de CAD et l''analyse de données Abaqus Export ist eine Fähigkeit, die das Exportieren von Geometrien und Ergebnissen von Abaqus in externe Formate für 3D-Druck, CAD-Austausch und Datenanalyse ermöglicht O Abaqus Export é uma habilidade que permite exportar geometrias e resultados do Abaqus para formatos externos para impressão 3D, troca de CAD e análise de dados ИИ Агент Abaqus Export позволяет экспортировать геометрии и результаты из Abaqus в внешние форматы для 3D-печати, обмена CAD и анализа данных يسمح Abaqus Export بتصدير الهندسة و النتائج من Abaqus إلى صيغ خارجية لطباعة 3D و تبادل CAD و تحليل البيانات how to use abaqus-export abaqus-export alternative abaqus-export setup guide what is abaqus-export abaqus-export vs other CAD tools abaqus-export install abaqus-export for 3D printing abaqus-export for CAD exchange abaqus-export tutorial Abaqus导出 3D打印 CAD交换 数据分析 存档 STL格式 CSV格式 Excel格式 INP文件 网格数据 Exports geometry to STL format for 3D printing Converts data to STEP format for CAD exchange Generates input files in INP format Exports results to CSV format for data analysis Saves mesh data for further processing Exports deformed shape and topology results Abaqus-export is a skill that allows users to export Abaqus data to various formats, including STL, STEP, and CSV, for applications such as 3D printing and CAD exchange.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wjyugutou/study-test-demo/vite', 'community', 'wjyugutou', 'study-test-demo', 'wjyugutou/study-test-demo', 'vite', 0, 0, 44, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:25.229Z', '3cb7a75336e338faa9be15dd8b97479721ac8ceac6f1ff4061c9b9eefccd9983', '{"id":"wjyugutou/study-test-demo/vite","name":"vite","description":{"en":"Vite is a next-generation frontend build tool that provides fast dev server and optimized production builds for developers. It uses Rolldown bundler and Oxc transformer.","zh":"Vite 是一个下一代前端构建工具，具有快速的开发服务器和优化的生产构建。它支持 TypeScript 和 ESM。","ja":"Vite は、高速な開発サーバーと最適化されたプロダクションビルドを備えた次世代のフロントエンドビルドツールです。TypeScript と ESM をサポートしています。","ko":"Vite는 빠른 개발 서버와 최적화된 프로덕션 빌드를 제공하는 차세대 프론트엔드 빌드 도구입니다. TypeScript와 ESM를 지원합니다.","es":"Vite es una herramienta de construcción de frontend de próxima generación con un servidor de desarrollo rápido y compilaciones de producción optimizadas. Aprende a configurar Vite con TypeScript y ESM","fr":"Vite est un outil de construction de frontend de nouvelle génération avec un serveur de développement rapide et des compilations de production optimisées. Découvrez comment configurer Vite avec TypeScript et ESM","de":"Vite ist ein Frontend-Build-Tool der nächsten Generation mit einem schnellen Entwicklungsserver und optimierten Produktionsbuilds. Erfahren Sie, wie Sie Vite mit TypeScript und ESM konfigurieren","pt":"O Vite é uma ferramenta de build frontend de próxima geração com servidor de desenvolvimento rápido e builds de produção otimizados.","ru":"Vite — это инструмент frontend-билда нового поколения с быстрым сервером разработки и оптимизированными производственными билдами.","ar":"أداة Vite هي أداة بناء الواجهة الأمامية من الجيل التالي مع خادم تطوير سريع وبناء إنتاج محسّن."},"seo":{"title":{"en":"Vite: Next-Gen Frontend Build Setup Guide | AI Agent Skill","zh":"Vite Setup Guide: 快速构建和优化前端项目","ja":"Vite ベストプラクティス:高速な開発サーバーと最適化されたプロダクションビルド","ko":"Vite 설정 가이드: 빠른 프론트엔드 빌드와 최적화","es":"Guía de configuración de Vite: Mejores prácticas para des...","fr":"Guide de configuration de Vite: Bonnes pratiques pour les...","de":"Vite-Konfigurationsleitfaden: Best Practices für Entwickler","pt":"Guia de Configuração Vite: Otimizando Builds Frontend","ru":"ИИ Агенты: Vite Настройка и Лучшие Практики","ar":"إعداد أداة Vite: دليل بناء الواجهة الأمامية"},"description":{"en":"Unlock fast dev server and optimized production builds with Vite. Learn how to configure and use Vite for your next project now!","zh":"了解 Vite 的核心功能和配置选项，包括使用 TypeScript、ESM 和条件配置","ja":"Vite のコア機能と設定オプションを学びましょう。TypeScript、ESM、条件設定など","ko":"Vite의 핵심 기능과 설정 옵션을 알아보세요. TypeScript, ESM, 조건부 구성 등","es":"Aprende a configurar Vite con TypeScript y ESM para una experiencia de desarrollo más rápida y eficiente. Descubre las mejores prácticas para producción y de...","fr":"Découvrez comment configurer Vite avec TypeScript et ESM pour une expérience de développement plus rapide et plus efficace. Apprenez les meilleures pratiques...","de":"Erfahren Sie, wie Sie Vite mit TypeScript und ESM konfigurieren, um eine schnellere und effizientere Entwicklungserfahrung zu ermöglichen. Entdecken Sie die ...","pt":"Aprenda a configurar o Vite para builds frontend rápidos e otimizados. Descubra as melhores práticas para usar o Vite com TypeScript e ESM.","ru":"Узнайте, как настроить Vite для быстрого и оптимизированного frontend-билда. Откройте для себя лучшие практики использования Vite с TypeScript и ESM.","ar":"تعلم كيفية إعداد أداة Vite لبناء الواجهة الأمامية السريع والمحسّن. اكتشف أفضل الممارسات لاستخدام Vite مع TypeScript و ESM."},"definition":{"en":"Vite is a next-generation frontend build tool with fast dev server and optimized production builds","zh":"Vite 是一个基于 Rolldown bundles 和 Oxc transformer 的前端构建工具","ja":"Vite は、Rolldown bundles と Oxc transformer を基盤とするフロントエンドビルドツールです","ko":"Vite는 Rolldown bundles와 Oxc transformer를 기반으로 하는 프론트엔드 빌드 도구입니다","es":"Vite es una herramienta de construcción de frontend que utiliza Rolldown bundler y Oxc transformer para ofrecer un servidor de desarrollo rápido y compilaciones de producción optimizadas","fr":"Vite est un outil de construction de frontend qui utilise Rolldown bundler et Oxc transformer pour offrir un serveur de développement rapide et des compilations de production optimisées","de":"Vite ist ein Frontend-Build-Tool, das Rolldown bundler und Oxc transformer verwendet, um einen schnellen Entwicklungsserver und optimierte Produktionsbuilds zu bieten","pt":"O Vite é uma ferramenta de build frontend que utiliza Rolldown bundler e Oxc transformer para builds rápidos e otimizados.","ru":"Vite — это инструмент frontend-билда, который использует Rolldown bundler и Oxc transformer для быстрого и оптимизированного билда.","ar":"أداة Vite هي أداة بناء الواجهة الأمامية التي تستخدم Rolldown bundler و Oxc transformer لبناء سريع ومحسّن."},"features":{"en":["Uses Rolldown bundler for optimized builds","Employs Oxc transformer for efficient code transformation","Supports native ESM and HMR for fast dev server","Allows configuration via `vite.config.ts` and `defineConfig`","Supports conditional configs and `loadEnv` for flexible build processes"],"zh":["快速的开发服务器（native ESM + HMR）","优化的生产构建","支持 TypeScript 和 ESM","条件配置和环境变量加载","使用 Rolldown bundles 和 Oxc transformer"],"ja":["高速な開発サーバー（native ESM + HMR）","最適化されたプロダクションビルド","TypeScript と ESM のサポート","条件設定と環境変数のロード","Rolldown bundles と Oxc transformer の使用"],"ko":["빠른 개발 서버（native ESM + HMR）","최적화된 프로덕션 빌드","TypeScript와 ESM 지원","조건부 구성과 환경 변수 로드","Rolldown bundles와 Oxc transformer 사용"],"es":["Soporte para TypeScript","Uso de ESM (ECMAScript Modules) en lugar de CommonJS","Servidor de desarrollo rápido con recarga en caliente (HMR)","Compilaciones de producción optimizadas","Compatibilidad con configuraciones condicionales","Uso de la función defineConfig para la configuración"],"fr":["Prise en charge de TypeScript","Utilisation d''ESM (ECMAScript Modules) au lieu de CommonJS","Serveur de développement rapide avec rechargement à chaud (HMR)","Compilations de production optimisées","Compatibilité avec des configurations conditionnelles","Utilisation de la fonction defineConfig pour la configuration"],"de":["Unterstützung für TypeScript","Verwendung von ESM (ECMAScript Modules) anstelle von CommonJS","Schneller Entwicklungsserver mit Hot-Reload (HMR)","Optimierte Produktionsbuilds","Kompatibilität mit bedingten Konfigurationen","Verwendung der Funktion defineConfig für die Konfiguration"],"pt":["Suporte a TypeScript com vite.config.ts","Uso de ESM em vez de CommonJS","Servidor de desenvolvimento rápido com HMR","Builds de produção otimizados com Rolldown bundler","Suporte a configurações condicionais com defineConfig"],"ru":["Поддержка TypeScript с vite.config.ts","Использование ESM вместо CommonJS","Быстрый сервер разработки с HMR","Оптимизированные производственные билды с Rolldown bundler","Поддержка условных конфигураций с defineConfig"],"ar":["دعم TypeScript مع vite.config.ts","استخدام ESM بدلاً من CommonJS","خادم تطوير سريع مع HMR","بناء إنتاج محسّن مع Rolldown bundler","دعم التكوين الشرطي مع defineConfig"]},"keywords":{"en":["how to use vite","vite setup guide","vite alternative","vite vs webpack","vite install","what is vite","vite config ts","vite frontend build tool"],"zh":["Vite","前端构建工具","TypeScript","ESM","Rolldown bundles","Oxc transformer","快速开发服务器","优化生产构建"],"ja":["Vite","フロントエンドビルドツール","TypeScript","ESM","Rolldown bundles","Oxc transformer","高速な開発サーバー","最適化されたプロダクションビルド"],"ko":["Vite","프론트엔드 빌드 도구","TypeScript","ESM","Rolldown bundles","Oxc transformer","빠른 개발 서버","최적화된 프로덕션 빌드"],"es":["Vite","TypeScript","ESM","CommonJS","Herramientas de construcción de frontend","Desarrollo web","Compilaciones de producción","Servidor de desarrollo rápido","Configuración de Vite"],"fr":["Vite","TypeScript","ESM","CommonJS","Outils de construction de frontend","Développement web","Compilations de production","Serveur de développement rapide","Configuration de Vite"],"de":["Vite","TypeScript","ESM","CommonJS","Frontend-Build-Tools","Webentwicklung","Produktionsbuilds","Schneller Entwicklungsserver","Vite-Konfiguration"],"pt":["vite configuração","vite frontend build","vite typescript","vite esm","vite rolldown bundler","vite oxc transformer","vite servidor de desenvolvimento","vite builds de produção"],"ru":["vite настройка","vite frontend-билд","vite typescript","vite esm","vite rolldown bundler","vite oxc transformer","vite сервер разработки","vite производственные билды"],"ar":["إعداد أداة Vite","بناء الواجهة الأمامية مع Vite","Vite و TypeScript","Vite و ESM","Vite و Rolldown bundler","Vite و Oxc transformer","خادم تطوير Vite","بناء إنتاج Vite"]}},"owner":"wjyugutou","repo":"study-test-demo","repoPath":"wjyugutou/study-test-demo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"vite","description":"Vite build tool configuration, plugin API, SSR, and Vite 8 Rolldown migration. Use when working with Vite projects, vite.config.ts, Vite plugins, or building libraries/SSR apps with Vite.","version":"2026.1.31","bodyPreview":"# Vite\n\n> Based on Vite 8 beta (Rolldown-powered). Vite 8 uses Rolldown bundler and Oxc transformer.\n\nVite is a next-generation frontend build tool with fast dev server (native ESM + HMR) and optimized production builds.\n\n## Preferences\n\n- Use TypeScript: prefer `vite.config.ts`\n- Always use ESM, avoid CommonJS\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | `vite.config.ts`, `defineConfig`, conditional configs, `loadEnv` | [core-config](refere","body":"# Vite\n\n> Based on Vite 8 beta (Rolldown-powered). Vite 8 uses Rolldown bundler and Oxc transformer.\n\nVite is a next-generation frontend build tool with fast dev server (native ESM + HMR) and optimized production builds.\n\n## Preferences\n\n- Use TypeScript: prefer `vite.config.ts`\n- Always use ESM, avoid CommonJS\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | `vite.config.ts`, `defineConfig`, conditional configs, `loadEnv` | [core-config](references/core-config.md) |\n| Features | `import.meta.glob`, asset queries (`?raw`, `?url`), `import.meta.env`, HMR API | [core-features](references/core-features.md) |\n| Plugin API | Vite-specific hooks, virtual modules, plugin ordering | [core-plugin-api](references/core-plugin-api.md) |\n\n## Build & SSR\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Build & SSR | Library mode, SSR middleware mode, `ssrLoadModule`, JavaScript API | [build-and-ssr](references/build-and-ssr.md) |\n\n## Advanced\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Environment API | Vite 6+ multi-environment support, custom runtimes | [environment-api](references/environment-api.md) |\n| Rolldown Migration | Vite 8 changes: Rolldown bundler, Oxc transformer, config migration | [rolldown-migration](references/rolldown-migration.md) |\n\n## Quick Reference\n\n### CLI Commands\n\n```bash\nvite              # Start dev server\nvite build        # Production build\nvite preview      # Preview production build\nvite build --ssr  # SSR build\n```\n\n### Common Config\n\n```ts\nimport { defineConfig } from ''vite''\n\nexport default defineConfig({\n  plugins: [],\n  resolve: { alias: { ''@'': ''/src'' } },\n  server: { port: 3000, proxy: { ''/api'': ''http://localhost:8080'' } },\n  build: { target: ''esnext'', outDir: ''dist'' },\n})\n```\n\n### Official Plugins\n\n- `@vitejs/plugin-vue` - Vue 3 SFC support\n- `@vitejs/plugin-vue-jsx` - Vue 3 JSX\n- `@vitejs/plugin-react` - React with Oxc/Babel\n- `@vitejs/plugin-react-swc` - React with SWC\n- `@vitejs/plugin-legacy` - Legacy browser support\n"},"lastSynced":"2026-03-08T02:04:25.229Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing fast and optimized build tools with native ESM and HMR support.","zh":"非常适合需要快速和优化的构建工具的前端代理，具有原生ESM和HMR支持。","ja":"フロントエンドエージェントが高速で最適化されたビルドツールを必要とする場合に最適です。ネイティブのESMとHMRをサポートしています。","ko":"프론트엔드 에이전트가 빠르고 최적화된 빌드 도구가 필요한 경우에 적합합니다. 네이티브 ESM 및 HMR를 지원합니다.","es":"Perfecto para agentes Frontend que necesitan herramientas de construcción rápidas y optimizadas con soporte nativo para ESM y HMR.","fr":"Parfait pour les agents Frontend ayant besoin d''outils de construction rapides et optimisés avec un support natif pour ESM et HMR.","de":"Perfekt für Frontend-Agents, die schnelle und optimierte Build-Tools mit nativem ESM- und HMR-Unterstützung benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de ferramentas de compilação rápidas e otimizadas com suporte nativo a ESM e HMR.","ru":"Идеально для Фронтенд-агентов, которым необходимы быстрые и оптимизированные инструменты сборки с родной поддержкой ESM и HMR.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى أدوات بناء سريعة ومثالية مع دعم أصلي لـ ESM و HMR."},"recommendation":{"en":"Empowers agents to create fast dev servers and optimized production builds using Rolldown bundler and Oxc transformer, with support for TypeScript and conditional configurations via `vite.config.ts` and `defineConfig`.","zh":"赋予代理创建快速开发服务器和优化的生产构建的能力，使用Rolldown bundler和Oxc transformer，支持TypeScript和通过`vite.config.ts`和`defineConfig`进行条件配置。","ja":"RolldownバンドラーとOxcトランスフォーマーを使用して、TypeScriptと`vite.config.ts`および`defineConfig`による条件構成をサポートし、高速な開発サーバーと最適化されたプロダクションビルドを作成するエージェントの能力を提供します。","ko":"Rolldown 번들러와 Oxc 변환기를 사용하여 TypeScript 및 `vite.config.ts`와 `defineConfig`를 통해 조건부 구성이 가능하며, 빠른 개발 서버 및 최적화된 프로덕션 빌드를 생성할 수 있는 에이전트의 능력을 제공합니다.","es":"Habilita a los agentes a crear servidores de desarrollo rápidos y compilaciones de producción optimizadas utilizando el empacador Rolldown y el transformador Oxc, con soporte para TypeScript y configuraciones condicionales a través de `vite.config.ts` y `defineConfig`.","fr":"Permet aux agents de créer des serveurs de développement rapides et des compilations de production optimisées en utilisant le bundleur Rolldown et le transformateur Oxc, avec un support pour TypeScript et des configurations conditionnelles via `vite.config.ts` et `defineConfig`.","de":"Ermächtigt Agents, schnelle Entwicklungsserver und optimierte Produktionsbuilds mit dem Rolldown-Bundler und dem Oxc-Transformer zu erstellen, mit Unterstützung für TypeScript und bedingte Konfigurationen über `vite.config.ts` und `defineConfig`.","pt":"Habilita os agentes a criar servidores de desenvolvimento rápidos e compilações de produção otimizadas usando o empacotador Rolldown e o transformador Oxc, com suporte para TypeScript e configurações condicionais via `vite.config.ts` e `defineConfig`.","ru":"Наделяет агентов возможностью создавать быстрые серверы разработки и оптимизированные сборки производства с помощью пакетировщика Rolldown и трансформатора Oxc, с поддержкой TypeScript и условных конфигураций через `vite.config.ts` и `defineConfig`.","ar":"يمكن الوكلاء من إنشاء خوادم تطوير سريعة وعمليات بناء إنتاج مثالية باستخدام حزمة Rolldown ومحول Oxc ، مع دعم TypeScript والتنفيذ الشرطي عبر `vite.config.ts` و `defineConfig`."},"useCases":{"en":["Configuring Vite for fast and optimized frontend builds","Generating production-ready code with native ESM and HMR","Debugging frontend issues with Vite''s fast dev server"],"zh":["为Vite配置快速和优化的前端构建","使用原生ESM和HMR生成生产就绪代码","使用Vite的快速开发服务器调试前端问题"],"ja":["Viteの高速で最適化されたフロントエンドビルドを構成する","ネイティブのESMとHMRを使用してプロダクションレディのコードを生成する","Viteの高速開発サーバーを使用してフロントエンドの問題をデバッグする"],"ko":["Vite에 빠르고 최적화된 프론트엔드 빌드를 구성하는 것","네이티브 ESM 및 HMR를 사용하여 프로덕션 레디 코드를 생성하는 것","Vite의 빠른 개발 서버를 사용하여 프론트엔드 문제를 디버깅하는 것"],"es":["Configuración de Vite para compilaciones de frontend rápidas y optimizadas","Generación de código listo para producción con ESM y HMR nativos","Depuración de problemas de frontend con el servidor de desarrollo rápido de Vite"],"fr":["Configuration de Vite pour des compilations de frontend rapides et optimisées","Génération de code prêt pour la production avec ESM et HMR natifs","Débogage des problèmes de frontend avec le serveur de développement rapide de Vite"],"de":["Konfiguration von Vite für schnelle und optimierte Frontend-Builds","Erzeugung von produktionsbereitem Code mit nativem ESM und HMR","Fehlerbehebung von Frontend-Problemen mit dem schnellen Entwicklungsserver von Vite"],"pt":["Configurando Vite para compilações de frontend rápidas e otimizadas","Gerando código pronto para produção com ESM e HMR nativos","Depurando problemas de frontend com o servidor de desenvolvimento rápido do Vite"],"ru":["Настройка Vite для быстрых и оптимизированных сборок фронтенда","Генерация кода, готового для производства с родными ESM и HMR","Отладка проблем фронтенда с помощью быстрого сервера разработки Vite"],"ar":["تكوين Vite لعمليات بناء واجهة المستخدم السريعة والمثالية","توليد رمز جاهز للإنتاج مع دعم أصلي لـ ESM و HMR","تصحيح أخطاء واجهة المستخدم باستخدام خادم التطوير السريع في Vite"]},"limitations":{"en":["Requires TypeScript for preferred configuration","Always uses ESM, avoiding CommonJS","Dependent on Rolldown bundler and Oxc transformer"],"zh":["需要TypeScript进行首选配置","始终使用ESM，避免CommonJS","依赖于Rolldown bundler和Oxc transformer"],"ja":["優先構成にはTypeScriptが必要","常にESMを使用し、CommonJSを回避する","RolldownバンドラーとOxcトランスフォーマーに依存する"],"ko":["선호하는 구성에는 TypeScript가 필요합니다","항상 ESM을 사용하고 CommonJS를 피함","Rolldown 번들러와 Oxc 변환기에 의존"],"es":["Requiere TypeScript para la configuración preferida","Siempre utiliza ESM, evitando CommonJS","Dependiente del empacador Rolldown y del transformador Oxc"],"fr":["Nécessite TypeScript pour la configuration préférée","Utilise toujours ESM, évitant CommonJS","Dépendant du bundleur Rolldown et du transformateur Oxc"],"de":["Benötigt TypeScript für die bevorzugte Konfiguration","Verwendet immer ESM, vermeidet CommonJS","Abhängig vom Rolldown-Bundler und dem Oxc-Transformer"],"pt":["Exige TypeScript para configuração preferida","Sempre usa ESM, evitando CommonJS","Dependente do empacotador Rolldown e do transformador Oxc"],"ru":["Требует TypeScript для предпочитаемой конфигурации","Всегда использует ESM, избегая CommonJS","Зависит от пакетировщика Rolldown и трансформатора Oxc"],"ar":["يتطلب TypeScript للتنفيذ المفضل","دائمًا ما يستخدم ESM ، وتجنب CommonJS","يعتمد على حزمة Rolldown ومحول Oxc"]},"version":4},"contentHash":"3cb7a75336e338faa9be15dd8b97479721ac8ceac6f1ff4061c9b9eefccd9983","qualityScore":44}');
