INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wjyugutou/study-test-demo/vite', 'vite', 'wjyugutou', 'study-test-demo', 'community', 'vite wjyugutou study-test-demo community Vite is a next-generation frontend build tool that provides fast dev server and optimized production builds for developers. It uses Rolldown bundler and Oxc transformer. Vite 是一个下一代前端构建工具，具有快速的开发服务器和优化的生产构建。它支持 TypeScript 和 ESM。 Vite は、高速な開発サーバーと最適化されたプロダクションビルドを備えた次世代のフロントエンドビルドツールです。TypeScript と ESM をサポートしています。 Vite는 빠른 개발 서버와 최적화된 프로덕션 빌드를 제공하는 차세대 프론트엔드 빌드 도구입니다. TypeScript와 ESM를 지원합니다. Vite es una herramienta de construcción de frontend de próxima generación con un servidor de desarrollo rápido y compilaciones de producción optimizadas. Aprende a configurar Vite con TypeScript y ESM Vite est un outil de construction de frontend de nouvelle génération avec un serveur de développement rapide et des compilations de production optimisées. Découvrez comment configurer Vite avec TypeScript et ESM Vite ist ein Frontend-Build-Tool der nächsten Generation mit einem schnellen Entwicklungsserver und optimierten Produktionsbuilds. Erfahren Sie, wie Sie Vite mit TypeScript und ESM konfigurieren O Vite é uma ferramenta de build frontend de próxima geração com servidor de desenvolvimento rápido e builds de produção otimizados. Vite — это инструмент frontend-билда нового поколения с быстрым сервером разработки и оптимизированными производственными билдами. أداة Vite هي أداة بناء الواجهة الأمامية من الجيل التالي مع خادم تطوير سريع وبناء إنتاج محسّن. how to use vite vite setup guide vite alternative vite vs webpack vite install what is vite vite config ts vite frontend build tool Vite 前端构建工具 TypeScript ESM Rolldown bundles Oxc transformer 快速开发服务器 优化生产构建 Uses Rolldown bundler for optimized builds Employs Oxc transformer for efficient code transformation Supports native ESM and HMR for fast dev server Allows configuration via `vite.config.ts` and `defineConfig` Supports conditional configs and `loadEnv` for flexible build processes Vite is a next-generation frontend build tool with fast dev server and optimized production builds');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('matsuni-kk/agent_template_public/agent-discovery', 'community', 'matsuni-kk', 'agent_template_public', 'matsuni-kk/agent_template_public', 'agent-discovery', 0, 0, 44, '2026-03-08T01:57:15.372Z', '2026-03-08T02:05:39.938Z', '627620de40aabeacd06a072cb419eaa9d1b3cd53a0f6a01d9833a19b1947c396', '{"id":"matsuni-kk/agent_template_public/agent-discovery","name":"agent-discovery","description":{"en":"The agent-discovery skill enables developers to generate domain-specific agents through a templated framework, streamlining the development process for AI agents. It benefits developers and organizations seeking to create customized agents for specific domains.","zh":"AI智能体发现框架是一个用于生成域特定AI智能体的模板框架，包括预检、生成和研究阶段","ja":"AIエージェントの発見ワークフローは、ドメイン特化エージェントの生成のためのテンプレートフレームワークです","ko":"AI 에이전트 발견 프레임워크는 도메인 특화 에이전트의 생성을 위한 템플릿 프레임워크입니다","es":"Agent-Discovery es un marco de trabajo para la generación de agentes específicos de dominio. Proporciona un flujo de trabajo de discovery para identificar requisitos y crear agentes personalizados","fr":"Agent-Discovery est un cadre de travail pour la génération d''agents spécifiques de domaine. Il fournit un flux de travail de discovery pour identifier les exigences et créer des agents personnalisés","de":"Agent-Discovery ist ein Rahmenwerk für die Erstellung von Domänen-spezifischen Agenten. Es bietet einen Discovery-Workflows, um Anforderungen zu identifizieren und benutzerdefinierte Agenten zu erstellen","pt":"O Agent-Discovery é um framework de modelo de agente para geração de agentes personalizados de IA. Ele fornece um fluxo de trabalho de descoberta para criar agentes de domínio específico.","ru":"Agent-Discovery - это фреймворк модели агента для генерации индивидуальных ИИ агентов. Он предоставляет рабочий процесс открытия для создания агентов конкретного домена.","ar":"العميل-اكتشاف هو إطار نموذج عميل لإنشاء عملاء ذكاء اصطناعي مخصصين. يقدم عملية اكتشاف لإنشاء عملاء مجال معين"},"seo":{"title":{"en":"agent-discovery: Domain-Specific Agent Generation Setup G...","zh":"AI智能体发现框架设置指南","ja":"AIエージェントの発見ワークフロー設定ガイド","ko":"AI 에이전트 발견 프레임워크 설정 가이드","es":"Guía de Configuración de Agent-Discovery para Generación ...","fr":"Guide de Configuration d''Agent-Discovery pour la Générati...","de":"Einrichtungsleitfaden für Agent-Discovery zur Erstellung ...","pt":"Guia de Configuração do Agent-Discovery para Ferramentas ...","ru":"Настройка ИИ Агентов с помощью Agent-Discovery: Руководство","ar":"دليل إعداد العميل-اكتشاف لادوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient agent development with agent-discovery. Discover how to generate domain-specific agents with our step-by-step guide and start building today!","zh":"了解AI智能体发现框架的设置步骤，包括预检、生成和研究阶段","ja":"AIエージェントの発見ワークフローを設定するためのステップバイステップガイド","ko":"AI 에이전트 발견 프레임워크 설정을 위한 단계별 가이드","es":"Descubre cómo configurar Agent-Discovery para crear agentes personalizados para tu dominio. Aprende sobre el flujo de trabajo de discovery y los requisitos n...","fr":"Découvrez comment configurer Agent-Discovery pour créer des agents personnalisés pour votre domaine. Apprenez sur le flux de travail de discovery et les exig...","de":"Erfahren Sie, wie Sie Agent-Discovery konfigurieren, um benutzerdefinierte Agenten für Ihr Domäne zu erstellen. Lernen Sie über den Discovery-Workflows und d...","pt":"Aprenda a configurar o Agent-Discovery para criar agentes personalizados de IA. Descubra como resolver problemas de domínio específico com nossa abordagem ba...","ru":"Узнайте, как настроить Agent-Discovery для создания индивидуальных ИИ агентов. Откройте для себя, как решать проблемы конкретного домена с нашей подходом на ...","ar":"تعلم كيفية إعداد العميل-اكتشاف لإنشاء عملاء ذكاء اصطناعي مخصصين. اكتشف كيفية حل مشاكل مجال معين باستخدام نهجنا القائم على الإطار"},"definition":{"en":"agent-discovery is a templated framework for generating domain-specific agents, facilitating the discovery phase of agent development with tools like discovery_checklist.md and framework_research.md.","zh":"AI智能体发现框架是一种用于生成AI智能体的模板框架","ja":"AIエージェントの発見ワークフローは、AIエージェントの生成のためのテンプレートフレームワークです","ko":"AI 에이전트 발견 프레임워크는 AI 에이전트의 생성을 위한 템플릿 프레임워크입니다","es":"Agent-Discovery es un marco de trabajo para la generación de agentes específicos de dominio que utiliza un flujo de trabajo de discovery para identificar requisitos","fr":"Agent-Discovery est un cadre de travail pour la génération d''agents spécifiques de domaine qui utilise un flux de travail de discovery pour identifier les exigences","de":"Agent-Discovery ist ein Rahmenwerk für die Erstellung von Domänen-spezifischen Agenten, das einen Discovery-Workflows verwendet, um Anforderungen zu identifizieren","pt":"O que é Agent-Discovery? É um framework de modelo de agente para geração de agentes de IA personalizados.","ru":"Что такое Agent-Discovery? Это фреймворк модели агента для генерации индивидуальных ИИ агентов.","ar":"ما هو العميل-اكتشاف؟ إنه إطار نموذج عميل لإنشاء عملاء ذكاء اصطناعي مخصصين"},"features":{"en":["Utilizes discovery_checklist.md for preflight checks","Supports industry-standard frameworks like BABOK and AMA","Generates draft_requirements.md and framework_research.md as key outputs","Collects domain information using discovery_questions.md","Enables collection of domain name, agent display name, and pain points"],"zh":["预检阶段：检查必須項目并收集業界标准フレームワーク","生成阶段：收集域名、解決したい課題、対象ユーザー等信息","研究阶段：調査対象ドメイン的業界标准フレームワーク","支持BABOK、AMA等業界标准フレームワーク","输出draft_requirements.md和framework_research.md文件"],"ja":["事前確認ステージ：必須項目を確認し、業界標準フレームワークを収集","生成ステージ：ドメイン名、解決したい課題、対象ユーザー等の情報を収集","研究ステージ：対象ドメインの業界標準フレームワークを調査","BABOK、AMA等の業界標準フレームワークをサポート","draft_requirements.mdとframework_research.mdファイルを出力"],"ko":["사전 확인 단계：필수 항목을 확인하고 산업 표준 프레임워크를 수집","생성 단계：도메인 이름, 해결하고자 하는 문제, 대상 사용자 등 정보를 수집","연구 단계：대상 도메인의 산업 표준 프레임워크를 조사","BABOK, AMA 등 산업 표준 프레임워크를 지원","draft_requirements.md와 framework_research.md 파일을 출력"],"es":["Flujo de trabajo de discovery para identificar requisitos","Creación de agentes personalizados para dominios específicos","Utilización de plantillas de preguntas para recopilar información","Generación de documentos de requisitos y investigación de marcos de trabajo","Compatibilidad con industrias estándar como BABOK y AMA","Soporte para la creación de agentes con funcionalidades específicas"],"fr":["Flux de travail de discovery pour identifier les exigences","Création d''agents personnalisés pour des domaines spécifiques","Utilisation de modèles de questions pour recueillir des informations","Génération de documents d''exigences et de recherche de cadres de travail","Compatibilité avec les industries standard comme BABOK et AMA","Prise en charge de la création d''agents avec des fonctionnalités spécifiques"],"de":["Discovery-Workflows zur Identifizierung von Anforderungen","Erstellung von benutzerdefinierten Agenten für spezifische Domänen","Verwendung von Fragenvorlagen zur Erfassung von Informationen","Erstellung von Anforderungsdokumenten und Rahmenwerkforschung","Kompatibilität mit Branchenstandards wie BABOK und AMA","Unterstützung für die Erstellung von Agenten mit spezifischen Funktionen"],"pt":["Fluxo de trabalho de descoberta para criar agentes de domínio específico","Suporte a frameworks de indústria padrão, como BABOK e AMA","Coleta de requisitos e pesquisa de framework","Definição de funcionalidades e cenários de utilização","Integração com tecnologias de IA e machine learning"],"ru":["Рабочий процесс открытия для создания агентов конкретного домена","Поддержка отраслевых стандартных фреймворков, таких как BABOK и AMA","Сбор требований и исследование фреймворка","Определение функциональности и сценариев использования","Интеграция с технологиями ИИ и машинного обучения"],"ar":["عملية اكتشاف لإنشاء عملاء مجال معين","دعم لإطارات صناعية قياسية، مثل BABOK و AMA","جمع متطلبات وأبحاث الإطار","تحديد الوظائف وسيناريوهات الاستخدام","التكامل مع تقنيات الذكاء الاصطناعي والتعلم الآلي"]},"keywords":{"en":["how to use agent-discovery","agent-discovery setup guide","domain-specific agent generation","agent-discovery vs traditional development","what is agent-discovery","agent-discovery install","agent-discovery framework","agent development workflow","customized AI agents"],"zh":["AI智能体发现框架","AI智能体生成","域特定AI智能体","预检阶段","生成阶段","研究阶段","BABOK","AMA"],"ja":["AIエージェントの発見ワークフロー","AIエージェントの生成","ドメイン特化エージェント","事前確認ステージ","生成ステージ","研究ステージ","BABOK","AMA"],"ko":["AI 에이전트 발견 프레임워크","AI 에이전트 생성","도메인 특화 에이전트","사전 확인 단계","생성 단계","연구 단계","BABOK","AMA"],"es":["agentes de AI","generación de agentes","dominios específicos","flujo de trabajo de discovery","creación de agentes personalizados","plantillas de preguntas","requisitos de dominio","investigación de marcos de trabajo","BABOK","AMA"],"fr":["agents d''IA","génération d''agents","domaines spécifiques","flux de travail de discovery","création d''agents personnalisés","modèles de questions","exigences de domaine","recherche de cadres de travail","BABOK","AMA"],"de":["KI-Agents","Erstellung von Agenten","spezifische Domänen","Discovery-Workflows","Erstellung von benutzerdefinierten Agenten","Fragenvorlagen","Anforderungen von Domänen","Rahmenwerkforschung","BABOK","AMA"],"pt":["agentes de IA","ferramentas de IA","framework de modelo de agente","descoberta de agentes","domínio específico","BABOK","AMA","machine learning"],"ru":["ИИ агенты","ИИ инструменты","фреймворк модели агента","открытие агентов","конкретный домен","BABOK","AMA","машинное обучение"],"ar":["عملاء الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","إطار نموذج عميل","اكتشاف العملاء","مجال معين","BABOK","AMA","التعلم الآلي"]}},"owner":"matsuni-kk","repo":"agent_template_public","repoPath":"matsuni-kk/agent_template_public","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"agent-discovery","description":"新規エージェント作成のためのヒアリング・要件定義を実施し、draft_requirements.mdとframework_research.mdを生成する。「エージェント作成」「新規Agent」「ヒアリング開始」を依頼されたときに使用する。","bodyPreview":"# Agent Discovery Workflow\n\n新規ドメイン特化エージェント作成のためのDiscoveryフェーズ。主成果物はdraft_requirements.mdとframework_research.md。\n\n## Instructions\n\n### 1. Preflight（事前確認）\n- `./assets/discovery_checklist.md` を先に読み、必須項目を確認する。\n- 対象ドメインの業界標準フレームワーク（BABOK、AMA等）をWeb検索で調査する。\n- 既存資料があれば収集し、参照元リンクと取得日時を記録する。\n- 確認できなかった資料は「未参照一覧」として明記する。\n\n### 2. 生成\n- `./questions/discovery_questions.md` に従い以下を収集する:\n  - ドメイン名（スネークケース）、エージェント表示名\n  - 解決したい課題・ペインポイント\n  - 対象ユーザー（ペルソナ）\n  - 期待成果・KPI・成功条件\n  - 必須機能（3-5個）、推奨機能、将来機能\n  - 利用シナリオ、成果物フォー","body":"# Agent Discovery Workflow\n\n新規ドメイン特化エージェント作成のためのDiscoveryフェーズ。主成果物はdraft_requirements.mdとframework_research.md。\n\n## Instructions\n\n### 1. Preflight（事前確認）\n- `./assets/discovery_checklist.md` を先に読み、必須項目を確認する。\n- 対象ドメインの業界標準フレームワーク（BABOK、AMA等）をWeb検索で調査する。\n- 既存資料があれば収集し、参照元リンクと取得日時を記録する。\n- 確認できなかった資料は「未参照一覧」として明記する。\n\n### 2. 生成\n- `./questions/discovery_questions.md` に従い以下を収集する:\n  - ドメイン名（スネークケース）、エージェント表示名\n  - 解決したい課題・ペインポイント\n  - 対象ユーザー（ペルソナ）\n  - 期待成果・KPI・成功条件\n  - 必須機能（3-5個）、推奨機能、将来機能\n  - 利用シナリオ、成果物フォーマット\n  - データソース・外部システム連携\n- `./assets/requirements_template.md` に従いdraft_requirements.mdを生成する。\n- `./assets/framework_research_template.md` に従いframework_research.mdを生成する。\n- 不確定事項はTODO形式で列挙し、合意時刻を明記する。\n- 元資料にない項目は省略せず「未記載」と明記する。\n\n### 3. 構造承認\n- Flow / Stock / Archived の初期構成を説明する。\n- エージェント要件とフォルダ設計についてユーザー承認を得る。\n- **承認が得られない場合は後続工程へ進まない。**\n\n### 4. QC（必須）\n- `recommended_subagents` のQC Subagent（`qa-skill-qc`）に評価を委譲する。\n- Subagentは `./evaluation/discovery_criteria.md` をReadし、QCを実施する。\n- 指摘を最小差分で反映する（最大3回）。\n- 指摘に対し「修正した/しない」と理由を成果物に残す。\n\n### 5. バックログ反映\n- タスクリスト（{{flow_day_dir}}/{{today}}_agent_creation_tasklist.md）を生成する。\n- 未決事項、次アクションをタスクリストへ追記する。\n- framework_research_done=true を記録してから次工程へ進む。\n\nsubagent_policy:\n  - 品質ループ（QC/チェック/フィードバック）は必ずサブエージェントへ委譲する\n  - サブエージェントの指摘を反映し、反映結果（修正有無/理由）を成果物に残す\n\nrecommended_subagents:\n  - qa-skill-qc: 必須項目網羅、曖昧表現、推測混入、業界標準整合、承認確認を検査\n\n## Resources\n- questions: ./questions/discovery_questions.md\n- assets: ./assets/discovery_checklist.md\n- assets: ./assets/requirements_template.md\n- assets: ./assets/framework_research_template.md\n- assets: ./assets/tasklist_template.md\n- evaluation: ./evaluation/discovery_criteria.md\n- triggers: ./triggers/next_action_triggers.md\n\n## Next Action\n- triggers: ./triggers/next_action_triggers.md\n\n起動条件に従い、条件を満たすSkillを自動実行する。\n"},"lastSynced":"2026-03-08T02:05:39.938Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing domain-specific templated frameworks for streamlined development.","zh":"非常适合需要特定领域模板框架以简化开发的 AI 代理。","ja":"ドメイン固有のテンプレートフレームワークを使用して開発を簡素化する必要がある AI エージェントに最適です。","ko":"개발을 간소화하기 위해 도메인별 템플릿 프레임워크가 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan frameworks de plantillas específicas de dominio para un desarrollo optimizado.","fr":"Parfait pour les agents IA ayant besoin de frameworks de modèles spécifiques de domaine pour un développement rationalisé.","de":"Perfekt für KI-Agents, die domänenspezifische Vorlagen-Frameworks für ein optimiertes Entwicklung benötigen.","pt":"Perfeito para Agentes de IA que necessitam de estruturas de template específicas de domínio para desenvolvimento simplificado.","ru":"Идеально подходит для агентов ИИ, которым требуются доменно-специфические шаблонные фреймворки для упрощенного развития.","ar":"مثالي لعمليات وكلاء الذكاء الاصطناعي الذين يحتاجون إلى إطارات مخصصة لمجال معين لتطوير بسط"},"recommendation":{"en":"Empowers agents to generate domain-specific requirements and framework research using templated discovery workflows, leveraging industry standards like BABOK and AMA, and producing draft requirements in Markdown format.","zh":"赋予代理生成特定领域的要求和框架研究使用模板化的发现工作流，利用行业标准如 BABOK 和 AMA，并以 Markdown 格式生成草稿要求。","ja":"エージェントが、BABOK や AMA などの業界標準を利用して、テンプレート化されたディスカバリーワークフローを使用してドメイン固有の要件とフレームワークの研究を生成し、Markdown 形式でドラフト要件を生成することを可能にします。","ko":"에이전트가 BABOK 및 AMA와 같은 산업 표준을 사용하여 템플릿화된 발견 워크플로를 통해 도메인별 요구 사항 및 프레임워크 연구를 생성하고 Markdown 형식으로 초안 요구 사항을 생성할 수 있도록 합니다.","es":"Habilita a los agentes a generar requisitos y investigaciones de framework específicas de dominio utilizando flujos de trabajo de descubrimiento con plantillas, aprovechando estándares de la industria como BABOK y AMA, y produciendo borradores de requisitos en formato Markdown.","fr":"Permet aux agents de générer des exigences et des recherches de framework spécifiques de domaine en utilisant des flux de travail de découverte avec des modèles, en exploitant les normes du secteur comme BABOK et AMA, et en produisant des brouillons d''exigences au format Markdown.","de":"Ermöglicht es Agents, domänenspezifische Anforderungen und Framework-Recherchen zu generieren, indem sie Arbeitsabläufe mit Vorlagen für die Entdeckung nutzen, Branchenstandards wie BABOK und AMA ausnutzen und Entwürfe von Anforderungen im Markdown-Format erstellen.","pt":"Habilita os agentes a gerar requisitos específicos de domínio e pesquisa de estruturas, utilizando fluxos de trabalho de descoberta com templates, aproveitando padrões da indústria como BABOK e AMA, e produzindo requisitos em draft no formato Markdown.","ru":"Наделяет агентов возможностью генерировать доменно-специфические требования и исследовать фреймворки с помощью шаблонных рабочих процессов открытия, используя отраслевые стандарты, такие как BABOK и AMA, и производя черновые требования в формате Markdown.","ar":"تمكّن الوكلاء من إنتاج متطلبات ومطالعات هيكلية محددة بالمجال باستخدام سير عمل اكتشاف معبأة، مستفيدة من معايير الصناعة مثل BABOK و AMA، وإنتاج مسودات المتطلبات بصيغة Markdown."},"useCases":{"en":["Automating discovery phases for new domain-specific agents","Generating draft requirements and framework research reports","Streamlining development workflows for customized AI agents"],"zh":["自动化新领域特定代理的发现阶段","生成领域特定要求和框架研究报告","为自定义 AI 代理简化开发工作流"],"ja":["新しいドメイン固有のエージェントのディスカバリーフェーズを自動化する","ドメイン固有の要件とフレームワークの研究報告を生成する","カスタマイズされた AI エージェントの開発ワークフローを簡素化する"],"ko":["새로운 도메인별 에이전트의 발견 단계 자동화","도메인별 요구 사항 및 프레임워크 연구 보고서 생성","사용자 지정 AI 에이전트의 개발 워크플ロー 간소화"],"es":["Automatizar las fases de descubrimiento para nuevos agentes específicos de dominio","Generar borradores de requisitos e informes de investigación de framework","Racionalizar los flujos de trabajo de desarrollo para agentes de IA personalizados"],"fr":["Automatiser les phases de découverte pour de nouveaux agents spécifiques de domaine","Générer des brouillons d''exigences et des rapports de recherche de framework","Rationaliser les flux de travail de développement pour des agents IA personnalisés"],"de":["Automatisieren der Entdeckungsphasen für neue domänenspezifische Agents","Erstellen von Entwürfen von Anforderungen und Framework-Recherchenberichten","Optimieren der Entwicklungswerkflüsse für maßgeschneiderte KI-Agents"],"pt":["Automatizar fases de descoberta para novos agentes específicos de domínio","Gerar relatórios de requisitos e pesquisas de estruturas em draft","Simplificar fluxos de trabalho de desenvolvimento para agentes de IA personalizados"],"ru":["Автоматизировать фазы открытия для новых доменно-специфических агентов","Генерировать черновые отчеты о требованиях и исследованиях фреймворков","Упрощать рабочие процессы разработки для индивидуальных агентов ИИ"],"ar":["تحسين مراحل الاكتشاف لأغراض وكلاء محددة بالمجال","إنتاج تقارير مسودة للمتطلبات وأبحاث الهياكل","تبسيط سير عمل التطوير لأنظمة الذكاء الاصطناعي المخصصة"]},"limitations":{"en":["Requires preflight checks and industry standard framework research","Limited to generating draft requirements and framework research reports","Needs access to relevant documentation and reference materials"],"zh":["需要进行预检和行业标准框架研究","仅限生成草稿要求和框架研究报告","需要访问相关文档和参考材料"],"ja":["プレフライトチェックと業界標準のフレームワークの研究が必要","ドラフト要件とフレームワークの研究報告を生成することのみ","関連するドキュメントと参考資料へのアクセスが必要"],"ko":["사전 점검 및 산업 표준 프레임워크 연구가 필요합니다","초안 요구 사항 및 프레임워크 연구 보고서 생성에만 제한됩니다","관련 문서 및 참고 자료에 대한 액세스가 필요합니다"],"es":["Requiere controles previos y investigación de framework de estándares de la industria","Limitado a la generación de borradores de requisitos e informes de investigación de framework","Necesita acceso a documentación y materiales de referencia relevantes"],"fr":["Nécessite des vérifications préalables et des recherches de framework de normes du secteur","Limité à la génération de brouillons d''exigences et de rapports de recherche de framework","Nécessite un accès à la documentation et aux matériaux de référence pertinents"],"de":["Erfordert Vorab-Checks und Branchenstandard-Framework-Recherchen","Begrenzt auf die Erstellung von Entwürfen von Anforderungen und Framework-Recherchenberichten","Benötigt Zugriff auf relevante Dokumentation und Referenzmaterialien"],"pt":["Requer verificações prévias e pesquisa de estruturas de acordo com os padrões da indústria","Limitado a gerar requisitos e relatórios de pesquisas de estruturas em draft","Necessita acesso a documentação e materiais de referência relevantes"],"ru":["Требует предварительных проверок и исследования фреймворков по отраслевым стандартам","Ограничен генерацией черновых требований и отчетов о исследованиях фреймворков","Требует доступа к соответствующей документации и справочным материалам"],"ar":["يتطلب فحصا مسبقا وبحوث هيكلية وفقا لمعايير الصناعة","محدود بالإنتاج المسودات للمتطلبات وتقارير أبحاث الهياكل","يحتاج إلى وصول إلى المستندات والمواد المرجعية ذات الصلة"]},"version":4},"contentHash":"627620de40aabeacd06a072cb419eaa9d1b3cd53a0f6a01d9833a19b1947c396","qualityScore":44}');
