INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deadronos/copilot-chat-playground/r3f-best-practices', 'r3f-best-practices', 'deadronos', 'copilot-chat-playground', 'community', 'r3f-best-practices deadronos copilot-chat-playground community The r3f-best-practices skill provides a comprehensive guide for React Three Fiber and the Poimandres ecosystem, covering 60+ rules across 11 categories. It helps developers optimize R3F performance and write efficient components. React Three Fiber 最佳实践指南，包含 60+ 条规则，帮助您优化性能和渲染 React Three Fiber ベストプラクティスガイド、60以上のルールを含み、パフォーマンスとレンダリングを最適化します React Three Fiber 최적화 가이드, 60개 이상의 규칙을 포함하여 성능과 렌더링을 개선합니다 Mejores prácticas para React Three Fiber, incluyendo optimización de rendimiento y guías para una integración perfecta con la ecología de Poimandres Meilleures pratiques pour React Three Fiber, y compris l''optimisation des performances et des guides pour une intégration parfaite avec l''écosystème Poimandres Best Practices für React Three Fiber, einschließlich Leistungsoptimierung und Anleitungen für eine perfekte Integration mit der Poimandres-Ökologie O r3f-best-practices é um guia abrangente para React Three Fiber e o ecossistema Poimandres, com 60+ regras em 11 categorias r3f-best-practices - это всесторонний гид по React Three Fiber и экосистеме Poimandres, содержащий 60+ правил в 11 категориях r3f-best-practices هو دليل شامل ل React Three Fiber وبيئة Poimandres، مع 60+ قاعدة في 11 فئة how to use r3f-best-practices what is r3f-best-practices r3f-best-practices alternative r3f-best-practices vs react-three r3f-best-practices install r3f-best-practices setup guide react three fiber optimization zustand state management drei helpers tutorial React Three Fiber Poimandres 最佳实践 性能优化 渲染优化 Zustand Drei helpers post-processing physics Provides 60+ rules across 11 categories for optimized React Three Fiber performance Covers best practices for writing new R3F components Includes guidelines for using Drei helpers correctly Offers tips for managing state with Zustand Supports implementation of post-processing or physics in R3F Covers the @react-three/fiber and @r ecosystems r3f-best-practices is a set of guidelines for React Three Fiber, providing best practices for writing efficient R3F components, optimizing performance, and managing state with Zustand.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CheekyCodexConjurer/aera-chart-engine/full_auth', 'community', 'CheekyCodexConjurer', 'aera-chart-engine', 'CheekyCodexConjurer/aera-chart-engine', 'full_auth', 0, 0, 44, '2026-03-08T01:57:15.388Z', '2026-03-08T02:05:57.646Z', 'e43530c3e7a567c8cc1a8269d2845fd015bddaccb9a0e564c4bce6bd7dc1983a', '{"id":"CheekyCodexConjurer/aera-chart-engine/full_auth","name":"full_auth","description":{"en":"full_auth enables AI agents to execute tasks end-to-end without interruptions, requiring explicit user permission to edit files. This skill benefits developers seeking to automate workflows efficiently.","zh":"Full Auth是AIエージェント的高级技能，实现无缝授权和PHASED PLAN的执行","ja":"Full AuthはAIエージェントの実行モードを最適化し、効率的なタスク完了を実現する","ko":"Full Auth는 AI 에이전트의 인증과 실행을 최적화하는 고급 스킬입니다","es":"full_auth es una habilidad que permite la autorización explícita para editar archivos y completar tareas de manera segura con agentes de IA. Se utiliza en modo de planificación por fases con ejecución inmediata.","fr":"full_auth est une compétence qui permet l''autorisation explicite pour éditer des fichiers et compléter des tâches de manière sécurisée avec les outils d''IA. Elle utilise un mode de planification par phases avec exécution immédiate.","de":"full_auth ist eine Fähigkeit, die die explizite Autorisierung zur Bearbeitung von Dateien und zum Abschließen von Aufgaben auf sichere Weise mit KI-Agents ermöglicht. Sie wird im Phasenplan-Modus mit sofortiger Ausführung verwendet.","pt":"O full_auth permite a automação de tarefas com permissão explícita, implementando planos faseados e executando comandos em sequência","ru":"Full_auth позволяет автоматизировать задачи с явным разрешением, реализуя фазовые планы и выполняя команды в последовательности","ar":"ال full_auth يتيح أتمتة المهام بالتصريح الصريح، وتنفيذ الخطط المرحلية وتنفيذ الأوامر بالتسلسل"},"seo":{"title":{"en":"full_auth: Phased Implementation Setup Guide | AI Agent S...","zh":"Full Auth Setup Guide: AIエージェント实现无缝授权","ja":"Full Auth ベストプラクティス: AIエージェントによる効率的な実行","ko":"Full Auth 사용자 가이드: AI 에이전트를 위한 완전한 인증","es":"full_auth: Guía de configuración para agentes de IA","fr":"full_auth: Guide de mise en place pour les outils d''IA","de":"full_auth: Einrichtungsleitfaden für KI-Agents","pt":"Guia de Configuração full_auth: Automação de Tarefas com ...","ru":"Полное руководство по настройке full_auth: Автоматизация ...","ar":"دليل إعداد full_auth: أتمتة المهام بالتصريح الكامل"},"description":{"en":"Unlock seamless task execution with full_auth! Discover how to grant explicit permissions and automate workflows without interruptions. Learn more and get st...","zh":"了解Full Auth的技术细节，包括PHASED PLAN和Blocking Rule，优化AIエージェント的执行","ja":"Full Authの実行モードとブロッキングルールをマスターし、AIエージェントのパフォーマンスを向上させる","ko":"Full Auth의 기술 세부 정보를 살펴보고, PHASED PLAN과 Blocking Rule을 사용하여 AI 에이전트의 성능을 최적화하세요","es":"Aprende a utilizar full_auth para autorizar edición de archivos y ejecución de tareas de manera segura con agentes de IA","fr":"Découvrez comment utiliser full_auth pour autoriser l''édition de fichiers et l''exécution de tâches de manière sécurisée avec les outils d''IA","de":"Erfahren Sie, wie Sie full_auth verwenden können, um die Bearbeitung von Dateien und die Ausführung von Aufgaben sicher mit KI-Agents durchzuführen","pt":"Aprenda a configurar o full_auth para automação de tarefas com permissão explícita. Descubra como implementar planos faseados e executar comandos sem interru...","ru":"Узнайте, как настроить full_auth для автоматизации задач с явным разрешением. Ознакомьтесь с реализацией фазовых планов и выполнением команд без прерывания","ar":"تعرف على كيفية إعداد full_auth لتنفيذ المهام تلقائيًا بالتصريح الصريح. اكتشف كيفية تنفيذ الخطط المرحلية وتنفيذ الأوامر دون انقطاع"},"definition":{"en":"full_auth is a skill that allows AI agents to perform phased implementation plans, executing all phases in sequence until completion, with explicit user permission.","zh":"Full Auth是AIエージェント的技能，用于实现无缝授权和PHASED PLAN的执行","ja":"Full AuthはAIエージェントの実行モードを最適化する技能","ko":"Full Auth는 AI 에이전트의 인증과 실행을 최적화하는 기술","es":"full_auth es una habilidad de agente de IA que autoriza la edición de archivos y la ejecución de tareas de manera segura","fr":"full_auth est une compétence d''outil d''IA qui autorise l''édition de fichiers et l''exécution de tâches de manière sécurisée","de":"full_auth ist eine Fähigkeit von KI-Agents, die die Bearbeitung von Dateien und die Ausführung von Aufgaben auf sichere Weise autorisiert","pt":"Full_auth é uma habilidade de agente de IA que permite a automação de tarefas com permissão explícita","ru":"Full_auth - это навык агента ИИ, позволяющий автоматизировать задачи с явным разрешением","ar":"ال full_auth هي مهارة لعميل الذكاء الاصطناعي التي تتيح أتمتة المهام بالتصريح الصريح"},"features":{"en":["Produces a phased implementation plan with multiple phases (Phase 1/2/3…)","Executes all phases in sequence in the same run, until Definition of Done is met","Pauses only when blocked by missing information or command failures","Requires explicit user permission to edit files and complete tasks","Supports autonomous resolution of command failures"],"zh":["PHASED PLAN的执行","Blocking Rule的支持","无缝授权和执行","AIエージェント的高级技能","Definition of Done的实现"],"ja":["PHASED PLANの実行","ブロッキングルールのサポート","無停止の認証と実行","AIエージェントの高級スキル","Definition of Doneの実現"],"ko":["PHASED PLAN의 실행","Blocking Rule의 지원","无중단 인증과 실행","AI 에이전트의 고급 스킬","Definition of Done의 달성"],"es":["Autorización explícita para editar archivos","Ejecución de tareas de manera segura con agentes de IA","Modo de planificación por fases con ejecución inmediata","Producción de un plan de implementación por fases","Ejecución de todas las fases en secuencia en la misma ejecución"],"fr":["Autorisation explicite pour éditer des fichiers","Exécution de tâches de manière sécurisée avec les outils d''IA","Mode de planification par phases avec exécution immédiate","Production d''un plan d''implémentation par phases","Exécution de toutes les phases en séquence dans la même exécution"],"de":["Explizite Autorisierung zur Bearbeitung von Dateien","Sichere Ausführung von Aufgaben mit KI-Agents","Phasenplan-Modus mit sofortiger Ausführung","Erstellung eines Phasenimplementierungsplans","Ausführung aller Phasen in Sequenz in der gleichen Ausführung"],"pt":["Automação de tarefas com permissão explícita","Implementação de planos faseados","Execução de comandos em sequência","Pause apenas em caso de falta de informação ou falha de comando","Integração com tecnologias de automação de tarefas","Suporte a execução de comandos CLI"],"ru":["Автоматизация задач с явным разрешением","Реализация фазовых планов","Выполнение команд в последовательности","Пауза только в случае отсутствия информации или неудачи команды","Интеграция с технологиями автоматизации задач","Поддержка выполнения команд CLI"],"ar":["أتمتة المهام بالتصريح الصريح","تنفيذ الخطط المرحلية","تنفيذ الأوامر بالتسلسل","الpause فقط في حالة عدم وجود معلومات أو فشل في الأمر","التكامل مع تقنيات أتمتة المهام","دعم تنفيذ أوامر CLI"]},"keywords":{"en":["how to use full_auth","full_auth alternative","full_auth setup guide","what is full_auth","full_auth vs other AI skills","full_auth install","phased implementation plan","automated workflow execution"],"zh":["AIエージェント","Full Auth","PHASED PLAN","Blocking Rule","无缝授权","AI工具","高级技能"],"ja":["AIエージェント","Full Auth","PHASED PLAN","ブロッキングルール","無停止の認証","AIツール","高級スキル"],"ko":["AI 에이전트","Full Auth","PHASED PLAN","Blocking Rule","无중단 인증","AI 도구","고급 스킬"],"es":["full_auth","agentes de IA","autorización explícita","edición de archivos","ejecución de tareas","planificación por fases","seguridad en IA","desarrollo de IA"],"fr":["full_auth","outils d''IA","autorisation explicite","édition de fichiers","exécution de tâches","planification par phases","sécurité en IA","développement d''IA"],"de":["full_auth","KI-Agents","explizite Autorisierung","Bearbeitung von Dateien","Ausführung von Aufgaben","Phasenplan-Modus","Sicherheit in KI","KI-Entwicklung"],"pt":["full_auth","automação de tarefas","permissão explícita","planos faseados","execução de comandos","CLI","agente de IA","ferramentas de automação","desenvolvimento de software","tecnologias de automação"],"ru":["full_auth","автоматизация задач","явное разрешение","фазовые планы","выполнение команд","CLI","агент ИИ","инструменты автоматизации","разработка программного обеспечения","технологии автоматизации"],"ar":["full_auth","أتمتة المهام","التصريح الصريح","الخطط المرحلية","تنفيذ الأوامر","CLI","عميل الذكاء الاصطناعي","أدوات أتمتة","تطوير البرمجيات","تقنيات أتمتة"]}},"owner":"CheekyCodexConjurer","repo":"aera-chart-engine","repoPath":"CheekyCodexConjurer/aera-chart-engine","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.388Z","topics":[],"category":"community","skillMd":{"name":"full_auth","description":"When explicitly authorized, execute end-to-end with a phased plan in one run until Definition of Done is met.","bodyPreview":"## Authorization\nUse this skill only when the user explicitly grants permission to edit files and\ncomplete the task end-to-end without asking “should I continue?”.\n\n## Execution Mode\nPHASED PLAN, ALL PHASES IN ONE RUN\n- Produce a phased implementation plan first (Phase 1/2/3…).\n- Immediately execute all phases in sequence in the same run, until Definition\n  of Done is met.\n- Only pause if blocked by missing info or if a command fails and cannot be\n  resolved autonomously.\n\n## Blocking Rule\nIf bl","body":"## Authorization\nUse this skill only when the user explicitly grants permission to edit files and\ncomplete the task end-to-end without asking “should I continue?”.\n\n## Execution Mode\nPHASED PLAN, ALL PHASES IN ONE RUN\n- Produce a phased implementation plan first (Phase 1/2/3…).\n- Immediately execute all phases in sequence in the same run, until Definition\n  of Done is met.\n- Only pause if blocked by missing info or if a command fails and cannot be\n  resolved autonomously.\n\n## Blocking Rule\nIf blocked, ask exactly one concise question that would unblock the work.\nOtherwise, keep going.\n\n## Definition of Done (generic)\n- Safety validation passes (respect `.agentignore`).\n- Use the best available repo verification:\n  - Prefer `.agent-docs/memory/COMMANDS.json` and `MANIFEST.yaml`.\n  - If missing, run capability/command detection and record confidence.\n  - Run tests, lint, and build as applicable.\n- If `QUALITY_GATES.md` exists, follow it as the source of truth.\n- Provide a final summary and list all modified/created files.\n\n## Output Requirements\n1) Investigation notes (what matters in the repo).\n2) Phased plan (Phase 1/2/3… with files and behaviors).\n3) Implementation (commit-style narrative by phase).\n4) Files changed + verification results (commands run and outcomes).\n\n## Guardrails\n- Always respect `.agentignore` forbidden zones.\n- Enforce Trust Layer TDD for behavior changes.\n- Keep an Action Ledger entry for meaningful work.\n"},"lastSynced":"2026-03-08T02:05:57.646Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring uninterrupted workflow execution and explicit user permission for file editing.","zh":"适用于需要无间断工作流执行和对文件编辑需要显式用户许可的自主代理。","ja":"中断されないワークフローの実行とファイルの編集に対する明示的なユーザーの許可を必要とする自律エージェントに適しています。","ko":"중단되지 않는 워크플로우 실행과 파일 편집에 대한 명시적 사용자 허가가 필요한 자율 에이전트에 적합합니다.","es":"Ideal para agentes autónomos que requieren una ejecución de flujo de trabajo ininterrumpida y un permiso de usuario explícito para la edición de archivos.","fr":"Idéal pour les agents autonomes nécessitant une exécution de flux de travail ininterrompue et un consentement explicite de l''utilisateur pour la modification de fichiers.","de":"Ideal für autonome Agenten, die eine unterbrechungsfreie Ausführung von Workflows und eine explizite Benutzererlaubnis für die Dateibearbeitung erfordern.","pt":"Ideal para Agentes Autônomos que requerem execução de fluxo de trabalho ininterrupta e permissão explícita do usuário para edição de arquivos.","ru":"Идеально для автономных агентов, требующих непрерывного выполнения рабочего процесса и явного разрешения пользователя на редактирование файлов.","ar":"مثالية للوكلاء الأوتوماتيكيين الذين يحتاجون إلى تنفيذ سير عمل غير متقطع و승락 صريح من المستخدم لتحرير الملفات."},"recommendation":{"en":"Empowers agents to execute tasks end-to-end without interruptions, utilizing PHASED PLAN execution mode and requiring explicit user permission to edit files, ensuring efficient automation of workflows with protocols like sequential phase execution and Definition of Done.","zh":"赋予代理执行任务的能力，从而在不中断的情况下完成任务，利用分阶段计划执行模式，并需要显式用户许可来编辑文件，确保工作流程的高效自动化，遵循顺序阶段执行和已完成定义等协议。","ja":"エージェントにタスクをエンドツーエンドで中断されずに実行する能力を付与し、PHASED PLAN実行モードを利用し、ファイルの編集には明示的なユーザーの許可を必要とし、シーケンシャルフェーズ実行やDefinition of Doneなどのプロトコルに従ったワークフローの自動化を効率的に行います。","ko":"에이전트가 작업을 중단 없이 종료에서 종료까지 실행할 수 있는 능력을 부여하여, 분阶段 계획 실행 모드를 활용하고 파일 편집에는 명시적인 사용자 허가를 필요로 하며, 시퀀셜 단계 실행 및 완료 정의 등과 같은 프로토콜에 따라 워크플로우의 자동화를 효율적으로 수행합니다.","es":"Habilita a los agentes a ejecutar tareas de principio a fin sin interrupciones, utilizando el modo de ejecución PHASED PLAN y requiriendo un permiso de usuario explícito para editar archivos, lo que garantiza una automatización eficiente de los flujos de trabajo con protocolos como la ejecución de fases secuenciales y la Definición de Hecho.","fr":"Permet aux agents d''exécuter des tâches de bout en bout sans interruptions, en utilisant le mode d''exécution PHASED PLAN et en nécessitant un consentement explicite de l''utilisateur pour modifier des fichiers, ce qui assure une automatisation efficace des flux de travail avec des protocoles tels que l''exécution de phases séquentielles et la Définition de Fait.","de":"Ermöglicht es Agenten, Aufgaben von Anfang bis Ende ohne Unterbrechungen auszuführen, indem sie den PHASED PLAN-Ausführungsmodus verwenden und eine explizite Benutzererlaubnis zum Bearbeiten von Dateien erfordern, was eine effiziente Automatisierung von Workflows mit Protokollen wie sequenzieller Phasenausführung und Definition von Done gewährleistet.","pt":"Habilita os agentes a executar tarefas de ponta a ponta sem interrupções, utilizando o modo de execução PHASED PLAN e requerendo permissão explícita do usuário para editar arquivos, garantindo automação eficiente de fluxos de trabalho com protocolos como execução de fase sequencial e Definição de Conclusão.","ru":"Наделяет агентов возможностью выполнять задачи от начала до конца без прерываний, используя режим выполнения PHASED PLAN и требуя явного разрешения пользователя на редактирование файлов, обеспечивая эффективную автоматизацию рабочих процессов с протоколами, такими как последовательная фазовая обработка и Определение готовности.","ar":"تمكّن الوكلاء من تنفيذ المهام من البداية إلى النهاية دون انقطاع، باستخدام وضع تنفيذ PHASED PLAN وتطلب موافقة المستخدم الصريحة لتحرير الملفات، مما يضمن آليّة كفءة لسير العمل باستخدام بروتوكولات مثل تنفيذ المرحلة التتابعية وتعريف الإنجاز."},"useCases":{"en":["Automating complex workflows with sequential phase execution","Executing tasks without interruptions using PHASED PLAN","Ensuring explicit user permission for file editing in automated workflows"],"zh":["使用顺序阶段执行自动化复杂的工作流程","使用PHASED PLAN在不中断的情况下执行任务","确保自动化工作流程中文件编辑需要显式用户许可"],"ja":["シーケンシャルフェーズ実行を使用した複雑なワークフローの自動化","PHASED PLANを使用した中断されないタスクの実行","自動化されたワークフローのファイル編集に対する明示的なユーザーの許可の確保"],"ko":["시퀀셜 단계 실행을 사용한 복잡한 워크플로우 자동화","PHASED PLAN을 사용한 중단되지 않는 작업 실행","자동화된 워크플로우에서 파일 편집에 대한 명시적인 사용자 허가 확보"],"es":["Automatización de flujos de trabajo complejos con ejecución de fases secuenciales","Ejecución de tareas sin interrupciones utilizando PHASED PLAN","Garantía de permiso de usuario explícito para la edición de archivos en flujos de trabajo automatizados"],"fr":["Automatisation de flux de travail complexes avec exécution de phases séquentielles","Exécution de tâches sans interruptions en utilisant PHASED PLAN","Garantie d''un consentement explicite de l''utilisateur pour la modification de fichiers dans les flux de travail automatisés"],"de":["Automatisierung komplexer Workflows mit sequenzieller Phasenausführung","Ausführung von Aufgaben ohne Unterbrechungen unter Verwendung von PHASED PLAN","Sicherstellung einer expliziten Benutzererlaubnis zum Bearbeiten von Dateien in automatisierten Workflows"],"pt":["Automatizar fluxos de trabalho complexos com execução de fase sequencial","Executar tarefas sem interrupções usando PHASED PLAN","Garantir permissão explícita do usuário para edição de arquivos em fluxos de trabalho automatizados"],"ru":["Автоматизировать сложные рабочие процессы с последовательной фазовой обработкой","Выполнять задачи без прерываний с помощью PHASED PLAN","Обеспечить явное разрешение пользователя на редактирование файлов в автоматизированных рабочих процессах"],"ar":["تحقيق آليّة لسير العمل المعقدة مع تنفيذ المرحلة التتابعية","تنفيذ المهام دون انقطاع باستخدام PHASED PLAN","ضمان موافقة المستخدم الصريحة لتحرير الملفات في سير العمل الآلي"]},"limitations":{"en":["Requires explicit user permission to edit files","Only pauses execution if blocked by missing info or command failure","Must operate within Definition of Done parameters"],"zh":["需要显式用户许可来编辑文件","仅在缺少信息或命令失败时暂停执行","必须在已完成定义参数内操作"],"ja":["ファイルの編集には明示的なユーザーの許可が必要","情報が不足しているかコマンドが失敗した場合のみ実行を一時停止する","Definition of Doneパラメータ内でなければ操作できない"],"ko":["파일 편집에는 명시적인 사용자 허가가 필요","정보가 부족하거나 명령어가 실패한 경우에만 실행을 暫停","완성 정의 매개변수 내에서만 작동"],"es":["Requiere un permiso de usuario explícito para editar archivos","Sólo pausa la ejecución si se bloquea por falta de información o falla de comando","Debe operar dentro de los parámetros de la Definición de Hecho"],"fr":["Nécessite un consentement explicite de l''utilisateur pour modifier des fichiers","Ne suspend l''exécution que si elle est bloquée par manque d''informations ou échec de commande","Doit fonctionner dans les paramètres de la Définition de Fait"],"de":["Erfordert eine explizite Benutzererlaubnis zum Bearbeiten von Dateien","Pausiert die Ausführung nur, wenn sie durch fehlende Informationen oder Befehlsfehler blockiert wird","Muss innerhalb der Parameter der Definition von Done operieren"],"pt":["Requer permissão explícita do usuário para editar arquivos","Só pausa a execução se bloqueada por falta de informação ou falha de comando","Deve operar dentro dos parâmetros da Definição de Conclusão"],"ru":["Требует явного разрешения пользователя на редактирование файлов","Приостанавливает выполнение только если заблокировано отсутствием информации или неудачей команды","Должно работать в пределах параметров Определения готовности"],"ar":["يتطلب موافقة المستخدم الصريحة لتحرير الملفات","يقوم بتعليق التنفيذ فقط إذا تم حظره بسبب عدم وجود معلومات أو فشل في الأمر","يجب أن يعمل في إطار معايير تعريف الإنجاز"]},"version":4},"contentHash":"e43530c3e7a567c8cc1a8269d2845fd015bddaccb9a0e564c4bce6bd7dc1983a","qualityScore":44}');
