INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CheekyCodexConjurer/aera-chart-engine/full_auth', 'full_auth', 'CheekyCodexConjurer', 'aera-chart-engine', 'community', 'full_auth CheekyCodexConjurer aera-chart-engine community full_auth enables AI agents to execute tasks end-to-end without interruptions, requiring explicit user permission to edit files. This skill benefits developers seeking to automate workflows efficiently. Full Auth是AIエージェント的高级技能，实现无缝授权和PHASED PLAN的执行 Full AuthはAIエージェントの実行モードを最適化し、効率的なタスク完了を実現する Full Auth는 AI 에이전트의 인증과 실행을 최적화하는 고급 스킬입니다 full_auth es una habilidad que permite la autorización explícita para editar archivos y completar tareas de manera segura con agentes de IA. Se utiliza en modo de planificación por fases con ejecución inmediata. full_auth est une compétence qui permet l''autorisation explicite pour éditer des fichiers et compléter des tâches de manière sécurisée avec les outils d''IA. Elle utilise un mode de planification par phases avec exécution immédiate. full_auth ist eine Fähigkeit, die die explizite Autorisierung zur Bearbeitung von Dateien und zum Abschließen von Aufgaben auf sichere Weise mit KI-Agents ermöglicht. Sie wird im Phasenplan-Modus mit sofortiger Ausführung verwendet. O full_auth permite a automação de tarefas com permissão explícita, implementando planos faseados e executando comandos em sequência Full_auth позволяет автоматизировать задачи с явным разрешением, реализуя фазовые планы и выполняя команды в последовательности ال full_auth يتيح أتمتة المهام بالتصريح الصريح، وتنفيذ الخطط المرحلية وتنفيذ الأوامر بالتسلسل how to use full_auth full_auth alternative full_auth setup guide what is full_auth full_auth vs other AI skills full_auth install phased implementation plan automated workflow execution AIエージェント Full Auth PHASED PLAN Blocking Rule 无缝授权 AI工具 高级技能 Produces a phased implementation plan with multiple phases (Phase 1/2/3…) Executes all phases in sequence in the same run, until Definition of Done is met Pauses only when blocked by missing information or command failures Requires explicit user permission to edit files and complete tasks Supports autonomous resolution of command failures full_auth is a skill that allows AI agents to perform phased implementation plans, executing all phases in sequence until completion, with explicit user permission.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RtlZeroMemory/Zireael/zireael-abi-formats', 'community', 'RtlZeroMemory', 'Zireael', 'RtlZeroMemory/Zireael', 'zireael-abi-formats', 0, 0, 44, '2026-03-08T01:57:15.372Z', '2026-03-08T02:05:58.975Z', 'c969e2ef43f247840692b6340cedcbc6df78060e33537ae4200b3bc998b3391d', '{"id":"RtlZeroMemory/Zireael/zireael-abi-formats","name":"zireael-abi-formats","description":{"en":"zireael-abi-formats is a deterministic terminal UI core engine in C, providing an FFI/ABI backend for Zireael-UI, benefiting developers who need to modify public engine ABI surfaces or drawlist formats.","zh":"Zireael-ABI-Formats是一个确定性的终端UI核心引擎，提供ABI和版本控制规则、绘图列表格式和事件系统","ja":"Zireael-ABI-Formatsは決定的なターミナルUIコアエンジンであり、ABIとバージョン管理ルール、描画リスト形式、イベントシステムを提供する","ko":"Zireael-ABI-Formats는 결정적인 터미널 UI 코어 엔진으로 ABI 및 버전 관리 규칙, 그리기 목록 형식 및 이벤트 시스템을 제공합니다","es":"zireael-abi-formats es un núcleo de interfaz de usuario terminal determinista en C con FFI/ABI backend para Zireael-UI. Utilízalo para cambiar la superficie de ABI de la interfaz de usuario","fr":"zireael-abi-formats est un noyau d''interface utilisateur terminal déterministe en C avec un backend FFI/ABI pour Zireael-UI. Utilisez-le pour modifier la surface d''ABI de l''interface utilisateur","de":"zireael-abi-formats ist ein deterministischer Terminalbenutzeroberflächenkern in C mit FFI/ABI-Backend für Zireael-UI. Verwenden Sie es, um die ABI-Oberfläche der Benutzeroberfläche zu ändern","pt":"O zireael-abi-formats é um engine de UI determinística em C, projetado para criar interfaces de usuário personalizadas e eficientes.","ru":"zireael-abi-formats - это детерминированный движок терминального UI на C, предназначенный для создания индивидуальных и эффективных интерфейсов пользователя.","ar":"zireael-abi-formats هو محرك واجهة المستخدم الطرفية التحليلي بلغة C، مصمم لإنشاء واجهات مستخدم مخصصة وفعالة."},"seo":{"title":{"en":"zireael-abi-formats: Deterministic Terminal UI Engine Set...","zh":"Zireael-ABI-Formats_SETUP GUIDE","ja":"Zireael-ABI-Formatsのセットアップガイド","ko":"Zireael-ABI-Formats 설정 가이드","es":"Guía de configuración de zireael-abi-formats para desarro...","fr":"Mise en route de zireael-abi-formats pour les développeur...","de":"Einrichtungsleitfaden für zireael-abi-formats für Entwick...","pt":"Guia de Configuração do zireael-abi-formats: Engine de UI...","ru":"Настройка zireael-abi-formats: Детерминированный движок т...","ar":"إعداد zireael-abi-formats: محرك واجهة المستخدم الطرفية ال..."},"description":{"en":"Discover how to leverage zireael-abi-formats for seamless terminal UI core engine integration - explore ABI surface, drawlist binary format, and versioning s...","zh":"了解Zireael-ABI-Formats的技术细节，包括ABI和版本控制规则、绘图列表格式和事件系统","ja":"Zireael-ABI-Formatsの技術的な詳細を学ぶ、ABIとバージョン管理ルール、描画リスト形式、イベントシステム","ko":"Zireael-ABI-Formats의 기술적 세부 사항을 알아보세요, ABI 및 버전 관리 규칙, 그리기 목록 형식 및 이벤트 시스템","es":"Aprende a utilizar zireael-abi-formats para crear interfaces de usuario deterministas con FFI/ABI backend para Zireael-UI. Mejora tu desarrollo con esta guía","fr":"Découvrez comment utiliser zireael-abi-formats pour créer des interfaces utilisateur déterministes avec un backend FFI/ABI pour Zireael-UI. Améliorez votre d...","de":"Erfahren Sie, wie Sie zireael-abi-formats verwenden können, um deterministische Benutzeroberflächen mit FFI/ABI-Backend für Zireael-UI zu erstellen. Verbesse...","pt":"Aprenda a utilizar o zireael-abi-formats, um engine de UI determinística em C, para criar interfaces de usuário personalizadas e eficientes.","ru":"Узнайте, как использовать zireael-abi-formats, детерминированный движок терминального UI на C, для создания индивидуальных и эффективных интерфейсов пользова...","ar":"تعرف على كيفية استخدام zireael-abi-formats، محرك واجهة المستخدم الطرفية التحليلي بلغة C، لإنشاء واجهات مستخدم مخصصة وفعالة."},"definition":{"en":"zireael-abi-formats is a C-based terminal UI core engine providing a deterministic ABI surface for Zireael-UI, governing drawlist binary formats and versioning strategies.","zh":"Zireael-ABI-Formats是什么？它是一个C语言实现的确定性的终端UI核心引擎","ja":"Zireael-ABI-Formatsとは何か？C言語で実装された決定的なターミナルUIコアエンジン","ko":"Zireael-ABI-Formats是什么？C 언어로 구현된 결정적인 터미널 UI 코어 엔진","es":"zireael-abi-formats es un núcleo de interfaz de usuario terminal determinista que proporciona un backend FFI/ABI para Zireael-UI","fr":"zireael-abi-formats est un noyau d''interface utilisateur terminal déterministe qui fournit un backend FFI/ABI pour Zireael-UI","de":"zireael-abi-formats ist ein deterministischer Terminalbenutzeroberflächenkern, der ein FFI/ABI-Backend für Zireael-UI bereitstellt","pt":"O zireael-abi-formats é um engine de UI determinística que fornece uma interface de programação de aplicativos (ABI) para criação de interfaces de usuário personalizadas.","ru":"zireael-abi-formats - это детерминированный движок терминального UI, который предоставляет интерфейс программирования приложений (ABI) для создания индивидуальных интерфейсов пользователя.","ar":"zireael-abi-formats هو محرك واجهة المستخدم الطرفية التحليلي الذي يوفر واجهة برمجة التطبيقات (ABI) لإنشاء واجهات مستخدم مخصصة."},"features":{"en":["Modifies public engine ABI surface, including function signatures and structs","Customizes drawlist binary format for optimized performance","Supports packed event batch format for efficient event handling","Implements versioning and negotiation strategy for seamless compatibility","References ABI and versioning rules from CONFIG_AND_ABI_VERSIONING.md","Utilizes error code semantics from ERROR_CODES_CATALOG.md"],"zh":["提供ABI和版本控制规则","支持绘图列表格式","包含事件系统和批量事件格式","支持错误代码和语义","提供版本固定功能"],"ja":["ABIとバージョン管理ルールを提供","描画リスト形式をサポート","イベントシステムとバッチイベント形式を含む","エラーコードとセマンティクスをサポート","バージョン固定機能を提供"],"ko":["ABI 및 버전 관리 규칙을 제공","그리기 목록 형식을 지원","이벤트 시스템 및 배치 이벤트 형식을 포함","오류 코드 및 의미론을 지원","버전 고정 기능을 제공"],"es":["Cambio de superficie de ABI de la interfaz de usuario","S