INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('miles990/self-evolving-agent/evolve', 'evolve', 'miles990', 'self-evolving-agent', 'community', 'evolve miles990 self-evolving-agent community The evolve skill enables autonomous goal achievement through iterative learning and self-improvement, benefiting developers of AI agents. It utilizes a self-evolving agent architecture for efficient goal attainment. Evolve 是一个 Claude Code 技能，实现自我迭代学习和自动目标实现，通过原子化架构和 PDCA 执行 Evolve は Claude Code スキルであり、イテレーティブ学習と自律的な目標達成を実現するものです。原子化アーキテクチャと PDCA 実行を通じて Evolve는 Claude Code 스킬로서 반복적 학습과 자동 목표 달성을 구현하는 것으로, 원자화 아키텍처와 PDCA 실행을 통해 Evolve es un skill de Claude Code que permite el logro de objetivos autónomos a través del aprendizaje iterativo y la auto-mejora, utilizando tecnologías como PSB y PDCA Evolve est un skill de Claude Code qui permet la réalisation d''objectifs autonomes via l''apprentissage itératif et l''auto-amélioration, en utilisant des technologies comme PSB et PDCA Evolve ist ein Skill von Claude Code, der die autonome Zielverwirklichung durch iteratives Lernen und Selbstverbesserung ermöglicht, unter Verwendung von Technologien wie PSB und PDCA O Evolve é uma habilidade de código Claude que permite alcançar metas de forma autônoma através do aprendizado iterativo e da melhoria contínua. Com uma arquitetura modular, ele divide o conhecimento em módulos independentes Evolve - это навык кода Claude, который позволяет достигать целей автономно через итеративное обучение и непрерывное совершенствование. С модульной архитектурой, он разделяет знания на независимые модули Evolve هو مهارة كود كلود التي تسمح بتحقيق الأهداف بشكل tự động من خلال التعلم التكراري والتحسين المستمر. مع هندسة معمارية موديولار، يقسم المعرفة إلى وحدات مستقلة how to use evolve evolve setup guide evolve alternative evolve vs claude evolve install what is evolve evolve autonomous goal achievement evolve AI agent development evolve iterative learning evolve self-improvement AI 代理 自我迭代学习 自动目标实现 原子化架构 PDCA 执行 Claude Code Utilizes PDCA execution with Test-Driven Development (TDD) and verification Employs systematic debugging for efficient issue resolution Supports automatic domain identification and skill acquisition Features a modular architecture with isolated worktrees for robust development Includes periodic health checks for optimal performance Implements a brainstorming module for target analysis and goal planning evolve is a Claude Code skill that facilitates autonomous goal achievement through iterative learning, self-improvement, and modular knowledge architecture.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wrsmith108/governance-claude-skill/governance', 'community', 'wrsmith108', 'governance-claude-skill', 'wrsmith108/governance-claude-skill', 'governance', 0, 0, 44, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:43.247Z', 'cf81a3c5a3cf809ea8c14f2688f3d489bf24885f648e0fa1bda588ae89c310a9', '{"id":"wrsmith108/governance-claude-skill/governance","name":"governance","description":{"en":"The governance skill enforces engineering standards and code quality policies using delegated execution and parallel agent execution for context efficiency, benefiting developers and engineering teams.","zh":"Governance AIエージェント用于执行工程标准和代码质量政策，通过并行代理执行实现上下文效率","ja":"Governance AIエージェントは、エンジニアリング標準とコード品質ポリシーを実施し、並列エージェント実行によりコンテキスト効率を実現します","ko":"Governance AI 에이전트는 엔지니어링 표준과 코드 품질 정책을 시행하며, 병렬 에이전트 실행을 통해 컨텍스트 효율성을 달성합니다","es":"La gobernanza con Claude Code permite a los equipos de ingeniería aplicar estándares y políticas de calidad de código de manera eficiente","fr":"La gouvernance avec Claude Code permet aux équipes d''ingénierie d''appliquer des normes et des politiques de qualité de code de manière efficace","de":"Die Governance mit Claude Code ermöglicht es Ingenieurteams, Standards und Code-Qualitätsrichtlinien effizient umzusetzen","pt":"A governança é uma habilidade do Claude Code que garante a qualidade do código e a conformidade com os padrões de engenharia","ru":"Управление кодом - это навык Claude Code, обеспечивающий качество кода и соблюдение стандартов разработки","ar":"الحوكمة هي مهارة في Claude Code تضمن جودة الكود وامتثال معايير الهندسة"},"seo":{"title":{"en":"Governance: Delegated Execution Setup Guide | AI Agent Skill","zh":"Governance Setup Guide - AIエージェント代码质量控制","ja":"Governance ベストプラクティス - AIエージェントによるコード品質管理","ko":"Governance 설정 가이드 - AI 에이전트를 활용한 코드 품질 관리","es":"Guía de configuración de gobernanza para estándares de in...","fr":"Guide de mise en place de la gouvernance pour les normes ...","de":"Einrichtungsleitfaden für Governance in der Ingenieurnorm","pt":"Guia de Configuração de Governança para Desenvolvedores","ru":"Настройка ИИ Агентов для Управления Кодом","ar":"دليل الإعداد للحوكمة في تطوير البرمجيات"},"description":{"en":"Discover how to enforce engineering standards with the governance skill, featuring parallel agent execution and context efficiency. Learn more and get starte...","zh":"了解Governance AIエージェント的功能和特点，包括代码质量控制和工程标准执行","ja":"Governance AIエージェントの特徴と機能を紹介します。コード品質管理とエンジニアリング標準の実施を学びましょう","ko":"Governance AI 에이전트의 기능과 특징을 알아보세요. 코드 품질 관리와 엔지니어링 표준 시행을 위한 최고의 방법입니다","es":"Aprende a implementar la gobernanza en tus proyectos con Claude Code, para asegurar la calidad y los estándares de ingeniería","fr":"Découvrez comment mettre en place la gouvernance dans vos projets avec Claude Code, pour garantir la qualité et les normes d''ingénierie","de":"Erfahren Sie, wie Sie die Governance in Ihren Projekten mit Claude Code umsetzen, um die Qualität und die Ingenieurnormen zu gewährleisten","pt":"Aprenda a configurar a governança para garantir a qualidade do código e cumprir os padrões de engenharia com o Claude Code","ru":"Узнайте, как настроить управление кодом с помощью ИИ Агентов и обеспечить соблюдение стандартов разработки","ar":"تعرف على كيفية ضبط الحوكمة لضمان جودة الكود وامتثال معايير الهندسة مع Claude Code"},"definition":{"en":"Governance is a Claude Code skill that enforces engineering standards and code quality policies through automated audits and reviews.","zh":"Governance AIエージェント是一种用于执行工程标准和代码质量政策的AI工具","ja":"Governance AIエージェントは、エンジニアリング標準とコード品質ポリシーを実施するためのAIエージェントです","ko":"Governance AI 에이전트는 엔지니어링 표준과 코드 품질 정책을 시행하기 위한 AI 에이전트입니다","es":"La gobernanza es un conjunto de procesos y herramientas para garantizar la calidad y los estándares de ingeniería en el desarrollo de software","fr":"La gouvernance est un ensemble de processus et d''outils pour garantir la qualité et les normes d''ingénierie dans le développement de logiciels","de":"Die Governance ist ein Satz von Prozessen und Werkzeugen, um die Qualität und die Ingenieurnormen in der Softwareentwicklung zu gewährleisten","pt":"Governança é a capacidade de garantir a qualidade do código e a conformidade com os padrões de engenharia","ru":"Управление кодом - это способность обеспечить качество кода и соблюдение стандартов разработки","ar":"الحوكمة هي القدرة على ضمان جودة الكود وامتثال معايير الهندسة"},"features":{"en":["Enforces engineering standards using a starter standards document (standards.md)","Executes audits via the `npm run audit:standards` command","Utilizes delegated execution with the built-in `reviewer` subagent type","Supports parallel agent execution for context efficiency","References a full protocol document (agent-prompt.md) for detailed implementation"],"zh":["并行代理执行","代码质量控制","工程标准执行","Delegated Execution 执行模型","reviewer 子代理类型"],"ja":["並列エージェント実行","コード品質管理","エンジニアリング標準の実施","Delegated Execution 実行モデル","reviewer サブエージェントタイプ"],"ko":["병렬 에이전트 실행","코드 품질 관리","엔지니어링 표준 시행","Delegated Execution 실행 모델","reviewer 서브 에이전트 유형"],"es":["Ejecución paralela de agentes para una mayor eficiencia","Delegación de ejecución a subagentes tipo ''reviewer''","Soporte para estándares de ingeniería personalizados","Integración con npm para auditorías de código","Compatibilidad con la versión 2.1 del modelo de ejecución"],"fr":["Exécution parallèle d''agents pour une meilleure efficacité","Délégation d''exécution à des sous-agents de type ''reviewer''","Prise en charge de normes d''ingénierie personnalisées","Intégration avec npm pour des audits de code","Compatibilité avec la version 2.1 du modèle d''exécution"],"de":["Parallele Ausführung von Agenten für höhere Effizienz","Delegation der Ausführung an Subagenten vom Typ ''reviewer''","Unterstützung für benutzerdefinierte Ingenieurnormen","Integration mit npm für Code-Audits","Kompatibilität mit der Version 2.1 des Ausführungsmodells"],"pt":["Execução paralela de agentes para eficiência de contexto","Cumprimento de padrões de engenharia com o documento de padrões","Script de auditoria para garantir a qualidade do código","Utilização do subagente ''reviewer'' para delegação de execução","Compatibilidade com o protocolo de agente-prompt","Integração com o comando ''npm run audit:standards''"],"ru":["Параллельная执行 агентов для эффективности контекста","Соблюдение стандартов разработки с помощью документа стандартов","Сценарий аудита для обеспечения качества кода","Использование субагента ''reviewer'' для делегации выполнения","Совместимость с протоколом агент-пrompt","Интеграция с командой ''npm run audit:standards''"],"ar":["تنفيذ مواز للوكلاء من أجل كفاءة السياق","الامتثال لمعايير الهندسة مع وثيقة المعايير","سكرิปت التدقيق لضمان جودة الكود","استخدام الوكيل الفرعي ''reviewer'' للتفويض التنفيذ","التوافق مع بروتوكول الوكيل-الاستدعاء","التكامل مع الأمر ''npm run audit:standards''"]},"keywords":{"en":["how to use governance in AI agents","governance skill for code quality","what is governance in software development","governance alternative for engineering standards","governance setup guide for developers","governance vs code review tools"],"zh":["Governance AIエージェント","代码质量控制","工程标准执行","AIエージェント工具","并行代理执行","Delegated Execution","reviewer 子代理类型"],"ja":["Governance AIエージェント","コード品質管理","エンジニアリング標準の実施","AIエージェントツール","並列エージェント実行","Delegated Execution","reviewer サブエージェントタイプ"],"ko":["Governance AI 에이전트","코드 품질 관리","엔지니어링 표준 시행","AI 에이전트 툴","병렬 에이전트 실행","Delegated Execution","reviewer 서브 에이전트 유형"],"es":["gobernanza en ingeniería","estándares de código","calidad de software","Claude Code","herramientas de desarrollo","automatización de pruebas","integración continua","desarrollo de software ágil"],"fr":["gouvernance en ingénierie","normes de code","qualité de logiciel","Claude Code","outils de développement","automatisation de tests","intégration continue","développement de logiciel agile"],"de":["Governance in der Ingenieurnorm","Code-Standards","Software-Qualität","Claude Code","Entwicklungstools","Automatisierung von Tests","kontinuierliche Integration","agiles Software-Entwicklung"],"pt":["governança de código","padrões de engenharia","qualidade do código"," Claude Code","desenvolvimento de software","ferramentas de desenvolvimento","ИИ Агенты","desenvolvedores"],"ru":["управление кодом","стандарты разработки","качество кода","Claude Code","разработка программного обеспечения","инструменты разработки","ИИ Агенты","разработчики"],"ar":["حوكمة الكود","معايير الهندسة","جودة الكود","Claude Code","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي","مطورون"]}},"owner":"wrsmith108","repo":"governance-claude-skill","repoPath":"wrsmith108/governance-claude-skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"governance","description":"Engineering standards and code governance enforcement with parallel agent execution. Triggers during code reviews, commits, and standards discussions. 70-90% token savings via delegated execution.","version":"2.1.0","tags":"","bodyPreview":"# Governance Skill\n\nEnforces engineering standards and code quality policies with parallel agent execution for context efficiency.\n\n> **Standards Document**: [standards.md](standards.md) (starter default — replace with your own)\n> **Audit Script**: `npm run audit:standards`\n> **Full Protocol**: [agent-prompt.md](agent-prompt.md)\n\n---\n\n## Execution Model (v2.1)\n\n**Type**: Delegated Execution — delegates to the built-in `reviewer` subagent type.\n\nThis skill uses the `reviewer` subagent (available","body":"# Governance Skill\n\nEnforces engineering standards and code quality policies with parallel agent execution for context efficiency.\n\n> **Standards Document**: [standards.md](standards.md) (starter default — replace with your own)\n> **Audit Script**: `npm run audit:standards`\n> **Full Protocol**: [agent-prompt.md](agent-prompt.md)\n\n---\n\n## Execution Model (v2.1)\n\n**Type**: Delegated Execution — delegates to the built-in `reviewer` subagent type.\n\nThis skill uses the `reviewer` subagent (available in all Claude Code installations — no custom agent required):\n\n1. **Spawn** the reviewer agent\n2. **Delegate** the governance task with instructions from `agent-prompt.md`\n3. **Await** completion\n4. **Report** the structured summary to the user\n\n### Token Efficiency\n\n| Execution Mode | Token Usage | Benefit |\n|----------------|-------------|---------|\n| Direct (v1.x) | ~3,000–8,000 | Full context in main thread |\n| Delegated (v2.x) | ~500–800 | 70–90% token savings |\n\n---\n\n## How to Invoke\n\nWhen this skill is triggered, read `agent-prompt.md` for the full protocol, then delegate:\n\n### Code Review\n```javascript\nTask({\n  description: \"Governance code review\",\n  prompt: `[See agent-prompt.md for full instructions]\nReview the following files for standards compliance:\n- [list files or PR description]\n\nExecute full code review workflow:\n1. Run standards audit\n2. Check each file against standards.md\n3. Fix ALL issues immediately (zero deferral)\n4. Return structured summary`,\n  subagent_type: \"reviewer\"\n})\n```\n\n### Pre-Commit Check\n```javascript\nTask({\n  description: \"Pre-commit governance\",\n  prompt: `[See agent-prompt.md for full instructions]\nRun pre-commit governance checks:\n1. typecheck, lint, format:check, test\n2. Check for untracked source files\n3. Return pass/fail with specific failures`,\n  subagent_type: \"reviewer\"\n})\n```\n\n### Retrospective\n```javascript\nTask({\n  description: \"Run retrospective\",\n  prompt: `[See agent-prompt.md for full instructions]\nRun retrospective for [topic/sprint]:\n1. Analyze completed issues\n2. Gather metrics\n3. Write report\n4. Return summary`,\n  subagent_type: \"reviewer\"\n})\n```\n\n---\n\n## Quick Reference\n\n### Pre-Commit Checklist\n\n```\n[ ] npm run typecheck\n[ ] npm run lint\n[ ] npm run test\n[ ] npm run audit:standards\n[ ] No console.log statements\n[ ] No hardcoded secrets\n```\n\n### Compliance Check\n\n```bash\nnpm run audit:standards\nnode scripts/governance-check.mjs\n```\n\n---\n\n*Full agent protocol, anti-pattern tables, and output format in [agent-prompt.md](agent-prompt.md)*\n*Version 2.1.0 — Structural cleanup: flat layout, built-in reviewer agent, standards.md default added*\n"},"lastSynced":"2026-03-08T02:06:43.247Z","agentAnalysis":{"suitability":{"en":"Ideal for Engineering Agents requiring rigorous code quality assurance and standards enforcement.","zh":"适用于需要严格代码质量保证和标准执行的工程代理","ja":"エンジニアリング エージェントが厳格なコード品質保証と標準の適用を必要とする場合に最適","ko":"严格한 코드 품질 보증과 표준 적용이 필요한 엔지니어링 에이전트에 적합","es":"Ideal para Agentes de Ingeniería que requieren una garantía de calidad de código rigurosa y aplicación de normas.","fr":"Idéal pour les agents d''ingénierie nécessitant une assurance de qualité de code rigoureuse et une application de normes.","de":"Ideal für Engineering-Agenten, die eine strenge Code-Qualitätssicherung und Normdurchsetzung erfordern.","pt":"Ideal para Agentes de Engenharia que exigem garantia de qualidade de código rigorosa e aplicação de normas.","ru":"Идеально для Инженерных Агентов, требующих строгого обеспечения качества кода и соблюдения стандартов.","ar":"مثالية للموكلين الهندسيين الذين يتطلبون ضمان جودة الشفرة الصارمة وتنفيذ المعايير."},"recommendation":{"en":"Empowers agents to enforce engineering standards and code quality policies using delegated execution and parallel agent execution for context efficiency, leveraging protocols like the reviewer subagent and standards defined in the standards.md document.","zh":"赋予代理执行工程标准和代码质量策略的能力，使用委托执行和并行代理执行以提高上下文效率，利用像审查子代理和 standards.md 文档中定义的标准等协议","ja":"エージェントにエンジニアリング標準とコード品質ポリシーの適用を委任された実行と並列エージェント実行によるコンテキスト効率を高める能力を付与することで、Reviewer サブエージェントや standards.md ドキュメントで定義された標準などのプロトコルを利用する","ko":"엔지니어링 표준과 코드 품질 정책을 위임된 실행 및 병렬 에이전트 실행을 통해 문맥 효율성을 높이는 기능을 에이전트에 부여함으로써 리뷰어 서브 에이전트 및 standards.md 문서에서 정의된 표준 등을 활용","es":"Habilita a los agentes a aplicar normas de ingeniería y políticas de calidad de código utilizando ejecución delegada y ejecución paralela de agentes para eficiencia de contexto, aprovechando protocolos como el subagente revisor y normas definidas en el documento standards.md.","fr":"Permet aux agents d''appliquer des normes d''ingénierie et des politiques de qualité de code en utilisant l''exécution déléguée et l''exécution parallèle d''agents pour l''efficacité du contexte, en exploitant des protocoles tels que le sous-agent réviseur et les normes définies dans le document standards.md.","de":"Ermächtigt Agenten, Ingenieurnormen und Code-Qualitätsrichtlinien durch delegierte Ausführung und parallele Agentenausführung für Kontexteffizienz durchzusetzen, indem Protokolle wie der Revisions-Subagent und in der standards.md-Dokument definierte Normen genutzt werden.","pt":"Habilita os agentes a aplicar normas de engenharia e políticas de qualidade de código usando execução delegada e execução paralela de agentes para eficiência de contexto, aproveitando protocolos como o subagente revisor e normas definidas no documento standards.md.","ru":"Наделяет агентов возможностью обеспечивать соблюдение инженерных стандартов и политик качества кода с помощью делегированной исполняемости и параллельной исполняемости агентов для контекстной эффективности, используя протоколы, такие как субагент-ревьюер и стандарты, определенные в документе standards.md.","ar":"تمكّن الوكلاء من فرض معايير هندسية وسياسات جودة الشفرة باستخدام التنفيذ المفوض والتنفيذ الموازي للوكيل من أجل كفاءة السياق، مستفيدا من بروتوكولات مثل وكيل المراجعة والقواعد المحددة في وثيقة standards.md."},"useCases":{"en":["Automating code reviews with npm run audit:standards","Enforcing consistent coding standards across large projects","Streamlining development workflows with delegated execution and parallel agent execution"],"zh":["使用npm run audit:standards自动化代码审查","在大型项目中执行一致的编码标准","使用委托执行和并行代理执行简化开发工作流程"],"ja":["npm run audit:standardsを使用してコードレビューを自動化する","大規模プロジェクト全体で一貫したコーディング標準を適用する","委任された実行と並列エージェント実行を使用して開発ワークフローを最適化する"],"ko":["npm run audit:standards를 사용하여 코드 리뷰를 자동화","대규모 프로젝트에서 일관된 코딩 표준을 적용","위임된 실행 및 병렬 에이전트 실행을 사용하여 개발 워크플ロー 최적화"],"es":["Automatizar revisiones de código con npm run audit:standards","Aplicar normas de codificación consistentes en proyectos grandes","Optimizar flujos de desarrollo con ejecución delegada y ejecución paralela de agentes"],"fr":["Automatiser les examens de code avec npm run audit:standards","Faire respecter des normes de codage cohérentes dans de grands projets","Optimiser les flux de développement avec l''exécution déléguée et l''exécution parallèle d''agents"],"de":["Automatisieren von Code-Reviews mit npm run audit:standards","Durchsetzen konsistenter Codierungsstandards in großen Projekten","Optimieren von Entwicklungsworkflows mit delegierter Ausführung und paralleler Agentenausführung"],"pt":["Automatizar revisões de código com npm run audit:standards","Aplicar normas de codificação consistentes em projetos grandes","Otimizar fluxos de trabalho de desenvolvimento com execução delegada e execução paralela de agentes"],"ru":["Автоматизировать проверку кода с помощью npm run audit:standards","Обеспечивать последовательные стандарты кодирования в крупных проектах","Оптимизировать рабочие потоки разработки с помощью делегированной исполняемости и параллельной исполняемости агентов"],"ar":["تأتمة مراجعة الشفرة باستخدام npm run audit:standards","تطبيق معايير الترميز المتسقة في المشاريع الكبيرة","تحسين سير عمل التطوير باستخدام التنفيذ المفوض والتنفيذ الموازي للوكيل"]},"limitations":{"en":["Requires implementation of standards.md document","Dependent on reviewer subagent availability","Context efficiency may vary based on project complexity"],"zh":["需要实现standards.md文档","依赖于审查子代理的可用性","上下文效率可能会根据项目复杂性而有所不同"],"ja":["standards.mdドキュメントの実装が必要","Reviewerサブエージェントの可用性に依存する","コンテキスト効率はプロジェクトの複雑さによって異なる場合がある"],"ko":["standards.md 문서의 구현이 필요","리뷰어 서브 에이전트의 가용성에 의존","문맥 효율성은 프로젝트의 복잡성에 따라 다를 수 있음"],"es":["Requiere implementación del documento standards.md","Depende de la disponibilidad del subagente revisor","La eficiencia del contexto puede variar en función de la complejidad del proyecto"],"fr":["Nécessite la mise en œuvre du document standards.md","Dépend de la disponibilité du sous-agent réviseur","L''efficacité du contexte peut varier en fonction de la complexité du projet"],"de":["Erfordert Implementierung der standards.md-Dokumentation","Hängt von der Verfügbarkeit des Revisions-Subagents ab","Die Kontexteffizienz kann je nach Projektcomplexität variieren"],"pt":["Exige a implementação do documento standards.md","Depende da disponibilidade do subagente revisor","A eficiência de contexto pode variar com base na complexidade do projeto"],"ru":["Требует реализации документа standards.md","Зависит от доступности субагента-ревьюера","Контекстная эффективность может варьироваться в зависимости от сложности проекта"],"ar":["يتطلب تنفيذ وثيقة standards.md","يعتمد على توافر وكيل المراجعة","يمكن أن تختلف كفاءة السياق بناءً على تعقيد المشروع"]},"version":4},"contentHash":"cf81a3c5a3cf809ea8c14f2688f3d489bf24885f648e0fa1bda588ae89c310a9","qualityScore":44}');
