INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wrsmith108/governance-claude-skill/governance', 'governance', 'wrsmith108', 'governance-claude-skill', 'community', 'governance wrsmith108 governance-claude-skill community The governance skill enforces engineering standards and code quality policies using delegated execution and parallel agent execution for context efficiency, benefiting developers and engineering teams. Governance AIエージェント用于执行工程标准和代码质量政策，通过并行代理执行实现上下文效率 Governance AIエージェントは、エンジニアリング標準とコード品質ポリシーを実施し、並列エージェント実行によりコンテキスト効率を実現します Governance AI 에이전트는 엔지니어링 표준과 코드 품질 정책을 시행하며, 병렬 에이전트 실행을 통해 컨텍스트 효율성을 달성합니다 La gobernanza con Claude Code permite a los equipos de ingeniería aplicar estándares y políticas de calidad de código de manera eficiente La gouvernance avec Claude Code permet aux équipes d''ingénierie d''appliquer des normes et des politiques de qualité de code de manière efficace Die Governance mit Claude Code ermöglicht es Ingenieurteams, Standards und Code-Qualitätsrichtlinien effizient umzusetzen A governança é uma habilidade do Claude Code que garante a qualidade do código e a conformidade com os padrões de engenharia Управление кодом - это навык Claude Code, обеспечивающий качество кода и соблюдение стандартов разработки الحوكمة هي مهارة في Claude Code تضمن جودة الكود وامتثال معايير الهندسة how to use governance in AI agents governance skill for code quality what is governance in software development governance alternative for engineering standards governance setup guide for developers governance vs code review tools Governance AIエージェント 代码质量控制 工程标准执行 AIエージェント工具 并行代理执行 Delegated Execution reviewer 子代理类型 Enforces engineering standards using a starter standards document (standards.md) Executes audits via the `npm run audit:standards` command Utilizes delegated execution with the built-in `reviewer` subagent type Supports parallel agent execution for context efficiency References a full protocol document (agent-prompt.md) for detailed implementation Governance is a Claude Code skill that enforces engineering standards and code quality policies through automated audits and reviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeffreymonjacastro/valentines-wrapped/api-checks', 'community', 'jeffreymonjacastro', 'valentines-wrapped', 'jeffreymonjacastro/valentines-wrapped', 'api-checks', 0, 0, 44, '2026-03-08T01:57:15.417Z', '2026-03-08T02:07:18.121Z', 'fe976bb383b8ecd42ac9bbe2daf3605b87561217640d5affb2079596bfd9e5bf', '{"id":"jeffreymonjacastro/valentines-wrapped/api-checks","name":"api-checks","description":{"en":"The api-checks skill enforces a repeatable API review checklist for Next.js App Router, suggesting improvements for validation, error handling, and response shapes. It benefits developers by flagging common pitfalls that cause 500s or inconsistent behavior.","zh":"API 检查技能用于 Next.js App Router，确保 API 路由安全可靠。它提供了重复的 API 审查清单，建议改进验证、错误处理和响应形状","ja":"API チェックスキルは Next.js App Router で使用されます。API ルーティングの安全性と信頼性を確保します","ko":"API 체크 스킬은 Next.js App Router에서 사용되며 API 라우팅의 안정성과 신뢰성을 보장합니다","es":"Api-checks es una habilidad que mejora la calidad de tus API, validando entradas y normalizando respuestas","fr":"Api-checks est une compétence qui améliore la qualité de vos API, en validant les entrées et en normalisant les réponses","de":"Api-checks ist eine Fähigkeit, die die Qualität Ihrer APIs verbessert, indem sie Eingaben validiert und Antworten normalisiert","pt":"O API Checks é uma habilidade que ajuda a garantir a segurança e desempenho da sua aplicação Next.js, fornecendo uma lista de verificação para rotas e handlers.","ru":"ИИ Агент API Checks - это навык, который помогает обеспечить безопасность и производительность вашего приложения Next.js, предоставляя проверочный список для маршрутов и обработчиков.","ar":"API Checks هو مهارة تساعد على ضمان أمان و أداء تطبيقات Next.js، حيث يقدم قائمة مراجعة لطرق وتحكمات التطبيق."},"seo":{"title":{"en":"api-checks: API Review Checklist for Next.js App Router |...","zh":"API 检查技能：Next.js App Router 最佳实践","ja":"API チェックスキル：Next.js App Router の設定ガイド","ko":"API 체크 스킬: Next.js App Router 최적화 가이드","es":"Herramientas de AI: Guía de configuración de api-checks","fr":"Outils d''IA: Guide de mise en place de api-checks","de":"AI-Tools: Einrichtungsleitfaden für api-checks","pt":"Guia de Configuração do API Checks para Desenvolvedores","ru":"ИИ Агент API Checks: Руководство по Настройке","ar":"دليل إعداد API Checks للاستفادة القصوى"},"description":{"en":"Discover how api-checks enforces a repeatable API review checklist, suggesting improvements for validation and error handling. Get started with api-checks to...","zh":"使用 API 检查技能来优化 Next.js App Router，确保 API 路由安全可靠","ja":"Next.js App Router を最適化するために、API チェックスキルを使用しましょう","ko":"Next.js App Router 최적화를 위해 API 체크 스킬을 사용하세요","es":"Mejora la calidad de tus API con api-checks, que ofrece validación de entradas, manejo de errores y normalización de respuestas","fr":"Améliorez la qualité de vos API avec api-checks, qui propose une validation des entrées, une gestion des erreurs et une normalisation des réponses","de":"Verbessern Sie die Qualität Ihrer APIs mit api-checks, das Eingabvalidierung, Fehlerbehandlung und Normalisierung von Antworten bietet","pt":"Aprenda a configurar o API Checks para melhorar a segurança e desempenho da sua aplicação Next.js","ru":"Узнайте, как настроить ИИ Агент API Checks для повышения безопасности и производительности вашего приложения Next.js","ar":"تعرف على كيفية إعداد API Checks لتحسين أمان وتقنيات تطبيق Next.js الخاص بك"},"definition":{"en":"api-checks is a skill that enforces a repeatable API review checklist, ensuring consistent and reliable API behavior in Next.js App Router applications.","zh":"API 检查技能是一种用于 Next.js App Router 的技术，用于检查和优化 API 路由","ja":"API チェックスキルは、Next.js App Router 用の API ルーティングをチェックし、最適化する技術です","ko":"API 체크 스킬은 Next.js App Router용 API 라우팅을 확인하고 최적화하는 기술입니다","es":"Api-checks es una herramienta de AI que proporciona una lista de verificación para la revisión de API","fr":"Api-checks est un outil d''IA qui propose une liste de vérification pour la révision de l''API","de":"Api-checks ist ein AI-Tool, das eine Prüfliste für die Überprüfung von APIs bietet","pt":"O que é API Checks? É uma habilidade que fornece uma lista de verificação para garantir a segurança e desempenho de rotas e handlers em aplicações Next.js","ru":"Что такое ИИ Агент API Checks? Это навык, который предоставляет проверочный список для обеспечения безопасности и производительности маршрутов и обработчиков в приложениях Next.js","ar":"ما هو API Checks؟ إنه مهارة توفر قائمة مراجعة لضمان أمان وأداء طرق وتحكمات تطبيقات Next.js"},"features":{"en":["Confirms handler coverage of expected HTTP methods","Validates inputs early and returns 400 for client errors","Normalizes error responses with consistent structure","Flags common pitfalls that cause 500s or inconsistent behavior","Suggests improvements for validation, error handling, and response shapes"],"zh":["确保处理程序涵盖预期的 HTTP 方法","提前验证输入并返回 400 客户端错误","规范化错误响应结构","标记常见的导致 500 或不一致行为的陷阱"],"ja":["予想される HTTP メソッドをカバーするハンドラーを確認","入力を早期に検証し、400 クライアント エラーを返す","エラー応答の構造を規格化","500 または不一致な動作につながる一般的な落とし穴をフラグ"],"ko":["처리기가 예상되는 HTTP 메서드를 커버하는지 확인","입력을 조기에 검증하고 400 클라이언트 오류를 반환","오류 응답 구조를 표준화","500 또는 일관되지 않은 동작을 유발하는 일반적인 함정을 플래그"],"es":["Validación de entradas para evitar errores del cliente","Normalización de respuestas con estructura consistente","Detección de errores comunes que causan errores 500","Comprobación de métodos HTTP esperados","Mejora de la gestión de errores y la validación de la respuesta"],"fr":["Validation des entrées pour éviter les erreurs du client","Normalisation des réponses avec une structure cohérente","Détection des erreurs courantes qui provoquent des erreurs 500","Vérification des méthodes HTTP attendues","Amélioration de la gestion des erreurs et de la validation de la réponse"],"de":["Eingabvalidierung, um Client-Fehler zu vermeiden","Normalisierung von Antworten mit konsistenter Struktur","Erkennung häufiger Fehler, die zu Fehlern 500 führen","Überprüfung der erwarteten HTTP-Methoden","Verbesserung der Fehlerbehandlung und der Validierung der Antwort"],"pt":["Confirmação de métodos HTTP esperados","Validação de entradas precoces e retorno de 400 para erros de cliente","Normalização de respostas de erro com estrutura consistente","Flagging de armadilhas comuns que causam 500 ou comportamento inconsistente"],"ru":["Подтверждение ожидаемых методов HTTP","Раннее валидация входных данных и возврат 400 для ошибок клиента","Нормализация ошибок ответов с последовательной структурой","Выявление общих ловушек, которые вызывают 500 или не последовательное поведение"],"ar":["التأكد من الطرق HTTP المتوقعة","التحقق المبكر من الإدخالات و إرجاع 400 لأخطاء العميل","تنسيق استجابات الأخطاء بتركيب منتظم","التحديد السريع للفخاخ الشائعة التي تسبب 500 أو سلوك غير متسق"]},"keywords":{"en":["how to use api-checks","api-checks setup guide","api-checks alternative","what is api-checks","api-checks vs API testing tools","api-checks install for Next.js","api-checks best practices for API review"],"zh":["API 检查技能","Next.js App Router","API 路由安全","API 审查清单","API 优化","AI 에이전트","API 체크"],"ja":["API チェックスキル","Next.js App Router","API ルーティング セキュリティ","API レビュー チェックリスト","API オプティマイゼーション","AI エージェント","API チェック"],"ko":["API 체크 스킬","Next.js App Router","API 라우팅 보안","API 리뷰 체크리스트","API 최적화","AI 에이전트","API 체크"],"es":["api checks","herramientas de ai para api","validación de api","normalización de respuestas","gestión de errores en api","mejora de la calidad de api","pruebas de api","revisión de api"],"fr":["api checks","outils d''ia pour api","validation d''api","normalisation des réponses","gestion des erreurs d''api","amélioration de la qualité d''api","tests d''api","révision d''api"],"de":["api checks","ai-tools für api","validierung von api","normalisierung von antworten","fehlerbehandlung in api","verbesserung der qualität von api","api-tests","überprüfung von api"],"pt":["API Checks","Next.js","segurança de api","desempenho de api","roteamento de api","validação de entrada","tratamento de erro"],"ru":["ИИ Агент API Checks","Next.js","безопасность api","производительность api","маршрутизация api","валидация входных данных","обработка ошибок"],"ar":["API Checks","Next.js","أمان Api","أداء Api","تسجيل Api","تحقق الإدخال","معالجة الأخطاء"]}},"owner":"jeffreymonjacastro","repo":"valentines-wrapped","repoPath":"jeffreymonjacastro/valentines-wrapped","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.417Z","topics":[],"category":"community","skillMd":{"name":"api-checks","description":"Validate Next.js route handlers and API responses with a consistent checklist for inputs, errors, and status codes.","bodyPreview":"# API Checks Skill\n\nUse this skill when you add or change route handlers in the Next.js App Router.\n\n## What this skill does\n\n- Enforces a repeatable API review checklist\n- Suggests improvements for validation, error handling, and response shapes\n- Flags common pitfalls that cause 500s or inconsistent behavior\n\n## Checklist\n\n1) Confirm the handler covers the expected HTTP methods.\n2) Validate inputs early and return 400 for client errors.\n3) Normalize error responses with consistent structure.\n4","body":"# API Checks Skill\n\nUse this skill when you add or change route handlers in the Next.js App Router.\n\n## What this skill does\n\n- Enforces a repeatable API review checklist\n- Suggests improvements for validation, error handling, and response shapes\n- Flags common pitfalls that cause 500s or inconsistent behavior\n\n## Checklist\n\n1) Confirm the handler covers the expected HTTP methods.\n2) Validate inputs early and return 400 for client errors.\n3) Normalize error responses with consistent structure.\n4) Set explicit status codes for success and errors.\n5) Avoid leaking internal error details in responses.\n6) Ensure JSON responses are serialized correctly.\n\n## Example\n\nWhen reviewing a route handler, apply the checklist and propose edits.\n\nInput:\n\n\"Add POST /api/notes that stores a note and returns it\"\n\nOutput:\n\n\"- Add input validation (title required, content max length)\n- Return 201 with JSON body\n- Catch errors and return 500 with a safe message\"\n"},"lastSynced":"2026-03-08T02:07:18.121Z","agentAnalysis":{"suitability":{"en":"Perfect for Next.js App Router Agents needing enhanced API validation and error handling capabilities.","zh":"非常适合需要增强API验证和错误处理能力的Next.js App Router代理。","ja":"Next.js App Routerエージェントが強化されたAPI検証およびエラー処理機能を必要とする場合に最適です。","ko":"강화된 API 유효성 검사 및 오류 처리 기능이 필요한 Next.js App Router 에이전트에 적합합니다.","es":"Perfecto para Agentes de Router de Aplicación de Next.js que necesitan capacidades de validación y manejo de errores de API mejoradas.","fr":"Parfait pour les agents de routeur d''application Next.js ayant besoin de capacités de validation et de gestion d''erreurs d''API améliorées.","de":"Perfekt für Next.js-App-Router-Agents, die erweiterte API-Validierungs- und Fehlerbehandlungsfunktionen benötigen.","pt":"Perfeito para Agentes de Roteador de Aplicativos Next.js que precisam de capacidades de validação de API e tratamento de erros aprimorados.","ru":"Идеально подходит для агентов маршрутизатора приложений Next.js, которым необходимы улучшенные возможности проверки API и обработки ошибок.","ar":"مثالي للوكلاء روتر التطبيق Next.js الذين يحتاجون إلى قدرات التحقق من واجهة برمجة التطبيقات والمعالجة الأخطاء المحسنة."},"recommendation":{"en":"Empowers agents to enforce repeatable API review checklists, suggesting improvements for validation, error handling, and response shapes using HTTP methods, input validation, and consistent error responses.","zh":"赋予代理执行可重复的API审查清单的能力，建议对验证、错误处理和响应形状进行改进，使用HTTP方法、输入验证和一致的错误响应。","ja":"エージェントに、HTTPメソッド、入力検証、および一貫したエラー応答を使用して、検証、エラー処理、およびレスポンスの形状の改善を提案する、繰り返し可能なAPIレビューのチェックリストを適用する機能を付与します。","ko":"에이전트가 HTTP 메서드, 입력 유효성 검사 및 일관된 오류 응답을 사용하여 유효성 검사, 오류 처리 및 응답 형태의 개선을 제안하는 반복 가능한 API 검토 체크 목록을 적용할 수 있는 기능을 부여합니다.","es":"Habilita a los agentes a hacer cumplir listas de verificación de revisión de API repetibles, sugiriendo mejoras para la validación, el manejo de errores y las formas de respuesta utilizando métodos HTTP, validación de entrada y respuestas de error consistentes.","fr":"Permet aux agents d''appliquer des listes de vérification de révision d''API répétitives, suggérant des améliorations pour la validation, la gestion des erreurs et les formes de réponse en utilisant des méthodes HTTP, une validation d''entrée et des réponses d''erreur cohérentes.","de":"Ermächtigt Agenten, wiederholbare API-Überprüfungs-Prüflisten durchzusetzen, und schlägt Verbesserungen für Validierung, Fehlerbehandlung und Antwortformen vor, die HTTP-Methoden, Eingabevalidierung und konsistente Fehlerantworten verwenden.","pt":"Habilita os agentes a impor listas de verificação de revisão de API repetíveis, sugerindo melhorias para validação, tratamento de erros e formas de resposta usando métodos HTTP, validação de entrada e respostas de erro consistentes.","ru":"Наделяет агентов возможностью обеспечивать выполнение повторяющихся проверочных списков API, предлагая улучшения для проверки, обработки ошибок и форм ответов с использованием методов HTTP, проверки входных данных и последовательных ответов об ошибках.","ar":"يمنح الوكلاء القدرة على فرض قوائم مراجعة واجهة برمجة التطبيقات القابلة للتكرار، مع اقتراح تحسينات للتحقق والتعامل مع الأخطاء وأشكال الاستجابة باستخدام أساليب HTTP والتحقق من الإدخال والاستجابات الخطأ المتسقة."},"useCases":{"en":["Validating route handlers for expected HTTP methods","Normalizing error responses for consistent structure","Flagging common pitfalls that cause 500s or inconsistent behavior"],"zh":["验证路由处理程序是否使用预期的HTTP方法","规范化错误响应以实现一致的结构","标记可能导致500或不一致行为的常见陷阱"],"ja":["予想されるHTTPメソッドを使用するルートハンドラーの検証","一貫した構造を実現するためのエラー応答の正規化","500または不一致な動作の原因となる一般的な落とし穴のフラグ付け"],"ko":["예상하는 HTTP 메서드를 사용하는 라우트 핸들러의 유효성 검사","일관된 구조를 구현하기 위한 오류 응답의 정규화","500 또는 불일치한 동작의 원인이 되는 일반적인 함정의 플래그 지정"],"es":["Validar controladores de rutas para métodos HTTP esperados","Normalizar respuestas de error para una estructura coherente","Marcar trampas comunes que causan errores 500 o comportamiento inconsistente"],"fr":["Valider les gestionnaires de routes pour les méthodes HTTP attendues","Normaliser les réponses d''erreur pour une structure cohérente","Marquer les pièges courants qui provoquent des erreurs 500 ou un comportement incohérent"],"de":["Validieren von Routen-Handlern für erwartete HTTP-Methoden","Normieren von Fehlerantworten für eine konsistente Struktur","Markieren häufiger Fallstricke, die Fehler 500 oder inkonsistentes Verhalten verursachen"],"pt":["Validar manipuladores de rotas para métodos HTTP esperados","Normalizar respostas de erro para estrutura consistente","Sinalizar armadilhas comuns que causam 500s ou comportamento inconsistente"],"ru":["Проверка обработчиков маршрутов на ожидаемые методы HTTP","Нормализация ответов об ошибках для последовательной структуры","Выделение распространенных ловушек, которые вызывают 500s или не последовательное поведение"],"ar":["التحقق من معالجات المسارات للأساليب-http المتوقعة","تطبيع استجابات الأخطاء لهيكل متسق","إضاءة الفخاخ الشائعة التي تسبب 500s أو سلوك غير متسق"]},"limitations":{"en":["Specific to Next.js App Router","Requires implementation of API review checklist"],"zh":["特定于Next.js App Router","需要API审查清单的实现"],"ja":["Next.js App Routerに特有のもの","APIレビューのチェックリストの実装が必要"],"ko":["Next.js App Router에 특정","API 검토 체크 목록의 구현이 필요"],"es":["Específico para Next.js App Router","Requiere la implementación de una lista de verificación de revisión de API"],"fr":["Spécifique à Next.js App Router","Nécessite la mise en œuvre d''une liste de vérification de révision d''API"],"de":["Spezifisch für Next.js-App-Router","Erfordert die Implementierung einer API-Überprüfungs-Prüfliste"],"pt":["Específico para Next.js App Router","Exige implementação de lista de verificação de revisão de API"],"ru":["Конкретно для Next.js App Router","Требует реализации проверочного списка API"],"ar":["نوعي لروتر تطبيق Next.js","يتطلب تنفيذ قائمة مراجعة واجهة برمجة التطبيقات"]},"version":4},"contentHash":"fe976bb383b8ecd42ac9bbe2daf3605b87561217640d5affb2079596bfd9e5bf","qualityScore":44}');
