INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeffreymonjacastro/valentines-wrapped/api-checks', 'api-checks', 'jeffreymonjacastro', 'valentines-wrapped', 'community', 'api-checks jeffreymonjacastro valentines-wrapped community The api-checks skill enforces a repeatable API review checklist for Next.js App Router, suggesting improvements for validation, error handling, and response shapes. It benefits developers by flagging common pitfalls that cause 500s or inconsistent behavior. API 检查技能用于 Next.js App Router，确保 API 路由安全可靠。它提供了重复的 API 审查清单，建议改进验证、错误处理和响应形状 API チェックスキルは Next.js App Router で使用されます。API ルーティングの安全性と信頼性を確保します API 체크 스킬은 Next.js App Router에서 사용되며 API 라우팅의 안정성과 신뢰성을 보장합니다 Api-checks es una habilidad que mejora la calidad de tus API, validando entradas y normalizando respuestas Api-checks est une compétence qui améliore la qualité de vos API, en validant les entrées et en normalisant les réponses Api-checks ist eine Fähigkeit, die die Qualität Ihrer APIs verbessert, indem sie Eingaben validiert und Antworten normalisiert O API Checks é uma habilidade que ajuda a garantir a segurança e desempenho da sua aplicação Next.js, fornecendo uma lista de verificação para rotas e handlers. ИИ Агент API Checks - это навык, который помогает обеспечить безопасность и производительность вашего приложения Next.js, предоставляя проверочный список для маршрутов и обработчиков. API Checks هو مهارة تساعد على ضمان أمان و أداء تطبيقات Next.js، حيث يقدم قائمة مراجعة لطرق وتحكمات التطبيق. how to use api-checks api-checks setup guide api-checks alternative what is api-checks api-checks vs API testing tools api-checks install for Next.js api-checks best practices for API review API 检查技能 Next.js App Router API 路由安全 API 审查清单 API 优化 AI 에이전트 API 체크 Confirms handler coverage of expected HTTP methods Validates inputs early and returns 400 for client errors Normalizes error responses with consistent structure Flags common pitfalls that cause 500s or inconsistent behavior Suggests improvements for validation, error handling, and response shapes api-checks is a skill that enforces a repeatable API review checklist, ensuring consistent and reliable API behavior in Next.js App Router applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Rukkha1024/post_auto_work/playwright-excel', 'community', 'Rukkha1024', 'post_auto_work', 'Rukkha1024/post_auto_work', 'playwright-excel', 0, 0, 44, '2026-03-08T01:57:15.428Z', '2026-03-08T02:07:29.272Z', '586bac4cea916ef62e39751488a2e323eee10069dc2910b55b42d3f47470e2bc', '{"id":"Rukkha1024/post_auto_work/playwright-excel","name":"playwright-excel","description":{"en":"The playwright-excel skill converts Playwright codegen scripts into Excel-driven automations, centralizing configuration and requiring Playwright CLI validation. It is designed for developers and QA engineers who use Playwright for browser automation and need to manage test data and flows within ...","zh":"Playwright Excel集成工具可以将codegen脚本转换为Excel驱动的自动化，使用集中化配置和CLI验证","ja":"Playwright Excel統合ツールは、codegenスクリプトをExcel駆動の自動化に変換し、集中化された構成とCLI検証を使用します","ko":"Playwright Excel 통합 도구는 codegen 스크립트를 Excel 드라이버 자동화로 변환하여集中화된 구성과 CLI 검증을 사용합니다","es":"Playwright-excel es una integración que convierte scripts de codegen de Playwright en automatizaciones con Excel y configuración centralizada","fr":"Playwright-excel est une intégration qui convertit les scripts de codegen de Playwright en automatisations Excel avec une configuration centralisée","de":"Playwright-excel ist eine Integration, die Playwright-Codegen-Skripte in Excel-Automatisierungen mit zentraler Konfiguration umwandelt","pt":"O Playwright Excel é uma ferramenta de automação que converte scripts de codegen em automações dirigidas por Excel","ru":"Playwright Excel - это инструмент для автоматизации, который преобразует сценарии codegen в автоматизацию, управляемую Excel","ar":"أداة Playwright Excel هي أداة آليّة تحول البرامج النصية المولّدة تلقائيًا إلى آليّات مدفوعة ببرنامج Excel"},"seo":{"title":{"en":"playwright-excel: Convert Codegen Scripts to Excel Automa...","zh":"Playwright Excel集成设置指南"