INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Rukkha1024/post_auto_work/playwright-excel', 'playwright-excel', 'Rukkha1024', 'post_auto_work', 'community', 'playwright-excel Rukkha1024 post_auto_work community The playwright-excel skill converts Playwright codegen scripts into Excel-driven automations, centralizing configuration and requiring Playwright CLI validation. It is designed for developers and QA engineers who use Playwright for browser automation and need to manage test data and flows within ... Playwright Excel集成工具可以将codegen脚本转换为Excel驱动的自动化，使用集中化配置和CLI验证 Playwright Excel統合ツールは、codegenスクリプトをExcel駆動の自動化に変換し、集中化された構成とCLI検証を使用します Playwright Excel 통합 도구는 codegen 스크립트를 Excel 드라이버 자동화로 변환하여集中화된 구성과 CLI 검증을 사용합니다 Playwright-excel es una integración que convierte scripts de codegen de Playwright en automatizaciones con Excel y configuración centralizada Playwright-excel est une intégration qui convertit les scripts de codegen de Playwright en automatisations Excel avec une configuration centralisée Playwright-excel ist eine Integration, die Playwright-Codegen-Skripte in Excel-Automatisierungen mit zentraler Konfiguration umwandelt O Playwright Excel é uma ferramenta de automação que converte scripts de codegen em automações dirigidas por Excel Playwright Excel - это инструмент для автоматизации, который преобразует сценарии codegen в автоматизацию, управляемую Excel أداة Playwright Excel هي أداة آليّة تحول البرامج النصية المولّدة تلقائيًا إلى آليّات مدفوعة ببرنامج Excel how to use playwright-excel what is playwright-excel playwright excel integration playwright codegen to excel playwright-excel setup guide playwright-excel install playwright-excel vs selenium excel browser automation with excel playwright conda environment Playwright Excel集成 codegen脚本 Excel驱动自动化 集中化配置 CLI验证 conda环境 Python脚本执行 AIエージェント工具 Converts Playwright codegen script paths into Excel-driven automations Requires execution within the `playwright` conda environment Validates inputs using Playwright CLI Maps hardcoded values from scripts to Excel data via `.xlsx` files Uses `conda run -n playwright python` for Python command execution Explicitly prohibits the use of venv or .venv environments playwright-excel is an AI Agent skill that transforms Playwright codegen scripts into Excel-driven automations. It uses a specified conda environment for execution and maps hardcoded values from scripts to Excel data for centralized configuration management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pythrick/codex-conductor/conductor', 'community', 'pythrick', 'codex-conductor', 'pythrick/codex-conductor', 'conductor', 0, 0, 44, '2026-03-08T01:57:15.426Z', '2026-03-08T02:07:30.902Z', 'eb4d9403b67dd31f4512155c4966bbc44d56120e69b199bbc61dd3b445af9df0', '{"id":"pythrick/codex-conductor/conductor","name":"conductor","description":{"en":"The Conductor skill enables AI agents to create and maintain Conductor artifacts for Gemini Conductor extension compatibility, streamlining workflow management for developers.","zh":"Conductor兼容性技能用于创建和维护Conductor工件，确保与Gemini Conductor扩展和工作流程的兼容性。它支持设置新项目上下文、开始新轨道、实现或恢复轨道、检查进度或还原工作","ja":"Conductor相互運用性スキルは、Conductorアーティファクトを作成および維持し、Gemini Conductor拡張機能およびワークフローとの互換性を確保するために使用されます。新しいプロジェクトコンテキストの設定、新的軌道の開始、軌道の実装または再開、進度の確認、または作業の復元をサポートします","ko":"Conductor 호환성 스킬은 Conductor 아티팩트를 생성 및 유지하고 Gemini Conductor 확장 및 워크플로우와의 호환성을 보장하는 데 사용됩니다. 새로운 프로젝트 컨텍스트 설정, 새로운 트랙 시작, 트랙 구현 또는 재개, 진행 상황 확인 또는 작업 되돌리기를 지원합니다","es":"Esta skill de IA para desarrolladores automatiza la creación y el mantenimiento de artefactos de Conductor, asegurando la compatibilidad total con el flujo de trabajo Contexto -> Especificación & Plan -> Implementación de la extensión Gemini.","fr":"Cet outil IA pour développeurs automatise la création et la maintenance des artefacts Conductor, garantissant une compatibilité totale avec le flux de travail Contexte -> Spécification & Plan -> Implémentation de l''extension Gemini.","de":"Dieses KI-Tool für Entwickler automatisiert die Erstellung und Pflege von Conductor-Artefakten und gewährleistet volle Kompatibilität mit dem Gemini-Erweiterungs-Workflow Kontext -> Spezifikation & Plan -> Implementierung.","pt":"O Conductor é uma habilidade de codex que cria e mantém artefatos compatíveis com a extensão Gemini Conductor. Utilize-o para configurar novos projetos e 