INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pythrick/codex-conductor/conductor', 'conductor', 'pythrick', 'codex-conductor', 'community', 'conductor pythrick codex-conductor community The Conductor skill enables AI agents to create and maintain Conductor artifacts for Gemini Conductor extension compatibility, streamlining workflow management for developers. Conductor兼容性技能用于创建和维护Conductor工件，确保与Gemini Conductor扩展和工作流程的兼容性。它支持设置新项目上下文、开始新轨道、实现或恢复轨道、检查进度或还原工作 Conductor相互運用性スキルは、Conductorアーティファクトを作成および維持し、Gemini Conductor拡張機能およびワークフローとの互換性を確保するために使用されます。新しいプロジェクトコンテキストの設定、新的軌道の開始、軌道の実装または再開、進度の確認、または作業の復元をサポートします Conductor 호환성 스킬은 Conductor 아티팩트를 생성 및 유지하고 Gemini Conductor 확장 및 워크플로우와의 호환성을 보장하는 데 사용됩니다. 새로운 프로젝트 컨텍스트 설정, 새로운 트랙 시작, 트랙 구현 또는 재개, 진행 상황 확인 또는 작업 되돌리기를 지원합니다 Esta skill de IA para desarrolladores automatiza la creación y el mantenimiento de artefactos de Conductor, asegurando la compatibilidad total con el flujo de trabajo Contexto -> Especificación & Plan -> Implementación de la extensión Gemini. Cet outil IA pour développeurs automatise la création et la maintenance des artefacts Conductor, garantissant une compatibilité totale avec le flux de travail Contexte -> Spécification & Plan -> Implémentation de l''extension Gemini. Dieses KI-Tool für Entwickler automatisiert die Erstellung und Pflege von Conductor-Artefakten und gewährleistet volle Kompatibilität mit dem Gemini-Erweiterungs-Workflow Kontext -> Spezifikation & Plan -> Implementierung. O Conductor é uma habilidade de codex que cria e mantém artefatos compatíveis com a extensão Gemini Conductor. Utilize-o para configurar novos projetos e gerenciar o fluxo de trabalho Conductor - это навык кодекса, который создает и поддерживает артефакты, совместимые с расширением Gemini Conductor. Используйте его для настройки новых проектов и управления рабочим процессом موصل هو مهارة كودكس لإنشاء مكونات متوافقة مع ملحق Gemini Conductor. استخدمه لإعداد مشاريع جديدة وإدارة العملية how to use conductor conductor setup guide conductor vs gemini conductor install what is conductor conductor alternative conductor workflow management gemini conductor extension conductor compatibility Conductor兼容性 Gemini Conductor扩展 Codex技能 Conductor工件 工作流程兼容性 项目上下文设置 轨道开始 进度检查 Creates product.md files for project context setup Generates tech-stack.md files for tracking technical dependencies Maintains setup_state.json files for workflow management Supports implementation and resumption of tracks via workflow.md files Ensures compatibility with Gemini Conductor extension and its workflow Requires a specific file structure for Conductor artifacts Conductor is a skill for creating and maintaining Conductor artifacts to ensure compatibility with the Gemini Conductor extension and its workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bebopbabailey/homelab-llm/homelab-durability', 'community', 'bebopbabailey', 'homelab-llm', 'bebopbabailey/homelab-llm', 'homelab-durability', 0, 0, 44, '2026-03-08T01:57:15.433Z', '2026-03-08T02:07:35.191Z', '8b26cf3b7e9125bcff57eacfab7017af4a70d2d77c41025e5031ecb2d7c029c7', '{"id":"bebopbabailey/homelab-llm/homelab-durability","name":"homelab-durability","description":{"en":"homelab-durability is a monorepo that provides a foundation for AI agents, offering sources of truth and execution contracts for reliable operation. It benefits developers seeking to build durable homelabs.","zh":"Homelab持久性是一个关键概念，涉及Sources of Truth和Execution Contract，用于优化AI工具性能","ja":"Homelab耐久性は、Sources of TruthとExecution Contractを含む重要な概念であり、AIエージェントのパフォーマンスを最適化するために使用されます","ko":"Homelab 내구성은 Sources of Truth와 Execution Contract를 포함하는 중요한 개념으로 AI 에이전트 성능을 최적화하는 데 사용됩니다","es":"Homelab-durability es un conjunto de prácticas y guías para mejorar la durabilidad de los Agentes de IA, incluyendo la configuración de umbrales de descarga y verificación de disco","fr":"Homelab-durability est un ensemble de pratiques et de guides pour améliorer la durabilité des Outils d''IA, notamment la configuration des seuils de téléchargement et de vérification de disque","de":"Homelab-durability ist ein Satz von Praktiken und Leitfäden, um die Haltbarkeit von KI-Agents zu verbessern, einschließlich der Konfiguration von Download-Schwellenwerten und Plattenprüfung","pt":"O Homelab Durability é um conjunto de práticas e configurações para garantir a estabilidade e segurança do seu laboratório de desenvolvimento","ru":"Homelab Durability - это набор практик и настроек для обеспечения стабильности и безопасности вашей разработческой лаборатории","ar":"أداة Homelab Durability هي مجموعة من الممارسات والإعدادات لتأمين الاستقرار والأمان لمختبر تطويرك"},"seo":{"title":{"en":"homelab-durability: Setup Guide for AI Agents | AI Agent ...","zh":"Homelab 持久性设置指南 - AI工具","ja":"Homelab 耐久性のベストプラクティス - AIエージェント","ko":"Homelab 내구성 설정 가이드 - AI 에이전트","es":"Guía de configuración de homelab-durability para Agentes ...","fr":"Guide de configuration de homelab-durability pour les Out...","de":"Einrichtungsleitfaden für homelab-durability in KI-Agents","pt":"Guia de Configuração de Durabilidade de Homelab para Dese...","ru":"ИИ Агенты: Руководство по Настройке Homelab Durability","ar":"إعداد أداة Homelab Durability للبرمجة"},"description":{"en":"Discover how to configure homelab-durability for optimal performance. Learn about sources of truth, execution contracts, and defaults for a robust AI agent s...","zh":"了解Homelab持久性的关键概念，包括Sources of Truth和Execution Contract，优化您的AI工具性能","ja":"Homelab耐久性の重要性と、Sources of TruthやExecution Contractの設定方法を学びましょう - AIエージェント","ko":"Homelab 내구성의 핵심 개념과 Sources of Truth 및 Execution Contract 설정을 통해 AI 에이전트 성능을 최적화하십시오","es":"Aprende a configurar homelab-durability para mejorar la durabilidad de tus Agentes de IA con nuestras mejores prácticas y guías técnicas","fr":"Découvrez comment configurer homelab-durability pour améliorer la durabilité de vos Outils d''IA avec nos meilleures pratiques et guides techniques","de":"Erfahren Sie, wie Sie homelab-durability konfigurieren, um die Haltbarkeit Ihrer KI-Agents zu verbessern, mit unseren besten Praktiken und technischen Leitfäden","pt":"Aprenda a configurar a durabilidade do Homelab com nossas melhores práticas e dicas técnicas para desenvolvedores","ru":"Узнайте, как настроить Homelab Durability с помощью наших рекомендаций и технических советов для разработчиков","ar":"تعرف على كيفية إعداد أداة Homelab Durability باستخدام أفضل الممارسات وأفضل النصائح الفنية للمطورين"},"definition":{"en":"homelab-durability is a technical framework that ensures reliable operation of AI agents through strict execution contracts and conservative defaults.","zh":"Homelab持久性是指优化AI工具性能的能力，涉及Sources of Truth和Execution Contract","ja":"Homelab耐久性とは、AIエージェントのパフォーマンスを最適化する能力であり、Sources of TruthとExecution Contractを含みます","ko":"Homelab 내구성은 AI 에이전트 성능을 최적화하는 능력으로 Sources of Truth와 Execution Contract를 포함합니다","es":"Homelab-durability se refiere a un conjunto de prácticas y guías para mejorar la durabilidad de los Agentes de IA","fr":"Homelab-durability fait référence à un ensemble de pratiques et de guides pour améliorer la durabilité des Outils d''IA","de":"Homelab-durability bezeichnet einen Satz von Praktiken und Leitfäden, um die Haltbarkeit von KI-Agents zu verbessern","pt":"Homelab Durability é um conjunto de técnicas para garantir a durabilidade e confiabilidade do seu laboratório de desenvolvimento","ru":"Homelab Durability - это набор техник для обеспечения долговечности и надежности вашей разработческой лаборатории","ar":"أداة Homelab Durability هي مجموعة من التقنيات لتأمين متانة وثبات مختبر تطويرك"},"features":{"en":["References sources of truth from docs/_core/OPERATING_MODEL.md and docs/_core/SOURCES_OF_TRUTH.md","Enforces strict execution contracts for reliable operation","Implements conservative defaults, including a 500MB download approval threshold","Requires disk checks before model downloads or large actions","Supports topology configuration via docs/foundation/topology.md","Provides a PLATFORM_DOSSIER for detailed documentation"],"zh":["Sources of Truth文档支持","Execution Contract设置","下载批准阈值设置（500MB）","磁盘检查要求支持","显式大型动作支持（>5GB）"],"ja":["Sources of Truthドキュメントのサポート","Execution Contractの設定","ダウンロード承認閾値の設定（500MB）","ディスクチェック要求のサポート","明示的な大きなアクションのサポート（>5GB）"],"ko":["Sources of Truth 문서 지원","Execution Contract 설정","다운로드 승인 임계값 설정（500MB）","디스크 확인 요구 사항 지원","명시적인 큰 동작 지원（>5GB）"],"es":["Configuración de umbrales de descarga de 500MB","Verificación de disco requerida antes de cualquier acción de descarga o caché","Soporte para modelos de operación y topología de red","Integración con CONSTRAINTS.md y PLATFORM_DOSSIER.md","Compatibilidad con operaciones de descarga y caché de más de 5GB","Cumplimiento estricto de las reglas de cambio y operación"],"fr":["Configuration des seuils de téléchargement de 500Mo","Vérification de disque requise avant toute action de téléchargement ou de mise en cache","Prise en charge des modèles d''exploitation et de topologie de réseau","Intégration avec CONSTRAINTS.md et PLATFORM_DOSSIER.md","Compatibilité avec les opérations de téléchargement et de mise en cache de plus de 5Go","Respect strict des règles de modification et d''exploitation"],"de":["Konfiguration von Download-Schwellenwerten von 500MB","Plattenprüfung erforderlich vor jeder Download- oder Cache-Aktion","Unterstützung für Betriebsmodelle und Netzwerktopologie","Integration mit CONSTRAINTS.md und PLATFORM_DOSSIER.md","Kompatibilität mit Download- und Cache-Operationen von über 5GB","Strenger Einhaltung der Änderungs- und Betriebsregeln"],"pt":["Configuração de fontes de verdade para garantir a consistência dos dados","Execução de contratos estritos para garantir a segurança do laboratório","Definição de limites de download e verificação de disco para evitar problemas de desempenho","Utilização de modelos de operação e topologia para garantir a escalabilidade do laboratório","Implementação de regras de mudança para garantir a estabilidade do laboratório"],"ru":["Настройка источников истины для обеспечения согласованности данных","Выполнение строгих контрактов для обеспечения безопасности лаборатории","Определение лимитов загрузки и проверка диска для предотвращения проблем с производительностью","Использование моделей операции и топологии для обеспечения масштабируемости лаборатории","Реализация правил изменения для обеспечения стабильности лаборатории"],"ar":["إعداد مصادر الحقيقة لضمان الاتساق في البيانات","تنفيذ عقود صارمة لضمان أمان مختبر التطوير","تحديد حدود التحميل والتحقق من القرص لتجنب مشاكل الأداء","استخدام نماذج التشغيل وال拓ولوجيا لضمان توسيع مختبر التطوير","تنفيذ قواعد التغيير لضمان استقرار مختبر التطوير"]},"keywords":{"en":["how to use homelab-durability","homelab-durability setup guide","homelab-durability alternative","homelab-durability vs other AI agent skills","what is homelab-durability","homelab-durability install","homelab-durability configuration","homelab-durability sources of truth","homelab-durability execution contracts"],"zh":["Homelab持久性","AI工具","Sources of Truth","Execution Contract","下载批准阈值","磁盘检查要求"],"ja":["Homelab耐久性","AIエージェント","Sources of Truth","Execution Contract","ダウンロード承認閾値","ディスクチェック要求"],"ko":["Homelab 내구성","AI 에이전트","Sources of Truth","Execution Contract","다운로드 승인 임계값","디스크 확인 요구 사항"],"es":["homelab-durability","Agentes de IA","configuración de umbrales de descarga","verificación de disco","modelos de operación","topología de red","CONSTRAINTS.md","PLATFORM_DOSSIER.md","descarga y caché de modelos"],"fr":["homelab-durability","Outils d''IA","configuration des seuils de téléchargement","vérification de disque","modèles d''exploitation","topologie de réseau","CONSTRAINTS.md","PLATFORM_DOSSIER.md","téléchargement et mise en cache de modèles"],"de":["homelab-durability","KI-Agents","Konfiguration von Download-Schwellenwerten","Plattenprüfung","Betriebsmodelle","Netzwerktopologie","CONSTRAINTS.md","PLATFORM_DOSSIER.md","Download- und Cache-Operationen von Modellen"],"pt":["homelab durability","desenvolvimento de software","laboratório de desenvolvimento","segurança do laboratório","estabilidade do laboratório","configuração de fontes de verdade","execução de contratos estritos","definição de limites de download","verificação de disco"],"ru":["ИИ Агенты","Homelab Durability","разработка программного обеспечения","лаборатория разработки","безопасность лаборатории","стабильность лаборатории","настройка источников истины","выполнение строгих контрактов","определение лимитов загрузки","проверка диска"],"ar":["أداة Homelab Durability","تطوير البرمجيات","مختبر التطوير","أمان مختبر التطوير","استقرار مختبر التطوير","إعداد مصادر الحقيقة","تنفيذ عقود صارمة","تحديد حدود التحميل","التحقق من القرص"]}},"owner":"bebopbabailey","repo":"homelab-llm","repoPath":"bebopbabailey/homelab-llm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.433Z","topics":[],"category":"community","skillMd":{"name":"homelab-durability","description":"Enforce docs-first, minimal-contract, validation-heavy workflow; prevent cross-host mistakes and scope creep.","bodyPreview":"# Homelab Durability\n\n## Sources of Truth (Must read first)\n- docs/_core/OPERATING_MODEL.md\n- docs/_core/SOURCES_OF_TRUTH.md\n- docs/_core/CHANGE_RULES.md\n- docs/foundation/operating-rhythm.md\n- layer-gateway/CONSTRAINTS.md\n- docs/foundation/topology.md\n- docs/PLATFORM_DOSSIER.md\n\n## Execution Contract (Strict)\n\n## Defaults (Conservative)\n- Download approval threshold: 500MB.\n- Disk check required before any model download/cache action or any explicitly large (>5GB) action: YES.\n- Host confirmati","body":"# Homelab Durability\n\n## Sources of Truth (Must read first)\n- docs/_core/OPERATING_MODEL.md\n- docs/_core/SOURCES_OF_TRUTH.md\n- docs/_core/CHANGE_RULES.md\n- docs/foundation/operating-rhythm.md\n- layer-gateway/CONSTRAINTS.md\n- docs/foundation/topology.md\n- docs/PLATFORM_DOSSIER.md\n\n## Execution Contract (Strict)\n\n## Defaults (Conservative)\n- Download approval threshold: 500MB.\n- Disk check required before any model download/cache action or any explicitly large (>5GB) action: YES.\n- Host confirmation: strict for ops commands, but may be treated as sticky within the same session after explicit confirmation.\n- Violations: HARD-BLOCK for MLX/disk/host/file-list rules; WARN for stylistic rules.\n\n## Workflow Rules (Behavioral)\n- Use `SCRATCH_PAD.md` only when the user asks. This is mainly for use if user needs to run \n  commands themselves or asks to review commands/outputs/diffs; otherwise inline is acceptable.\n- `NOW.md` must reflect the active development task; update it when the active work changes.\n- `NOW.md` contains only active work + a single “NEXT UP” section. Everything else goes to `BACKLOG.md`.\n- Journal entries are append-only. Do not move or delete files in `docs/journal/`.\n  If a correction is needed, add a new dated entry and update `docs/journal/index.md`.\n\n### Required startup declarations\nEvery response MUST begin by stating:\n1) **Host** (Mini vs Studio vs Orin)\n2) **Scope** (layer/service)\n3) **Files** (explicit list of intended files to change)\n\n### Hard-block rules (must refuse)\n- No multi-file edits without an explicit file list.\n- No ops commands unless **Host Check** is explicitly satisfied in the same response.\n- No restarts/service modifications unless **Stage = Validate** and a rollback is specified.\n- No disk repair / fsck / apfs repair / partition changes without explicit user approval.\n- MLX backends: MUST use `mlxctl` + registry as source of truth. No ad-hoc edits or direct `mlx-openai-server` control unless explicitly authorized.\n- Any download/cache/model pull > 500MB requires explicit user approval.\n\n### Disk guardrail\n- Before any model download/cache action or any explicitly large (>5GB) action, require a disk free check command suggestion and STOP until user confirms.\n\n### Default stance\n- Default to read-only inspection first.\n\n### Host Check (required before ops commands)\n- Explicitly confirm target host and its role.\n- If not confirmed, STOP and ask for confirmation.\n\n## Preferred Operating Rhythm\nInventory → Constraints → Minimal contract → Wire → Validate → Codify → Prune\n\n## Output Format (Required)\nMode: Discover|Design|Build|Verify\nStage: Inventory|Constraints|Minimal Contract|Wire|Validate|Codify|Prune\nHost: <explicit>\nScope: <layer/service>\nProposed Change: <one paragraph>\nFiles: <explicit list>\nCommands: <copy/paste safe; no wrapped lines>\nValidation: <commands>\nRollback: <commands>\n\n## How to use\n- Invoke by name: \"use homelab-durability\"\n- Behavior changes:\n  - Host check gate before any ops commands\n  - File list gate before edits\n  - Validation gate requires rollback for restarts\n"},"lastSynced":"2026-03-08T02:07:35.191Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing reliable homelab operation and durability, particularly those utilizing operating models and execution contracts.","zh":"非常适合需要可靠的家庭实验室操作和耐用性的 AI Agent，特别是那些使用操作模型和执行合约的 Agent。","ja":"信頼性の高いホームラボ操作と耐久性が必要な AI エージェントに最適です。特に、運用モデルと実行契約を使用するエージェントに適しています。","ko":"안정적인 홈 랩 운영과 내구성이 필요한 AI 에이전트에게 적합합니다. 특히 운영 모델과 실행 계약을 사용하는 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA que necesitan una operación de homelab confiable y duradera, particularmente aquellos que utilizan modelos de operación y contratos de ejecución.","fr":"Parfait pour les agents IA nécessitant une exploitation de homelab fiable et durable, en particulier ceux utilisant des modèles de fonctionnement et des contrats d''exécution.","de":"Perfekt für KI-Agents, die eine zuverlässige Homelab-Betrieb und Haltbarkeit benötigen, insbesondere solche, die Betriebsmodelle und Ausführungsverträge verwenden.","pt":"Perfeito para Agentes de IA que precisam de operação de homelab confiável e durabilidade, particularmente aqueles que utilizam modelos de operação e contratos de execução.","ru":"Идеально для ИИ-агентов, требующих надежной работы homelab и долговечности, особенно тех, которые используют операционные модели и контракты выполнения.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تشغيل homelab موثوق ومتانة، خاصة تلك التي تستخدم نماذج تشغيلية وعقود تنفيذ."},"recommendation":{"en":"Empowers agents to ensure reliable operation by providing sources of truth, such as OPERATING_MODEL.md and SOURCES_OF_TRUTH.md, and enforcing strict execution contracts with conservative defaults, including disk checks and download approval thresholds, utilizing Markdown documentation and layer-gateway constraints.","zh":"通过提供真实来源（如 OPERATING_MODEL.md 和 SOURCES_OF_TRUTH.md）并强制执行严格的执行合约（包括磁盘检查和下载批准阈值），同时利用 Markdown 文档和层网关约束，赋予代理确保可靠操作的能力。","ja":"OPERATING_MODEL.md や SOURCES_OF_TRUTH.md などの真実の情報源を提供し、厳格な実行契約（ディスク チェックやダウンロード承認閾値を含む）を強制的に実施し、さらに Markdown ドキュメントやレイヤーゲートウェイ制約を利用することで、エージェントが信頼性の高い操作を確保できるようにします。","ko":"OPERATING_MODEL.md와 SOURCES_OF_TRUTH.md와 같은 진실한 정보원을 제공하고, 엄격한 실행 계약(디스크 체크 및 다운로드 승인 임계값 포함)을 강제로施行하며, 마크다운 문서 및 계층 게이트웨이 제약을 활용하여 에이전트가 안정적인 작동을 보장할 수 있도록 합니다.","es":"Habilita a los agentes a garantizar una operación fiable proporcionando fuentes de verdad, como OPERATING_MODEL.md y SOURCES_OF_TRUTH.md, y aplicando contratos de ejecución estrictos con valores predeterminados conservadores, incluyendo comprobaciones de disco y umbrales de aprobación de descargas, utilizando la documentación Markdown y restricciones de capa-puerta.","fr":"Habilite les agents à assurer une exploitation fiable en fournissant des sources de vérité, telles que OPERATING_MODEL.md et SOURCES_OF_TRUTH.md, et en appliquant des contrats d''exécution stricts avec des valeurs par défaut conservatrices, notamment des vérifications de disque et des seuils d''approbation de téléchargement, en utilisant la documentation Markdown et les contraintes de couche-passerelle.","de":"Ermächtigt Agents, eine zuverlässige Ausführung sicherzustellen, indem es Quellen der Wahrheit wie OPERATING_MODEL.md und SOURCES_OF_TRUTH.md bereitstellt und strikte Ausführungsverträge mit konservativen Standardwerten durchsetzt, einschließlich Plattenprüfungen und Download-Genehmigungsschwellen, unter Verwendung der Markdown-Dokumentation und Schicht-Tor-Einschränkungen.","pt":"Habilita os agentes a garantir a operação confiável, fornecendo fontes de verdade, como OPERATING_MODEL.md e SOURCES_OF_TRUTH.md, e aplicando contratos de execução estritos com padrões conservadores, incluindo verificações de disco e limiares de aprovação de download, utilizando documentação Markdown e restrições de gateway de camada.","ru":"Наделяет агентов возможностью обеспечить надежную работу, предоставляя источники истинных данных, такие как OPERATING_MODEL.md и SOURCES_OF_TRUTH.md, и применяя строгие контракты выполнения с консервативными настройками по умолчанию, включая проверки диска и пороги одобрения загрузки, используя документацию Markdown и ограничения шлюза уровня.","ar":"يمنح الوكلاء القدرة على ضمان التشغيل الموثوق، من خلال تقديم مصادر للحقيقة، مثل OPERATING_MODEL.md و SOURCES_OF_TRUTH.md، وتطبيق عقود تنفيذ صارمة مع إعدادات mặcأفة محافظة، بما في ذلك فحوصات القرص وعتبات موافقة التنزيل، باستخدام توثيق Markdown وقيود بوابة الطبقة."},"useCases":{"en":["Enforcing strict execution contracts for reliable homelab operation","Managing sources of truth for consistent decision-making","Configuring conservative defaults for safe model downloads and caching"],"zh":["强制执行严格的执行合约以确保可靠的家庭实验室操作","管理真实来源以进行一致的决策","配置保守的默认值以安全地下载和缓存模型"],"ja":["信頼性の高いホームラボ操作を確保するために、厳格な実行契約を強制的に実施する","一貫した意思決定を行うために、真実の情報源を管理する","モデルを安全にダウンロードしてキャッシュするために、保守的なデフォルト値を設定する"],"ko":["안정적인 홈 랩 운영을 보장하기 위해 엄격한 실행 계약을 강제로施行한다","일관된 의사 결정을 위해 진실한 정보원을 관리한다","모델을 안전하게 다운로드하고 캐시하기 위해 보수적인 기본값을 구성한다"],"es":["Aplicar contratos de ejecución estrictos para una operación de homelab confiable","Gestionar fuentes de verdad para una toma de decisiones coherente","Configurar valores predeterminados conservadores para descargas de modelos seguras y caché"],"fr":["Appliquer des contrats d''exécution stricts pour une exploitation de homelab fiable","Gérer les sources de vérité pour une prise de décision cohérente","Configurer des valeurs par défaut conservatrices pour des téléchargements de modèles sécurisés et un cache"],"de":["Durchsetzen strikter Ausführungsverträge für eine zuverlässige Homelab-Ausführung","Verwalten von Quellen der Wahrheit für eine konsistente Entscheidungsfindung","Konfigurieren konservativer Standardwerte für sichere Modell-Downloads und Caching"],"pt":["Aplicar contratos de execução estritos para operação de homelab confiável","Gerenciar fontes de verdade para tomada de decisão consistente","Configurar padrões conservadores para downloads de modelo seguros e cache"],"ru":["Применять строгие контракты выполнения для надежной работы homelab","Управлять источниками истинных данных для последовательного принятия решений","Настроить консервативные настройки по умолчанию для безопасных загрузок моделей и кэширования"],"ar":["تطبيق عقود تنفيذ صارمة لتشغيل homelab موثوق","إدارة مصادر للحقيقة لاتخاذ قرارات متسقة","تكوين إعدادات mặcأفة محافظة لتنزيلات نموذجية آمنة وتخزين مؤقت"]},"limitations":{"en":["Requires adherence to specified operating models and change rules","Needs Markdown documentation for sources of truth","Imposes a download approval threshold of 500MB and requires disk checks for large actions"],"zh":["需要遵守指定的操作模型和更改规则","需要 Markdown 文档来提供真实来源","施加 500MB 的下载批准阈值，并需要对大型操作进行磁盘检查"],"ja":["指定された運用モデルと変更ルールに従う必要がある","真実の情報源を提供するために Markdown ドキュメントが必要","500MB のダウンロード承認閾値を課し、大規模な操作にはディスク チェックが必要"],"ko":["지정된 운영 모델과 변경 규칙을 따라야 한다","진실한 정보원을 제공하기 위해 마크다운 문서가 필요하다","500MB의 다운로드 승인 임계값을 부과하며, 대형 작용에는 디스크 체크가 필요하다"],"es":["Requiere adherencia a los modelos de operación y reglas de cambio especificados","Necesita documentación Markdown para fuentes de verdad","Establece un umbral de aprobación de descarga de 500 MB y requiere comprobaciones de disco para acciones grandes"],"fr":["Nécessite l''adhésion aux modèles de fonctionnement et aux règles de modification spécifiées","Nécessite une documentation Markdown pour les sources de vérité","Fixe un seuil d''approbation de téléchargement de 500 Mo et nécessite des vérifications de disque pour les actions importantes"],"de":["Erfordert die Einhaltung der angegebenen Betriebsmodelle und Änderungsregeln","Benötigt Markdown-Dokumentation für Quellen der Wahrheit","Setzt eine Download-Genehmigungsschwelle von 500 MB und erfordert Plattenprüfungen für große Aktionen"],"pt":["Exige adesão a modelos de operação especificados e regras de alteração","Necessita de documentação Markdown para fontes de verdade","Impõe um limiar de aprovação de download de 500MB e exige verificações de disco para ações grandes"],"ru":["Требует соблюдения указанных операционных моделей и правил изменения","Требует документации Markdown для источников истинных данных","Вводит порог одобрения загрузки 500МБ и требует проверок диска для крупных действий"],"ar":["يتطلب الالتزام بنماذج تشغيلية محددة وقواعد التغيير","يتطلب توثيق Markdown لمصادر للحقيقة","يفرض عتبة موافقة تحميل 500MB ويتطلب فحوصات قرص لعمل كبيرة"]},"version":4},"contentHash":"8b26cf3b7e9125bcff57eacfab7017af4a70d2d77c41025e5031ecb2d7c029c7","qualityScore":44}');
DELETE FROM skills_fts WHERE id = 'bebopbabailey/homelab-llm/homelab-durability';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bebopbabailey/homelab-llm/homelab-durability', 'homelab-durability', 'bebopbabailey', 'homelab-llm', 'community', 'homelab-durability bebopbabailey homelab-llm community homelab-durability is a monorepo that provides a foundation for AI agents, offering sources of truth and execution contracts for reliable operation. It benefits developers seeking to build durable homelabs. Homelab持久性是一个关键概念，涉及Sources of Truth和Execution Contract，用于优化AI工具性能 Homelab耐久性は、Sources of TruthとExecution Contractを含む重要な概念であり、AIエージェントのパフォーマンスを最適化するために使用されます Homelab 내구성은 Sources of Truth와 Execution Contract를 포함하는 중요한 개념으로 AI 에이전트 성능을 최적화하는 데 사용됩니다 Homelab-durability es un conjunto de prácticas y guías para mejorar la durabilidad de los Agentes de IA, incluyendo la configuración de umbrales de descarga y verificación de disco Homelab-durability est un ensemble de pratiques et de guides pour améliorer la durabilité des Outils d''IA, notamment la configuration des seuils de téléchargement et de vérification de disque Homelab-durability ist ein Satz von Praktiken und Leitfäden, um die Haltbarkeit von KI-Agents zu verbessern, einschließlich der Konfiguration von Download-Schwellenwerten und Plattenprüfung O Homelab Durability é um conjunto de práticas e configurações para garantir a estabilidade e segurança do seu laboratório de desenvolvimento Homelab Durability - это набор практик и настроек для обеспечения стабильности и безопасности вашей разработческой лаборатории أداة Homelab Durability هي مجموعة من الممارسات والإعدادات لتأمين الاستقرار والأمان لمختبر تطويرك how to use homelab-durability homelab-durability setup guide homelab-durability alternative homelab-durability vs other AI agent skills what is homelab-durability homelab-durability install homelab-durability configuration homelab-durability sources of truth homelab-durability execution contracts Homelab持久性 AI工具 Sources of Truth Execution Contract 下载批准阈值 磁盘检查要求 References sources of truth from docs/_core/OPERATING_MODEL.md and docs/_core/SOURCES_OF_TRUTH.md Enforces strict execution contracts for reliable operation Implements conservative defaults, including a 500MB download approval threshold Requires disk checks before model downloads or large actions Supports topology configuration via docs/foundation/topology.md Provides a PLATFORM_DOSSIER for detailed documentation homelab-durability is a technical framework that ensures reliable operation of AI agents through strict execution contracts and conservative defaults.');
