INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rickyraz/learn-three-typegpu-claude/three-best-practices', 'three-best-practices', 'rickyraz', 'learn-three-typegpu-claude', 'community', 'three-best-practices rickyraz learn-three-typegpu-claude community This AI agent skill provides a comprehensive performance optimization guide for Three.js applications, featuring 100+ prioritized rules across 17 categories. It is based on official guidelines from the Three.js `llms` branch and is essential for developers working with WebGPU, custom shaders, and... Three.js 优化指南提供了100+条规则，帮助开发者优化Three.js应用的性能和内存 Three.js 最適化ガイドは、100以上のルールを提供し、開発者がThree.jsアプリのパフォーマンスとメモリを最適化するのに役立ちます Three.js 최적화 가이드는 100개 이상의 규칙을 제공하여 개발자가 Three.js 애플리케이션의 성능과 메모리를 최적화하는 데 도움을줍니다 Guía de optimización de rendimiento para aplicaciones Three.js con 100+ reglas en 17 categorías. Basado en las directrices oficiales de Three.js. Guide d''optimisation des performances pour les applications Three.js avec plus de 100 règles dans 17 catégories. Basé sur les directives officielles de Three.js. Leitfaden für Performance-Optimierung für Three.js-Anwendungen mit 100+ Regeln in 17 Kategorien. Basierend auf den offiziellen Richtlinien von Three.js. Otimização de desempenho do Three.js com regras priorizadas por impacto. Baseado nas diretrizes oficiais do Three.js Оптимизация производительности Three.js с правилами, расположенными в порядке приоритета по воздействию. Основано на официальных руководствах Three.js تحسين أداء Three.js مع قواعد مصنفة حسب الأثر. مستندة إلى الإرشادات الرسمية لثري جيس three-best-practices performance guide how to optimize Three.js applications Three.js llms branch best practices three-best-practices vs manual optimization WebGPU implementation guide Three.js install three-best-practices AI agent Three.js GLSL shader optimization fix Three.js memory leaks three-best-practices setup guide Three.js 优化 Three.js 性能优化 Three.js 内存优化 Three.js 最佳实践 Three.js llms WebGPU GLSL TSL Contains 100+ performance optimization rules for Three.js Organizes best practices across 17 technical categories Based on official guidelines from the Three.js `llms` branch Provides guidance for custom shader development (GLSL/TSL) Includes optimization strategies for WebGPU implementation Offers prioritized rules for performance and memory leak fixes three-best-practices is an AI agent skill containing a comprehensive performance optimization guide for Three.js. It provides over 100 rules across 17 categories, based on official guidelines from the Three.js `llms` branch maintained by mrdoob.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rayhanadev/fresh/write-documentation', 'community', 'rayhanadev', 'fresh', 'rayhanadev/fresh', 'write-documentation', 0, 0, 44, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:05.520Z', '5055dd314a9377672e4e781af6658c157ac876473f7ac7d562589cfa7db9c6e3', '{"id":"rayhanadev/fresh/write-documentation","name":"write-documentation","description":{"en":"The write-documentation skill synchronizes code and documentation changes, ideal for developers working on public API additions, internal workflow changes, or new module implementations.","zh":"写文档功能帮助您保持代码和文档的同步，适用于公共API、内部工作流和架构变更","ja":"ドキュメント作成機能は、コードとドキュメントを同期させ、パブリックAPI、内部ワークフロー、またはアーキテクチャの変更に適応","ko":"문서화 기능은 코드와 문서를 동기화하고, 공개 API, 내부 워크플로, 아키텍처 변경에 대응","es":"Esta skill de IA Agent automatiza la creación y sincronización de documentación técnica. Identifica cambios en APIs públicas, workflows internos y nuevos módulos para generar docs precisas y actualizadas directamente desde el código.","fr":"Cette compétence d''outil IA automatise la création et la synchronisation de documentation technique. Identifie les changements d''API publique, workflows internes et nouveaux modules pour une docs précise et à jour directement depuis le code.","de":"Diese KI-Tool-Fähigkeit automatisiert die Erstellung und Synchronisierung technischer Dokumentation. Erkennt Änderungen an öffentlichen APIs, internen Workflows und neuen Modulen für präzise, codebasierte Docs.","pt":"O Write Documentation é uma habilidade que ajuda a manter o código e a documentação atualizados e sincronizados.","ru":"Write Documentation — это навык, который помогает поддерживать код и документацию в актуальном и синхронизированном состоянии.","ar":"Write Documentation هو مهارة تساعد على الحفاظ على التعليمات البرمجية والتوثيق محدثين ومتزامنين."},"seo":{"title":{"en":"Write-Documentation: Sync Code and Docs Setup Guide | AI ...","zh":"AIエージェント写文档设置指南","ja":"AIエージェントを使用したドキュメント作成ベストプラクティス","ko":"AI 에이전트를 이용한 문서화 가이드","es":"write-documentation: Guía para Sincronizar Código y Docs ...","fr":"write-documentation : Guide de Synchronisation Code-Docum...","de":"write-documentation: Leitfaden zur Code-Doku-Synchronisie...","pt":"Guia de Configuração do Write Documentation para Ferramen...","ru":"ИИ Агенты: Настройка Write Documentation для Синхронизаци...","ar":"دليل إعداد Write Documentation لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to keep code and documentation in sync with write-documentation. Learn when to use it and get started with our expert guide today!","zh":"使用AIエージェント写文档功能，保持代码和文档的同步，适用于公共API、内部工作流和架构变更","ja":"AIエージェントを使用して、コードとドキュメントを同期させ、パブリックAPI、内部ワークフロー、またはアーキテクチャの変更に適応","ko":"AI 에이전트를 사용하여 코드와 문서를 동기화하고, 공개 API, 내부 워크플로, 아키텍처 변경에 대응","es":"Automatiza la documentación con IA Agents para APIs públicas, cambios internos y nuevos módulos. Mantén la coherencia entre código y docs en cada commit.","fr":"Automatisez la documentation avec les outils IA pour les APIs publiques, changements internes et nouveaux modules. Gardez code et docs synchronisés à chaque ...","de":"Automatisieren Sie die Dokumentation mit KI-Tools für öffentliche APIs, interne Änderungen und neue Module. Halten Sie Code und Docs bei jedem Commit synchron.","pt":"Aprenda a manter o código e a documentação sincronizados com o Write Documentation, ideal para mudanças na API pública ou fluxo de trabalho interno.","ru":"Используйте Write Documentation для синхронизации кода и документации при изменениях публичного API или внутреннего рабочего процесса.","ar":"استخدم Write Documentation لتنظيم التعليمات البرمجية والتوثيق معًا عند إجراء تغييرات على واجهة برمجة التطبيقات العامة أو سير العمل الداخلي."},"definition":{"en":"write-documentation is a skill that ensures code and documentation consistency by identifying changes and updating relevant documents accordingly.","zh":"写文档是AIエージェント的一种功能，用于保持代码和文档的同步","ja":"ドキュメント作成は、AIエージェントの機能の一つで、コードとドキュメントを同期させる","ko":"문서화는 AI 에이전트의 기능 중 하나로, 코드와 문서를 동기화","es":"Write-documentation es una skill de IA Agent que mantiene la documentación sincronizada con el código. Analiza cambios en APIs públicas, comportamiento de usuario, arquitectura interna y nuevos módulos para generar docs precisas como parte del mismo commit.","fr":"Write-documentation est une compétence d''outil IA qui garde la documentation synchronisée avec le code. Analyse les changements d''API publique, comportement utilisateur, architecture interne et nouveaux modules pour une docs précise dans le même commit.","de":"Write-documentation ist eine KI-Tool-Fähigkeit, die Dokumentation mit Code synchron hält. Analysiert Änderungen an öffentlichen APIs, Nutzerverhalten, interner Architektur und neuen Modulen für präzise Docs im selben Commit.","pt":"O que é Write Documentation? É uma ferramenta de IA que mantém a documentação e o código sincronizados.","ru":"Что такое Write Documentation? Это инструмент ИИ, который поддерживает документацию и код в синхронизированном состоянии.","ar":"ما هي Write Documentation؟ هي أداة ذكاء اصطناعي تحافظ على التوثيق والتعليمات البرمجية متزامنين."},"features":{"en":["Identifies public API additions or signature changes for documentation updates","Detects internal workflow or architecture changes for guided documentation","Supports documentation for new modules or systems with discoverable guidance","Checks for touched entry points and exports to ensure comprehensive documentation","Identifies which source documents need updates for consistency"],"zh":["支持公共API的添加或签名变更","支持内部工作流或架构变更","支持新模块或系统的可发现性指南","自动识别变更的入口点和导出","自动识别当前源文档"],"ja":["パブリックAPIの追加または署名の変更をサポート","内部ワークフローまたはアーキテクチャの変更をサポート","新しいモジュールまたはシステムの可発見性ガイドをサポート","変更されたエントリーポイントとエクスポートを自動的に識別","現在のソースドキュメントを自動的に識別"],"ko":["공개 API의 추가 또는 서명의 변경을 지원","내부 워크플로 또는 아키텍처의 변경을 지원","새로운 모듈 또는 시스템의 가시성 가이드를 지원","변경된 진입점과 내보내기를 자동으로 식별","현재의 소스 문서를 자동으로 식별"],"es":["Sincronización automática para cambios de API pública y firmas","Documentación de comportamiento orientado al usuario","Actualización de docs para workflows y arquitectura interna","Detección de nuevos módulos y sistemas","Identificación de puntos de entrada y exports afectados","Chequeo de prerrequisitos para tipo de cambio (API/workflow/arch)"],"fr":["Synchronisation automatique pour changements d''API publique et signatures","Documentation du comportement utilisateur","Mise à jour docs pour workflows et architecture interne","Détection de nouveaux modules et systèmes","Identification des points d''entrée et exports impactés","Vérification préalable du type de changement (API/workflow/arch)"],"de":["Automatische Synchronisation für öffentliche API- und Signaturänderungen","Dokumentation nutzerorientierten Verhaltens","Aktualisierung für interne Workflows und Architektur","Erkennung neuer Module und Systeme","Identifikation betroffener Einstiegspunkte und Exports","Vorabprüfung des Änderungstyps (API/Workflow/Architektur)"],"pt":["Sincronização de código e documentação","Suporte para mudanças na API pública","Identificação de pontos de entrada e exportações afetados","Documentação para novos módulos e sistemas"],"ru":["Синхронизация кода и документации","Поддержка изменений публичного API","Идентификация затронутых точек входа и экспортов","Документация для новых модулей и систем"],"ar":["تنظيم التعليمات البرمجية والتوثيق","دعم للتغييرات على واجهة برمجة التطبيقات العامة","تحديد النقاط التي تمت إضافتها والتصدير المتأثر","توثيق لｍواد جديدة ونظم"]},"keywords":{"en":["how to use write-documentation","write-documentation setup guide","what is write-documentation","write-documentation alternative","write-documentation vs documentation tools","write-documentation install","public API documentation best practices","internal workflow documentation tips"],"zh":["AIエージェント写文档","代码文档同步","公共API变更","内部工作流变更","架构变更","新模块指导","自动识别变更"],"ja":["AIエージェントドキュメント作成","コードとドキュメントの同期","パブリックAPIの変更","内部ワークフローの変更","アーキテクチャの変更","新しいモジュールのガイド","自動的に識別された変更"],"ko":["AI 에이전트 문서화","코드와 문서의 동기화","공개 API의 변경","내부 워크플로의 변경","아키텍처의 변경","새로운 모듈의 가이드","자동으로 식별된 변경"],"es":["automatizar documentación técnica","sincronizar código y docs","IA Agents documentación API","documentación automática commits","herramientas docs para desarrolladores","write-documentation skill","documentar cambios de API","docs para nuevos módulos"],"fr":["automatiser documentation technique","synchroniser code et docs","outils IA documentation API","documentation automatique commits","outils docs développeurs","compétence write-documentation","documenter changements API","docs nouveaux modules"],"de":["technische Dokumentation automatisieren","Code und Docs synchronisieren","KI-Tools API-Dokumentation","automatische Dokumentation Commits","Dokumentationstools Entwickler","write-documentation Fähigkeit","API-Änderungen dokumentieren","Dokumentation neue Module"],"pt":["Write Documentation","ferramentas de IA","documentação de código","API pública","fluxo de trabalho interno","desenvolvimento de software","geração de documentação automática"],"ru":["Write Documentation","ИИ Агенты","документация кода","публичный API","внутренний рабочий процесс","разработка программного обеспечения","автоматическая генерация документации"],"ar":["Write Documentation","أدوات الذكاء الاصطناعي","توثيق التعليمات البرمجية","واجهة برمجة التطبيقات العامة","سير العمل الداخلي","تطوير البرمجيات","توليد التوثيق التلقائي"]}},"owner":"rayhanadev","repo":"fresh","repoPath":"rayhanadev/fresh","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.454Z","topics":[],"category":"community","skillMd":{"name":"write-documentation","description":"Updates JSDoc, README, AGENTS.md, and docs content to match behavior and API changes. Use whenever implementation changes affect users, contributors, or future agents.","bodyPreview":"# Write Documentation\n\nUse this skill to keep code and documentation synchronized as part of the same change.\n\n## When To Use\n\n- Public API additions or signature changes\n- User-facing behavior changes\n- Internal workflow or architecture changes\n- New modules or systems that need discoverable guidance\n\n## Prerequisite Checks\n\n- Identify whether the change is public API, internal workflow, or architecture.\n- Identify all touched entry points and exports.\n- Identify which docs are currently source","body":"# Write Documentation\n\nUse this skill to keep code and documentation synchronized as part of the same change.\n\n## When To Use\n\n- Public API additions or signature changes\n- User-facing behavior changes\n- Internal workflow or architecture changes\n- New modules or systems that need discoverable guidance\n\n## Prerequisite Checks\n\n- Identify whether the change is public API, internal workflow, or architecture.\n- Identify all touched entry points and exports.\n- Identify which docs are currently source-of-truth for the affected behavior.\n\n## Documentation Targets\n\n- Public exports: add complete JSDoc (`description`, `@param`, `@returns`, `@throws`, `@example`).\n- User-facing usage changes: update `README.md`.\n- Agent workflow or internal pattern changes: update `AGENTS.md`.\n- New architecture or subsystem docs: update `docs/`.\n\n## Workflow\n\n1. Classify the change type before finalizing implementation.\n2. Build a docs-impact checklist from changed files and exports.\n3. Update JSDoc while writing code, not as a post-pass.\n4. Update `README.md` usage snippets for any user-facing behavior change.\n5. Update `AGENTS.md` for contributor or internal policy updates.\n6. Update `docs/` for architecture-level changes.\n7. Verify examples match current signatures and behavior.\n8. Re-check docs during quality gate run to prevent stale guidance.\n\n## Commonly Missed Cases\n\n- Return-type changes with unchanged function names.\n- New error tags introduced without JSDoc `@throws` updates.\n- Configuration and environment variable changes not reflected in docs.\n- Internal behavior changes that invalidate AGENTS guidance.\n\n## Example: Public API Change\n\nIf `createSession(input)` now requires `tenantId`, update all of:\n\n- JSDoc in source:\n  - Add `@param tenantId` details and update example.\n- `README.md`:\n  - Update usage snippets and migration notes.\n- `AGENTS.md`:\n  - Add any new contributor rule or workflow impact.\n\n## Review Checklist\n\n- Public exports have complete and accurate JSDoc.\n- README usage examples compile logically against current API.\n- AGENTS guidance reflects current internal patterns.\n- Architecture docs cover any new subsystem or integration.\n- No contradictory statements remain across docs.\n\n## References\n\n- https://jsdoc.app/\n- https://effect.website/docs/\n- https://platform.claude.com/docs/en/agents-and-tools/agent-skills/best-practices\n"},"lastSynced":"2026-03-08T02:09:05.520Z","agentAnalysis":{"suitability":{"en":"Essential for Developer Productivity Agents maintaining code-documentation synchronization across API changes.","zh":"对于开发者生产力代理保持跨API更改的代码文档同步至关重要。","ja":"APIの変更を超えてコードとドキュメントの同期を維持する開発者生産性エージェントに不可欠です。","ko":"API 변경 사항 전반의 코드 문서화 동기화를 유지하는 개발자 생산성 에이전트에 필수적입니다.","es":"Esencial para los Agentes de Productividad de Desarrolladores que mantienen la sincronización de la documentación del código a través de los cambios de API.","fr":"Essentiel pour les Agents de Productivité des Développeurs qui maintiennent la synchronisation de la documentation du code à travers les changements d''API.","de":"Wesentlich für Developer-Produktivitätsagenten, die die Synchronisierung von Code-Dokumentation über API-Änderungen hinweg aufrechterhalten.","pt":"Essencial para Agentes de Produtividade de Desenvolvedores que mantêm a sincronização entre código e documentação ao longo de alterações de API.","ru":"Необходим для агентов производительности разработчиков, поддерживающих синхронизацию кода и документации при изменениях API.","ar":"ضروري لعميل إنتاجية المطورين الذين يحافظون على التزامن بين الكود والوثائق عبر التغييرات في واجهة برمجة التطبيقات."},"recommendation":{"en":"Automatically synchronizes code and documentation changes by identifying touched entry points, exports, and source documentation files. Enforces documentation integrity for public API signatures, user-facing behavior changes, and internal workflow modifications.","zh":"通过识别被修改的入口点、导出和源文档文件，自动同步代码和文档的更改。强制执行公共API签名、用户面向行为更改和内部工作流修改的文档完整性。","ja":"変更されたエントリポイント、エクスポート、ソースドキュメントファイルを識別して、コードとドキュメントの変更を自動的に同期します。パブリックAPIのシグネチャ、ユーザー向けの動作の変更、内部ワークフローの変更に対するドキュメントの完全性を強制します。","ko":"변경된 엔트리 포인트, 내보내기 및 소스 문서 파일을 식별하여 코드 및 문서의 변경 사항을 자동으로 동기화합니다. 공용 API 시그니처, 사용자 중심의 동작 변경 및 내부 워크플로 수정에 대한 문서 완전성을 적용합니다.","es":"Sincroniza automáticamente los cambios de código y documentación al identificar los puntos de entrada tocados, las exportaciones y los archivos de documentación de origen. Garantiza la integridad de la documentación para firmas de API públicas, cambios de comportamiento orientados al usuario y modificaciones de flujo de trabajo interno.","fr":"Synchronise automatiquement les changements de code et de documentation en identifiant les points d''entrée touchés, les exportations et les fichiers de documentation source. Assure l''intégrité de la documentation pour les signatures d''API publiques, les changements de comportement orientés vers l''utilisateur et les modifications de workflow interne.","de":"Synchronisiert automatisch Code- und Dokumentationsänderungen, indem es die berührten Einstiegspunkte, Exporte und Quelldokumentationsdateien identifiziert. Gewährleistet die Integrität der Dokumentation für öffentliche API-Signaturen, benutzerseitige Verhaltensänderungen und interne Workflow-Modifikationen.","pt":"Sincroniza automaticamente as alterações de código e documentação, identificando pontos de entrada tocados, exportações e arquivos de documentação de origem. Garante a integridade da documentação para assinaturas de API pública, alterações de comportamento voltadas para o usuário e modificações de fluxo de trabalho interno.","ru":"Автоматически синхронизирует изменения кода и документации, определяя затронутые точки входа, экспорты и исходные файлы документации. Обеспечивает целостность документации для публичных подписей API, изменений поведения, ориентированных на пользователя, и внутренних изменений рабочего процесса.","ar":"يتماشى تلقائيًا مع تغييرات الكود والوثائق من خلال تحديد نقاط الدخول المتأثرة والتصدير وملفات وثائق المصدر. يضمن سلامة الوثائق للتواقيع العامة لواجهة برمجة التطبيقات وتغييرات السلوك المتجهة للمستخدم وتغييرات سير العمل الداخلي."},"useCases":{"en":["Generating documentation for public API additions","Updating internal workflow documentation","Creating discoverable guidance for new modules","Maintaining documentation for architecture changes"],"zh":["为公共API添加项生成文档","更新内部工作流文档","为新模块创建可发现的指南","维护架构更改的文档"],"ja":["パブリックAPIの追加項目のドキュメントを生成する","内部ワークフローのドキュメントを更新する","新しいモジュールの発見可能なガイダンスを作成する","アーキテクチャの変更のドキュメントを維持する"],"ko":["공개 API 추가 항목에 대한 문서 생성","내부 워크플로 문서 업데이트","새 모듈에 대한 검색 가능한 가이드 생성","아키텍처 변경에 대한 문서 유지"],"es":["Generar documentación para adiciones de API públicas","Actualizar la documentación del flujo de trabajo interno","Crear orientación detectable para nuevos módulos","Mantener la documentación para cambios de arquitectura"],"fr":["Générer la documentation pour les ajouts d''API publiques","Mettre à jour la documentation du workflow interne","Créer des conseils détectables pour les nouveaux modules","Maintenir la documentation pour les changements d''architecture"],"de":["Erzeugen von Dokumentationen für öffentliche API-Hinzufügungen","Aktualisieren der internen Workflow-Dokumentation","Erstellen von auffindbaren Anleitungen für neue Module","Aufrechterhalten der Dokumentation für Architekturänderungen"],"pt":["Geração de documentação para adições de API pública","Atualização da documentação de fluxo de trabalho interno","Criação de orientação descobrível para módulos novos","Manutenção da documentação para alterações de arquitetura"],"ru":["Генерация документации для публичных дополнений API","Обновление документации внутреннего рабочего процесса","Создание обнаруживаемого руководства для новых модулей","Поддержание документации для изменений архитектуры"],"ar":["генерация وثائق لواجهة برمجة التطبيقات العامة الجديدة","تحديث وثائق سير العمل الداخلي","إنشاء توجيه يمكن اكتشافه لأدلة جديدة","صيانة الوثائق لتغييرات بنية التطبيق"]},"limitations":{"en":["Requires identification of documentation source files","Needs analysis of entry points and exports","Must distinguish between public API/internal changes"],"zh":["需要识别文档源文件","需要分析入口点和导出","必须区分公共API和内部更改"],"ja":["ドキュメントのソースファイルを識別する必要がある","エントリポイントとエクスポートを分析する必要がある","パブリックAPIと内部の変更を区別する必要がある"],"ko":["문서 소스 파일을 식별해야 함","엔트리 포인트 및 내보내기 분석이 필요함","공용 API 및 내부 변경을 구분해야 함"],"es":["Requiere la identificación de archivos de documentación de origen","Necesita análisis de puntos de entrada y exportaciones","Debe distinguir entre cambios de API públicos/internos"],"fr":["Nécessite l''identification des fichiers de documentation source","A besoin d''analyse des points d''entrée et des exportations","Doit distinguer entre les changements d''API publics/internes"],"de":["Erfordert die Identifizierung von Quelldokumentationsdateien","Benötigt Analyse von Einstiegspunkten und Exporten","Muss zwischen öffentlichen/internen API-Änderungen unterscheiden"],"pt":["Exige identificação de arquivos de origem da documentação","Necessita análise de pontos de entrada e exportações","Deve distinguir entre alterações de API pública e interna"],"ru":["Требует идентификации исходных файлов документации","Требует анализа точек входа и экспортов","Должен различать изменения публичного и внутреннего API"],"ar":["يتطلب تحديد ملفات مصدر الوثائق","يتطلب تحليل نقاط الدخول والتصدير","يجب التمييز بين التغييرات العامة وال内部 لواجهة برمجة التطبيقات"]},"version":4},"contentHash":"5055dd314a9377672e4e781af6658c157ac876473f7ac7d562589cfa7db9c6e3","qualityScore":44}');
