INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('christopher-buss/rbxts-jest-extended/isentinel', 'isentinel', 'christopher-buss', 'rbxts-jest-extended', 'community', 'isentinel christopher-buss rbxts-jest-extended community isentinel provides additional Jest matchers for rbxts, sourced from jest-extended. It benefits developers working with roblox-ts by offering a set of opinionated tooling and patterns. isentinel 是一个用于 Roblox-ts 开发的工具，提供 Jest 匹配器、pnpm 包管理和 TypeScript 配置等功能 isentinel は、Jest マッチャー、pnpm パッケージマネージャー、TypeScript 構成などを提供する Roblox-ts 開発ツールです isentinel은 Jest 매처, pnpm 패키지 관리 및 TypeScript 구성과 같은 기능을 제공하는 로블록스-ts 개발 도구입니다 isentinel es una herramienta de desarrollo para rbxts que proporciona matchers adicionales para Jest, mejorando la eficiencia en las pruebas y el desarrollo isentinel est un outil de développement pour rbxts qui fournit des matchers supplémentaires pour Jest, améliorant l''efficacité des tests et du développement isentinel ist ein Entwicklungstool für rbxts, das zusätzliche Matcher für Jest bereitstellt, um die Effizienz von Tests und Entwicklung zu verbessern O isentinel é uma ferramenta de desenvolvimento roblox-ts que fornece Jest matchers adicionais e configurações de TypeScript. Исентинел - это инструмент для разработки роблокс-ts, который предоставляет дополнительные Jest matchers и настройки TypeScript. أداة isentinel هي أداة لتنمية roblox-ts توفر Jest matchers إضافية وضبطات TypeScript. how to use isentinel with Jest isentinel setup guide for roblox-ts isentinel vs jest-extended isentinel install for AI agents what is isentinel in roblox-ts development isentinel alternative for testing isentinel and pnpm integration isentinel TypeScript configuration isentinel Jest matchers tutorial isentinel Roblox-ts Jest 匹配器 pnpm 包管理 TypeScript 配置 AI エージェント Roblox-ts 开发 前端开发工具 Utilizes pnpm as the package manager with bun as an optional runtime Supports TypeScript with strict and extra checks for robust code quality Includes @isentinel/tsconfig for standardized TypeScript configuration Employs @isentinel/eslint-config for linting without Prettier Enhances testing capabilities with additional Jest matchers from jest-extended isentinel is a set of additional Jest matchers for rbxts development, offering opinionated tooling and patterns for efficient testing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('randlee/synaptic-canvas/sc-managing-worktrees', 'community', 'randlee', 'synaptic-canvas', 'randlee/synaptic-canvas', 'sc-managing-worktrees', 0, 0, 44, '2026-03-08T01:57:15.551Z', '2026-03-08T02:11:30.095Z', '1082cef00ec5f414c0ca666202d4023392dae287550e0711a3a7b9001962e97c', '{"id":"randlee/synaptic-canvas/sc-managing-worktrees","name":"sc-managing-worktrees","description":{"en":"The sc-managing-worktrees skill enables developers to manage worktrees with a standard structure and tracking. It delegates to specialized agents via the Task tool for create, scan, and cleanup operations.","zh":"sc-managing-worktrees 是一个用于管理 Git 工作树的 AI 工具，提供标准结构和跟踪","ja":"sc-managing-worktrees は Git ワークツリーを管理する AI エージェントで、標準構造と追跡を提供します","ko":"sc-managing-worktrees는 Git 워크트리를 관리하는 AI 툴로 표준 구조와 추적을 제공합니다","es":"sc-managing-worktrees es una habilidad que permite gestionar worktrees con una estructura y seguimiento estándar","fr":"sc-managing-worktrees est une compétence qui permet de gérer les worktrees avec une structure et un suivi standard","de":"sc-managing-worktrees ist eine Fähigkeit, die die Verwaltung von Worktrees mit einer Standardstruktur und -verfolgung ermöglicht","pt":"O sc-managing-worktrees é uma habilidade que permite gerenciar worktrees com estrutura padrão e rastreamento. Use o comando /sc-git-worktree para invocar essa habilidade.","ru":"Sc-managing-worktrees - это навык, который позволяет управлять worktrees со стандартной структурой и отслеживанием. Используйте команду /sc-git-worktree, чтобы вызвать этот навык ИИ Агентов.","ar":"sc-managing-worktrees هو مهارة يسمح بإدارة worktrees بتركيب معياري وتحديد الموقع. استخدم الأمر /sc-git-worktree لاستدعاء هذه المهارة لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"sc-managing-worktrees: Git Worktree Management Setup Guid...","zh":"sc-managing-worktrees 工作树管理设置指南","ja":"sc-managing-worktrees ワークツリー管理ベストプラクティス","ko":"sc-managing-worktrees 워크트리 관리 설정 가이드","es":"Guía de configuración de sc-managing-worktrees para Git","fr":"Configurer sc-managing-worktrees pour une gestion de work...","de":"Einrichten von sc-managing-worktrees für Git-Worktrees","pt":"Guia de Configuração do sc-managing-worktrees para Desenv...","ru":"Настройка sc-managing-worktrees: Руководство для Разработ...","ar":"دليل إعداد sc-managing-worktrees لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to manage Git worktrees efficiently with sc-managing-worktrees. Learn to invoke the /sc-git-worktree command and optimize your workflow today!","zh":"了解如何使用 sc-managing-worktrees AIエージェント管理 Git 工作树，包括创建、扫描和清理","ja":"sc-managing-worktrees AIエージェントを使用して Git ワークツリーを管理する方法について学びます","ko":"sc-managing-worktrees 워크트리 관리를 위한 AI 툴을 사용하여 Git 워크트리를 생성, 스캔, 청소하는 방법","es":"Aprende a administrar worktrees con sc-managing-worktrees y mejora tu flujo de trabajo con Git","fr":"Découvrez comment configurer sc-managing-worktrees pour gérer vos worktrees Git de manière efficace","de":"Erfahren Sie, wie Sie sc-managing-worktrees einrichten, um Ihre Git-Worktrees zu verwalten","pt":"Aprenda a gerenciar worktrees com o sc-managing-worktrees. Descubra como usar o comando /sc-git-worktree para melhorar a produtividade.","ru":"Узнайте, как управлять worktrees с помощью sc-managing-worktrees. Откройте для себя, как использовать команду /sc-git-worktree для повышения производительнос...","ar":"تعرف على كيفية إدارة worktrees باستخدام sc-managing-worktrees. اكتشف كيفية استخدام الأمر /sc-git-worktree لتحسين الإنتاجية لأدوات الذكاء الاصطناعي"},"definition":{"en":"sc-managing-worktrees is a skill that manages Git worktrees using a standard structure and tracking, utilizing the /sc-git-worktree command and Task tool delegation.","zh":"sc-managing-worktrees 是一个用于管理 Git 工作树的 AI 工具","ja":"sc-managing-worktrees は Git ワークツリーを管理する AI エージェント","ko":"sc-managing-worktrees는 Git 워크트리를 관리하는 AI 툴","es":"sc-managing-worktrees es una habilidad que gestiona worktrees con Git","fr":"sc-managing-worktrees est une compétence qui gère les worktrees avec Git","de":"sc-managing-worktrees ist eine Fähigkeit, die Worktrees mit Git verwaltet","pt":"O sc-managing-worktrees é uma habilidade que gerencia worktrees com estrutura padrão e rastreamento.","ru":"Sc-managing-worktrees - это навык, который управляет worktrees со стандартной структурой и отслеживанием ИИ Агентов.","ar":"sc-managing-worktrees هو مهارة لإدارة worktrees بتركيب معياري وتحديد الموقع لأدوات الذكاء الاصطناعي"},"features":{"en":["Invokes the /sc-git-worktree command for worktree management","Delegates to sc-worktree-create agent for worktree creation","Utilizes sc-worktree-scan agent for worktree scanning and recommendations","Employs sc-worktree-cleanup agent for worktree cleanup operations","Returns JSON data for success, path, branch, and tracking information","Supports worktree list and recommendations via JSON output"],"zh":["使用 `/sc-git-worktree` 命令管理工作树","支持创建、扫描和清理工作树","与 `sc-worktree-create` 和 `sc-worktree-scan` 等特化代理集成","提供 JSON 格式的成功、路径、分支和跟踪行等信息","支持工作树列表和推荐的生成"],"ja":["ワークツリーの管理に `/sc-git-worktree` コマンドを使用","ワークツリーの作成、スキャン、クリーンアップをサポート","特化エージェント `sc-worktree-create` および `sc-worktree-scan` と統合","JSON 形式の成功、パス、ブランチ、追跡行などの情報を提供","ワークツリーの一覧と推奨事項の生成をサポート"],"ko":["워크트리의 관리를 위해 `/sc-git-worktree` 명령을 사용","워크트리의 생성, 스캔, 청소를 지원","전용 에이전트 `sc-worktree-create` 및 `sc-worktree-scan`와 통합","JSON 형식의 성공, 경로, 브랜치, 추적 행 등의 정보를 제공","워크트리 목록과 추천 사항의 생성을 지원"],"es":["Crea worktrees con la herramienta Task","Escanea worktrees para detectar problemas","Limpia worktrees para mantener la organización","Utiliza el comando /sc-git-worktree para invocar la habilidad","Delega tareas a agentes especializados como sc-worktree-create y sc-worktree-scan"],"fr":["Crée des worktrees avec l''outil Task","Analyse des worktrees pour détecter les problèmes","Nettoie les worktrees pour maintenir l''organisation","Utilise la commande /sc-git-worktree pour invoquer la compétence","Délegue des tâches à des agents spécialisés tels que sc-worktree-create et sc-worktree-scan"],"de":["Erstellt Worktrees mit dem Task-Tool","Scannen von Worktrees, um Probleme zu erkennen","Reinigt Worktrees, um die Organisation aufrechtzuerhalten","Verwenden Sie den Befehl /sc-git-worktree, um die Fähigkeit aufzurufen","Delegiert Aufgaben an spezialisierte Agenten wie sc-worktree-create und sc-worktree-scan"],"pt":["Criação de worktrees com estrutura padrão","Rastreamento de worktrees","Uso do comando /sc-git-worktree","Delegação de tarefas para agentes especializados","Suporte a operações de criação, varredura e limpeza","Retorno de JSON com informações de sucesso e caminho"],"ru":["Создание worktrees со стандартной структурой","Отслеживание worktrees","Использование команды /sc-git-worktree","Делегирование задач специализированным агентам ИИ Агентов","Поддержка операций создания, сканирования и очистки","Возвращение JSON с информацией о успехе и пути"],"ar":["إنشاء worktrees بتركيب معياري","تحديد الموقع ل worktrees","استخدام الأمر /sc-git-worktree","تفويض المهام إلى وكلاء متخصصين لأدوات الذكاء الاصطناعي","دعم عمليات إنشاء وتصفية وتنظيف","إرجاع JSON مع معلومات النجاح والمسار"]},"keywords":{"en":["how to use sc-managing-worktrees","sc-managing-worktrees setup guide","git worktree management","sc-managing-worktrees alternative","sc-managing-worktrees vs git worktree","sc-managing-worktrees install","sc-managing-worktrees tutorial","git worktree tracking","sc-managing-worktrees documentation"],"zh":["sc-managing-worktrees","Git 工作树管理","AI 工具","工作树创建","工作树扫描","工作树清理","Git 工作树跟踪"],"ja":["sc-managing-worktrees","Git ワークツリー管理","AI エージェント","ワークツリー作成","ワークツリーズキャン","ワークツリークリーンアップ","Git ワークツートラッキング"],"ko":["sc-managing-worktrees","Git 워크트리 관리","AI 툴","워크트리 생성","워크트리 스캔","워크트리 청소","Git 워크트리 추적"],"es":["sc-managing-worktrees","Git worktrees","gestión de worktrees","herramientas de Git","agentes de Git","configuración de Git","flujo de trabajo de Git"],"fr":["sc-managing-worktrees","Worktrees Git","gestion de worktrees","outils Git","agents Git","configuration Git","flux de travail Git"],"de":["sc-managing-worktrees","Git-Worktrees","Verwaltung von Worktrees","Git-Tools","Git-Agents","Git-Konfiguration","Git-Arbeitsablauf"],"pt":["sc-managing-worktrees","gerenciamento de worktrees","rastreamento de worktrees","comando /sc-git-worktree","desenvolvimento de software","ferramentas de desenvolvimento","git worktree","desenvolvedores de software"],"ru":["sc-managing-worktrees","управление worktrees","отслеживание worktrees","команда /sc-git-worktree","разработка программного обеспечения","инструменты разработки","git worktree","разработчики программного обеспечения ИИ Агентов"],"ar":["sc-managing-worktrees","إدارة worktrees","تحديد الموقع ل worktrees","الأمر /sc-git-worktree","تطوير البرمجيات","أدوات التطوير","git worktree","مطورو البرمجيات لأدوات الذكاء الاصطناعي"]}},"owner":"randlee","repo":"synaptic-canvas","repoPath":"randlee/synaptic-canvas","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.551Z","topics":[],"category":"community","skillMd":{"name":"sc-managing-worktrees","description":">","version":"0.8.0","bodyPreview":"# Managing Git Worktrees\n\nUse this skill to manage worktrees with a standard structure and tracking. Use the `/sc-git-worktree` command to invoke this skill.\n\n## Agent Delegation\n\nThis skill delegates to specialized agents via the **Task tool**:\n\n| Operation | Agent | Returns |\n|-----------|-------|---------|\n| Create | `sc-worktree-create` | JSON: success, path, branch, tracking_row |\n| Scan | `sc-worktree-scan` | JSON: success, worktrees list, recommendations |\n| Cleanup | `sc-worktree-cleanup","body":"# Managing Git Worktrees\n\nUse this skill to manage worktrees with a standard structure and tracking. Use the `/sc-git-worktree` command to invoke this skill.\n\n## Agent Delegation\n\nThis skill delegates to specialized agents via the **Task tool**:\n\n| Operation | Agent | Returns |\n|-----------|-------|---------|\n| Create | `sc-worktree-create` | JSON: success, path, branch, tracking_row |\n| Scan | `sc-worktree-scan` | JSON: success, worktrees list, recommendations |\n| Cleanup | `sc-worktree-cleanup` | JSON: success, branch_deleted, tracking_update |\n| Abort | `sc-worktree-abort` | JSON: success, worktree_removed, tracking_update |\n| Update | `sc-worktree-update` | JSON: success, commits_pulled, conflicts (if any) |\n\nTo invoke an agent, use the Task tool with:\n- Prompt file: `.claude/agents/<agent-name>.md`\n- Parameters as documented in each agent''s Inputs section\n\n## Standards and paths\n- Repo root: current directory.\n- Default worktree base: `../synaptic-canvas-worktrees`.\n- Worktrees live in `<worktree_base>/<branch>`.\n- Tracking document (if used): `<worktree_base>/worktree-tracking.md` must be updated on create/scan/cleanup/abandon. Allow a toggle to disable tracking for repos that don''t use it.\n- Naming: worktree directory = branch name; branch naming follows repo policy (e.g., master release; develop/DevBranch integration; feature from integration; hotfix from master; release branches as needed).\n- Branch protections/hooks: no direct commits to protected branches; ensure hooks/branch protections are respected across worktrees.\n- Cleanliness: worktrees must be removed and tracking updated when work is complete or branch is merged.\n\n## Protected Branch Configuration\n\nProtected branches (main, develop, master, etc.) require special handling to prevent accidental deletion:\n\n```yaml\n# Configuration (typically in repo .claude/config or passed to agents)\ngit_flow:\n  enabled: true  # boolean: whether git-flow workflow is used\n  main_branch: \"main\"  # or \"master\" - the primary production branch\n  develop_branch: \"develop\"  # only if git_flow.enabled = true\n\nprotected_branches:\n  - \"main\"\n  - \"develop\"\n  - \"master\"\n  # Can include additional patterns: \"release/*\", \"hotfix/*\"\n```\n\n**Protected Branch Rules:**\n- If `git_flow.enabled: false` → protect only `main_branch`\n- If `git_flow.enabled: true` → protect `main_branch` + `develop_branch`\n- Additional branches can be added to `protected_branches` array\n- **Cleanup/abort agents NEVER delete protected branches** (local or remote)\n- Protected branches can only be removed from worktrees, never deleted\n- Use `--update` to safely pull changes for protected branches in worktrees\n\n## Workflows\n\n### Scaffolding (if missing)\n- Ensure base path exists: `<worktree_base>`. If missing, create it.\n- If tracking is enabled, ensure tracking doc exists with headers.\n\n### Create worktree (and branch)\n1) Inputs: `--branch <name>`, `--base <master|develop|...>`, optional `--path`.\n2) Ensure scaffolding/tracking doc exists (if enabled); fetch all: `git fetch --all --prune`.\n3) Confirm base branch exists and is up to date.\n4) Determine path: default `<worktree_base>/<branch>` (or override).\n5) Create branch/worktree:\n   - If branch does not yet exist: `git worktree add -b <branch> <path> <base>`.\n   - If branch exists: `git worktree add <path> <branch>`.\n6) In the new worktree, ensure hooks apply and verify status is clean.\n7) If tracking enabled, add/refresh entry in tracking doc (branch, path, base, purpose, owner, created date, status).\n8) Agent option: delegate to `sc-worktree-create` agent; it returns structured JSON (tracking row, status).\n\n### Scan/verify worktrees\n1) List worktrees: `git worktree list --porcelain`.\n2) Cross-check tracking doc (if enabled); flag missing/stale entries or extra rows.\n3) For each worktree, check status and merge state:\n   - `git -C <path> status --short`\n   - `git -C <path> fetch`\n   - `git branch --remotes --contains <branch>` to see if merged.\n4) Identify issues: untracked changes, diverged branches, merged-but-not-cleaned worktrees, missing tracking entries.\n5) Update tracking doc with current state and issues (if enabled); propose cleanup where appropriate.\n6) Agent option: delegate to `sc-worktree-scan` agent; it returns structured JSON.\n\n### Clean-up worktree (post-merge or finished work)\n1) **Check if branch is protected**: If branch is in protected_branches list, ONLY remove worktree, NEVER delete the branch.\n2) If `git status` is not clean, stop and request explicit approval/coordination.\n3) Ensure all work is committed/pushed or explicitly confirmed to discard.\n4) Confirm target branch merged or otherwise approved for removal.\n5) Remove worktree: `git worktree remove <path>` (use `--force` only with approval).\n6) For **non-protected branches**: If merged and no unique commits, delete the branch locally (`git branch -d <branch>`) and remotely (`git push origin --delete <branch>`) by default; only skip if the user explicitly opts out. If the remote branch is already absent, continue without error. If not merged, only delete with explicit approval.\n7) For **protected branches**: Only remove worktree, preserve branch locally and remotely. Update tracking to note \"worktree removed, branch preserved (protected)\".\n8) If tracking enabled, update tracking doc to remove/mark cleaned with merge SHA/date.\n9) Agent option: delegate to `sc-worktree-cleanup` agent; it returns structured JSON.\n\n### Abandon worktree (discard work)\n1) **Check if branch is protected**: If branch is in protected_branches list, ONLY remove worktree, NEVER delete the branch.\n2) If `git status` is not clean, stop and request explicit approval/coordination.\n3) Confirm user approval to discard local changes and optionally delete the branch.\n4) Remove worktree: `git worktree remove <path>` (force only with approval).\n5) For **non-protected branches**: If instructed, delete the branch locally (`git branch -D <branch>`) and remotely (`git push origin --delete <branch>`).\n6) For **protected branches**: Only remove worktree, preserve branch locally and remotely. Require confirmation: \"Branch is protected. Remove worktree but preserve branch?\"\n7) If tracking enabled, update tracking doc to remove the entry and note abandonment.\n8) Agent option: delegate to `sc-worktree-abort` agent; it returns structured JSON.\n\n### Update protected branch (pull latest changes)\n1) **Verify branch is protected**: Only operates on branches in protected_branches list. If no branch is specified, update all protected branches that have worktrees.\n2) Check if worktree exists at expected path; error if missing.\n3) If `git status` is not clean, stop and report dirty state.\n4) Fetch and pull: `git fetch origin <branch>` then `git pull origin <branch>`.\n5) **If merge conflicts occur**:\n   - Collect conflicted files: `git diff --name-only --diff-filter=U`\n   - Return control to main agent with conflict details\n   - Main agent coordinates with user to resolve conflicts\n   - After resolution, user commits and continues\n6) **If clean pull**: Update tracking with last_checked timestamp and commits pulled count.\n7) Agent option: delegate to `sc-worktree-update` agent; it returns structured JSON with success or conflict details.\n\n## Safety and reminders\n- **NEVER delete protected branches** (main, develop, master) under any circumstances.\n- Protected branches can only be removed from worktrees; the branch itself must always be preserved.\n- Never delete branches or force-remove worktrees without explicit approval.\n- Never clean/abandon a worktree with uncommitted changes unless explicitly approved.\n- Keep tracking doc in sync on every operation when enabled.\n- Respect branch protections and hooks; no direct commits to protected branches.\n- Use background agents for long scans/cleanups; keep the main context focused on decisions and summaries.\n- When updating protected branches in worktrees, handle merge conflicts by returning control to main agent for user coordination.\n"},"lastSynced":"2026-03-08T02:11:30.095Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing standardized Git worktree management and tracking.","zh":"非常适合需要标准化 Git 工作目录管理和跟踪的开发代理。","ja":"標準的なGitのワークツリーマネージメントと追跡が必要な開発エージェントに最適です。","ko":"표준화된 Git 작업 트리 관리 및 추적이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión y seguimiento de Git worktree estandarizados.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''un suivi standardisés de l''arborescence de travail Git.","de":"Perfekt für Entwicklungssagenten, die eine standardisierte Git-Arbeitsbereichsverwaltung und -nachverfolgung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de worktree do Git padronizado e rastreamento.","ru":"Идеально для агентов разработки, которым необходим стандартизированный менеджмент Git worktree и отслеживание.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى إدارة شجرة العمل الخاصة ب Git ومتابعتها بشكل معياري."},"recommendation":{"en":"Empowers agents to manage worktrees with a standard structure and tracking via the Task tool, utilizing specialized agents for create, scan, and cleanup operations, and returning JSON data for success, path, branch, and tracking row.","zh":"赋予代理管理具有标准结构的工作目录的能力，并通过任务工具进行跟踪，利用专门的代理执行创建、扫描和清理操作，并返回JSON数据以实现成功、路径、分支和跟踪行。","ja":"エージェントが標準構造のワークツリーを管理し、タスクツールを使用して追跡できるようにし、専用のエージェントを使用して作成、スキャン、クリーンアップ操作を実行し、成功、パス、ブランチ、追跡行のJSONデータを返します。","ko":"에이전트가 표준 구조의 작업 트리를 관리하고 작업 도구를 사용하여 추적할 수 있도록 하며, 생성, 스캔, 정리 작업을 위한 전문 에이전트를 사용하여 JSON 데이터를 성공, 경로, 브랜치 및 추적 행으로 반환합니다.","es":"Habilita a los agentes a gestionar las arborescencias de trabajo con una estructura estándar y seguimiento a través de la herramienta Task, utilizando agentes especializados para operaciones de creación, análisis y limpieza, y devolviendo datos JSON para éxito, ruta, rama y fila de seguimiento.","fr":"Permet aux agents de gérer les arbres de travail avec une structure standard et un suivi via l''outil Task, en utilisant des agents spécialisés pour les opérations de création, d''analyse et de nettoyage, et en renvoyant des données JSON pour le succès, le chemin, la branche et la ligne de suivi.","de":"Ermöglicht es Agenten, Arbeitsbereiche mit einer standardmäßigen Struktur und Nachverfolgung über das Task-Tool zu verwalten, indem spezialisierte Agenten für Erstellungs-, Scan- und Bereinigungsoperationen eingesetzt werden und JSON-Daten für Erfolg, Pfad, Zweig und Nachverfolgungszeile zurückgegeben werden.","pt":"Permite que os agentes gerenciem worktrees com uma estrutura padrão e rastreamento por meio da ferramenta Task, utilizando agentes especializados para operações de criação, varredura e limpeza, e retornando dados JSON para sucesso, caminho, branch e linha de rastreamento.","ru":"Позволяет агентам управлять worktree с стандартной структурой и отслеживанием через инструмент Task, используя специализированные агенты для операций создания, сканирования и очистки, и возвращая данные JSON для успеха, пути, ветки и строки отслеживания.","ar":"تمكن الوكلاء من إدارة شجرة العمل بمعايير معيارية والتعقب من خلال أداة Task، مستخدمين وكلاء متخصصين لعمليات الإنشاء والفحص والتنظيف، وعلى إرجاع بيانات JSON للنجاح والمسار والفرع وسطر التعقب."},"useCases":{"en":["Automating worktree creation with sc-worktree-create","Scanning worktrees for recommendations with sc-worktree-scan","Cleaning up worktrees with sc-worktree-cleanup"],"zh":["使用 sc-worktree-create 自动创建工作目录","使用 sc-worktree-scan 扫描工作目录以获取建议","使用 sc-worktree-cleanup 清理工作目录"],"ja":["sc-worktree-create を使用してワークツリーの自動作成","sc-worktree-scan を使用してワークツリーのスキャンと推奨事項の取得","sc-worktree-cleanup を使用してワークツリーのクリーンアップ"],"ko":["sc-worktree-create를 사용하여 작업 트리 자동 생성","sc-worktree-scan를 사용하여 작업 트리 스캔 및 권장 사항 가져오기","sc-worktree-cleanup를 사용하여 작업 트리 정리"],"es":["Automatización de la creación de arborescencia de trabajo con sc-worktree-create","Análisis de las arborescencias de trabajo para recomendaciones con sc-worktree-scan","Limpieza de las arborescencias de trabajo con sc-worktree-cleanup"],"fr":["Automatisation de la création d''arborescence de travail avec sc-worktree-create","Analyse des arbres de travail pour des recommandations avec sc-worktree-scan","Nettoyage des arbres de travail avec sc-worktree-cleanup"],"de":["Automatisierung der Erstellung von Arbeitsbereichen mit sc-worktree-create","Scannen von Arbeitsbereichen für Empfehlungen mit sc-worktree-scan","Bereinigung von Arbeitsbereichen mit sc-worktree-cleanup"],"pt":["Automatizar a criação de worktree com sc-worktree-create","Varredurar worktrees para recomendações com sc-worktree-scan","Limpar worktrees com sc-worktree-cleanup"],"ru":["Автоматизировать создание worktree с помощью sc-worktree-create","Сканировать worktree для рекомендаций с помощью sc-worktree-scan","Очистить worktree с помощью sc-worktree-cleanup"],"ar":["تأتميم إنشاء شجرة العمل مع sc-worktree-create","فحص شجرة العمل لتقديم توصيات مع sc-worktree-scan","تنظيف شجرة العمل مع sc-worktree-cleanup"]},"limitations":{"en":["Requires Task tool integration","Limited to Git worktree management"],"zh":["需要任务工具集成","仅限 Git 工作目录管理"],"ja":["タスクツールの統合が必要","Git のワークツリーマネージメントのみ"],"ko":["작업 도구 통합이 필요","Git 작업 트리 관리만 해당"],"es":["Requiere integración con la herramienta Task","Limitado a la gestión de la arborescencia de trabajo de Git"],"fr":["Nécessite une intégration avec l''outil Task","Limité à la gestion de l''arborescence de travail Git"],"de":["Benötigt Task-Tool-Integration","Begrenzt auf die Verwaltung von Git-Arbeitsbereichen"],"pt":["Requer integração com a ferramenta Task","Limitado ao gerenciamento de worktree do Git"],"ru":["Требует интеграции с инструментом Task","Ограничен менеджментом Git worktree"],"ar":["يتطلب تكاملًا مع أداة Task","محدود بإدارة شجرة العمل الخاصة ب Git"]},"version":4},"contentHash":"1082cef00ec5f414c0ca666202d4023392dae287550e0711a3a7b9001962e97c","qualityScore":44}');
