INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('randlee/synaptic-canvas/sc-managing-worktrees', 'sc-managing-worktrees', 'randlee', 'synaptic-canvas', 'community', 'sc-managing-worktrees randlee synaptic-canvas community The sc-managing-worktrees skill enables developers to manage worktrees with a standard structure and tracking. It delegates to specialized agents via the Task tool for create, scan, and cleanup operations. sc-managing-worktrees 是一个用于管理 Git 工作树的 AI 工具，提供标准结构和跟踪 sc-managing-worktrees は Git ワークツリーを管理する AI エージェントで、標準構造と追跡を提供します sc-managing-worktrees는 Git 워크트리를 관리하는 AI 툴로 표준 구조와 추적을 제공합니다 sc-managing-worktrees es una habilidad que permite gestionar worktrees con una estructura y seguimiento estándar sc-managing-worktrees est une compétence qui permet de gérer les worktrees avec une structure et un suivi standard sc-managing-worktrees ist eine Fähigkeit, die die Verwaltung von Worktrees mit einer Standardstruktur und -verfolgung ermöglicht O sc-managing-worktrees é uma habilidade que permite gerenciar worktrees com estrutura padrão e rastreamento. Use o comando /sc-git-worktree para invocar essa habilidade. Sc-managing-worktrees - это навык, который позволяет управлять worktrees со стандартной структурой и отслеживанием. Используйте команду /sc-git-worktree, чтобы вызвать этот навык ИИ Агентов. sc-managing-worktrees هو مهارة يسمح بإدارة worktrees بتركيب معياري وتحديد الموقع. استخدم الأمر /sc-git-worktree لاستدعاء هذه المهارة لأدوات الذكاء الاصطناعي how to use sc-managing-worktrees sc-managing-worktrees setup guide git worktree management sc-managing-worktrees alternative sc-managing-worktrees vs git worktree sc-managing-worktrees install sc-managing-worktrees tutorial git worktree tracking sc-managing-worktrees documentation sc-managing-worktrees Git 工作树管理 AI 工具 工作树创建 工作树扫描 工作树清理 Git 工作树跟踪 Invokes the /sc-git-worktree command for worktree management Delegates to sc-worktree-create agent for worktree creation Utilizes sc-worktree-scan agent for worktree scanning and recommendations Employs sc-worktree-cleanup agent for worktree cleanup operations Returns JSON data for success, path, branch, and tracking information Supports worktree list and recommendations via JSON output sc-managing-worktrees is a skill that manages Git worktrees using a standard structure and tracking, utilizing the /sc-git-worktree command and Task tool delegation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kimthiphuongthao/failover_openig/auto-debug-command', 'community', 'kimthiphuongthao', 'failover_openig', 'kimthiphuongthao/failover_openig', 'auto-debug-command', 0, 0, 44, '2026-03-08T01:57:15.602Z', '2026-03-08T02:13:06.753Z', '1c32949beee0a15fef561e258b03b01f9433f0734ad4e393e37101d1afc5a194', '{"id":"kimthiphuongthao/failover_openig/auto-debug-command","name":"auto-debug-command","description":{"en":"The auto-debug-command skill automates shell command execution, monitoring, and debugging for developers. It runs commands in detached mode and attempts to fix errors until successful.","zh":"Auto-Debug Command 是一个自动执行 shell 命令、监控输出并修复错误的技能。它可以自动重试命令直到成功","ja":"Auto-Debug コマンドは、シェルコマンドの自動実行、出力の監視、エラーの修復を実行する技能です。コマンドを自動で再実行して成功するまで継続します","ko":"자동 디버그 명령어는 셸 명령어의 자동 실행, 출력 모니터링, 오류 수정을 수행하는 스킬입니다. 명령어를 자동으로 재실행하여 성공할 때까지 지속합니다","es":"El auto-debug-command es una habilidad que automatiza la ejecución de comandos de shell y su depuración. Mejora la eficiencia de tus proyectos de desarrollo","fr":"L''auto-debug-command est une fonctionnalité qui automatise l''exécution de commandes shell et leur débogage. Améliorez l''efficacité de vos projets de développement","de":"Das auto-debug-command ist eine Fähigkeit, die die Ausführung von Shell-Befehlen und deren Fehlersuche automatisiert. Verbessern Sie die Effizienz Ihrer Entwicklungsprojekte","pt":"O auto-debug-command é uma habilidade que automatiza a execução de comandos shell e monitora a saída para erros, tentando depurar e corrigir problemas identificados","ru":"ИИ Агент auto-debug-command автоматизирует выполнение команд shell и отслеживает вывод для ошибок, пытаясь отладить и исправить выявленные проблемы","ar":"وظيفة أوامر Debug التلقائي تحول دون الحاجة إلى متابعة الأوامر يدويًا، حيث تقوم بتشغيل أوامر Shell وتحدد الأخطاء وتحاول إصلاحها"},"seo":{"title":{"e