INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lucapalomba/carGPT/update_check_skill', 'update_check_skill', 'lucapalomba', 'carGPT', 'community', 'update_check_skill lucapalomba carGPT community The update_check_skill ensures project documentation and API specs are up-to-date after each task. It benefits developers by automating documentation updates. Update Check Skill 是一个确保项目文档和 API 规范保持最新的技能。它通过更新 Markdown 文件和 Swagger.json 文件来实现 Update Check Skill は、プロジェクトのドキュメントと API 規約を最新に保つためのスキルです。Markdown ファイルと Swagger.json ファイルを更新することで機能します Update Check Skill은 프로젝트 문서와 API 명세가 최신 상태로 유지되도록 하는_skill입니다. Markdown 파일과 Swagger.json 파일을 업데이트하여 작동합니다 update_check_skill es una habilidad que garantiza la actualización de la documentación y especificaciones de API después de cada tarea en proyectos de desarrollo de software con agentes de IA update_check_skill est une compétence qui assure la mise à jour de la documentation et des spécifications d''API après chaque tâche dans les projets de développement logiciel utilisant des outils d''IA update_check_skill ist eine Fähigkeit, die die Aktualisierung der Dokumentation und API-Spezifikationen nach jedem Task in Softwareentwicklungsprojekten mit KI-Agenten gewährleistet O update_check_skill é uma habilidade que atualiza a documentação do projeto após cada tarefa, garantindo que os arquivos Markdown e swagger.json estejam atualizados. update_check_skill — это умение, которое обновляет документацию проекта после каждой задачи, гарантируя, что файлы Markdown и swagger.json актуальны. update_check_skill هو مهارة تحديث المستندات بعد كل مهمة، مما يضمن أن يتم تحديث ملفات Markdown و swagger.json how to use update_check_skill update_check_skill setup guide what is update_check_skill update_check_skill alternative update_check_skill vs API documentation tools update_check_skill install API documentation automation swagger.json file updates Markdown file management Update Check Skill AI 工具 文档更新 Swagger.json API 规范 Markdown 文件 项目文档 AIエージェント 技术文档 自动更新 Reviews changes made during tasks to update relevant Markdown files Updates the swagger.json file for changed API endpoints or schemas Ensures documentation in the docs/ directory is current Automates updates after every task completion Supports API specification updates via JSON file modifications Streamlines documentation maintenance using Markdown files update_check_skill is a technical skill that updates project documentation and API specifications after every task completion.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('peterfriese/yt-genius-skill/yt-genius', 'community', 'peterfriese', 'yt-genius-skill', 'peterfriese/yt-genius-skill', 'yt-genius', 0, 0, 44, '2026-03-08T01:57:15.634Z', '2026-03-08T02:13:35.286Z', '4a0e223da237e2d3a7521691233667f6002e5f80641e4a603157fa07567b2abc', '{"id":"peterfriese/yt-genius-skill/yt-genius","name":"yt-genius","description":{"en":"yt-genius is a YouTube growth expert skill that helps maximize video content reach and engagement by generating metadata and chapters. It benefits YouTube content creators and strategists.","zh":"yt-genius 是一个 YouTube 增长专家和内容策略师，帮助用户最大化视频内容的reach 和参与度，提供元数据生成、社交媒体重用和内容分析功能","ja":"yt-genius は YouTube 成長エキスパートとコンテンツストラテジストであり、ユーザーがビデオコンテンツのリーチとエンゲージメントを最大化するのを支援します。メタデータ生成、ソーシャルメディアの再利用、コンテンツ分析機能を提供","ko":"yt-genius는 YouTube 성장 전문가 및 콘텐츠 전략가로서 사용자가 비디오 콘텐츠의 도달 및 참여도를 최대화하도록 도와줍니다. 메타데이터 생성, 소셜 미디어 재사용, 콘텐츠 분석 기능을 제공","es":"yt-genius es una herramienta de inteligencia artificial que ayuda a los desarrolladores a generar metadatos y capítulos para videos de YouTube","fr":"yt-genius est un outil d''intelligence artificielle qui aide les développeurs à générer des métadonnées et des chapitres pour les vidéos YouTube","de":"yt-genius ist ein KI-Tool, das Entwicklern hilft, Metadaten und Kapitel für YouTube-Videos zu generieren","pt":"O yt-genius é uma habilidade que ajuda a gerar metadados e capítulos para vídeos do YouTube, melhorando o alcance e o engajamento do conteúdo","ru":"yt-genius - это навык, который помогает генерировать метаданные и главы для видео на YouTube, увеличивая охват и вовлеченность контента","ar":"yt-genius هي مهارة تساعد في توليد البيانات الوصفية والفصول للفيديوهات على يوتيوب، مما يحسن مدى وارتباط المحتوى"},"seo":{"title":{"en":"yt-genius: YouTube Metadata Generation and Chapter Setup ...","zh":"yt-genius.setup 指南：AI 工具用于生成元数据和章节","ja":"yt-genius セットアップガイド：AI エージェントによるメタデータとチャプター生成","ko":"yt-genius 설정 가이드: AI 에이전트를 사용한 메타데이터 및 장 생성","es":"yt-genius: Guía de configuración para metadatos de YouTube","fr":"yt-genius: Guide de démarrage pour les métadonnées YouTube","de":"yt-genius: Einrichtungsanleitung für YouTube-Metadaten","pt":"Guia de Configuração do yt-genius para Otimização de Vídeos","ru":"Настройка yt-genius: Генерация Метаданных и Глава для You...","ar":"دليل yt-genius لإعداد الفيديوهات مع تحسين المتاديات"},"description":{"en":"Unlock YouTube growth with yt-genius! Generate click-worthy titles, SEO-optimized descriptions, and timestamped chapters. Get started now and boost your vide...","zh":"使用 yt-genius AI 工具生成点击吸引力的标题、SEO 优化描述、时间戳章节、信息卡和相关哈希标签","ja":"yt-genius AI エージェントを使用してクリック誘発的なタイトル、SEO 最適化された説明、タイムスタンプの章、情報カード、関連ハッシュタグを生成","ko":"yt-genius AI 에이전트를 사용하여 클릭 유도 제목, SEO 최적화 설명, 타임스탬프 장, 정보 카드 및 관련 해시태그 생성","es":"Maximiza el alcance de tus videos con yt-genius, la herramienta de inteligencia artificial para generar metadatos y capítulos de YouTube","fr":"Améliorez la portée de vos vidéos avec yt-genius, l''outil d''intelligence artificielle pour générer des métadonnées et des chapitres YouTube","de":"Erhöhen Sie die Reichweite Ihrer Videos mit yt-genius, dem KI-Tool für die Generierung von YouTube-Metadaten und Kapiteln","pt":"Aprenda a configurar o yt-genius para gerar títulos atraentes, descrições otimizadas para SEO e capítulos temporizados para vídeos do YouTube","ru":"Узнайте, как настроить yt-genius для генерации привлекательных названий, описаний, оптимизированных для SEO, и временных глав для видео на YouTube","ar":"تعلم كيفية 설정 yt-genius لإنشاء عناوين جذابة ووصف محسن لتحسين محركات البحث وأفلام مؤطرة للفيديوهات على يوتيوب"},"definition":{"en":"yt-genius is a skill that generates metadata and chapters for YouTube videos, including click-worthy titles, SEO-optimized descriptions, and timestamped chapters.","zh":"yt-genius 是一种 AI 工具，用于生成 YouTube 元数据和章节，帮助用户提高视频内容的可发现性和参与度","ja":"yt-genius 