INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('peterfriese/yt-genius-skill/yt-genius', 'yt-genius', 'peterfriese', 'yt-genius-skill', 'community', 'yt-genius peterfriese yt-genius-skill community yt-genius is a YouTube growth expert skill that helps maximize video content reach and engagement by generating metadata and chapters. It benefits YouTube content creators and strategists. yt-genius 是一个 YouTube 增长专家和内容策略师，帮助用户最大化视频内容的reach 和参与度，提供元数据生成、社交媒体重用和内容分析功能 yt-genius は YouTube 成長エキスパートとコンテンツストラテジストであり、ユーザーがビデオコンテンツのリーチとエンゲージメントを最大化するのを支援します。メタデータ生成、ソーシャルメディアの再利用、コンテンツ分析機能を提供 yt-genius는 YouTube 성장 전문가 및 콘텐츠 전략가로서 사용자가 비디오 콘텐츠의 도달 및 참여도를 최대화하도록 도와줍니다. 메타데이터 생성, 소셜 미디어 재사용, 콘텐츠 분석 기능을 제공 yt-genius es una herramienta de inteligencia artificial que ayuda a los desarrolladores a generar metadatos y capítulos para videos de YouTube yt-genius est un outil d''intelligence artificielle qui aide les développeurs à générer des métadonnées et des chapitres pour les vidéos YouTube yt-genius ist ein KI-Tool, das Entwicklern hilft, Metadaten und Kapitel für YouTube-Videos zu generieren O yt-genius é uma habilidade que ajuda a gerar metadados e capítulos para vídeos do YouTube, melhorando o alcance e o engajamento do conteúdo yt-genius - это навык, который помогает генерировать метаданные и главы для видео на YouTube, увеличивая охват и вовлеченность контента yt-genius هي مهارة تساعد في توليد البيانات الوصفية والفصول للفيديوهات على يوتيوب، مما يحسن مدى وارتباط المحتوى how to use yt-genius yt-genius alternative yt-genius setup guide what is yt-genius yt-genius vs YouTube SEO tools yt-genius install YouTube metadata generation yt-genius for YouTube growth yt-genius chapter setup yt-genius AI 工具 YouTube 元数据生成 社交媒体重用 内容分析 SEO 优化 点击吸引力 信息卡 哈希标签 Metadata Generation: creates click-worthy titles and SEO-optimized descriptions Social Media Repurposing: drafts posts for Twitter/X, LinkedIn, Bluesky, Mastodon, Threads, and YouTube Community Content Analysis: identifies potential ''Shorts'' segments Generates timestamped chapters and info cards Adds relevant hashtags for improved discoverability yt-genius is a skill that generates metadata and chapters for YouTube videos, including click-worthy titles, SEO-optimized descriptions, and timestamped chapters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flourine95/zent-ui/vercel-composition-patterns', 'community', 'flourine95', 'zent-ui', 'flourine95/zent-ui', 'vercel-composition-patterns', 0, 0, 44, '2026-03-08T01:57:15.636Z', '2026-03-08T02:13:39.490Z', 'e38e0eaa609316b10423a9a138ed95e35099accd3f735585295c8a8f165c28a3', '{"id":"flourine95/zent-ui/vercel-composition-patterns","name":"vercel-composition-patterns","description":{"en":"Vercel composition patterns provide guidelines for building flexible React components, benefiting developers and AI agents alike by simplifying codebases and improving scalability.","zh":"Vercel 组合模式提供了一种优化 React 组件的方法，通过避免布尔属性过度，提高代码可维护性","ja":"Vercel Composition Patterns は、Boolean プロパティの増加を避けて React コンポーネントを最適化し、コードの保守性を高める方法を提供します","ko":"Vercel 컴포지션 패턴은 React 컴포넌트를 최적화하고, 불리언 속성의 과다 생성을 방지하여 코드의 유지 보수성을 향상시키는 방법을 제공합니다","es":"Patrones de composición para construir componentes de React flexibles y mantenibles. Evita la proliferación de propiedades booleanas con componentes compuestos y estado elevado","fr":"Modèles de composition pour créer des composants React flexibles et maintenables. Évitez la prolifération des propriétés booléennes avec des composants composés et un état élevé","de":"Zusammensetzungs-Muster für die Erstellung flexibler und wartbarer React-Komponenten. Vermeiden Sie die Ausbreitung von booleschen Eigenschaften mit zusammengesetzten Komponenten und angehobenem Zustand","pt":"Padrões de composição para construir componentes React flexíveis e mantenedores com o Vercel","ru":"Шаблоны композиции для создания гибких и поддерживаемых компонентов React с помощью Vercel","ar":"نماذج التكوين لبناء مكونات React مرنة وقابلة للصيانة مع Vercel"},"seo":{"title":{"en":"Vercel Composition Patterns: Best Practices for AI Agents...","zh":"Vercel 组合模式设置指南 - 优化 React 组件","ja":"Vercel Composition Patterns セットアップガイド - React コ