INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vivshaw/let-claude-say-fuck/fuck', 'fuck', 'vivshaw', 'let-claude-say-fuck', 'community', 'fuck vivshaw let-claude-say-fuck community The fuck skill enables AI agents to correct and retry failed bash commands using thefuck CLI utility, streamlining error handling for developers. fuck是一种使用thefuck CLI实用程序来纠正和重试失败的bash命令的技能 fuckは、thefuck CLIユーティリティを使用して失敗したbashコマンドを修正して再実行するスキルです fuck는 thefuck CLI 유틸리티를 사용하여 실패한 bash 명령을 수정하고 다시 실행하는 스킬입니다 fuck es una habilidad de Claude Code que permite a Claude decir ''fuck'' y utilizar la utilidad de línea de comandos thefuck para corregir comandos fallidos fuck est une compétence de Claude Code qui permet à Claude de dire ''fuck'' et d''utiliser l''utilitaire de ligne de commande thefuck pour corriger les commandes échouées fuck ist eine Fähigkeit von Claude Code, die es Claude ermöglicht, ''fuck'' zu sagen und die Befehlszeilen-Utility thefuck zu verwenden, um fehlgeschlagene Befehle zu korrigieren O Fuck é uma habilidade do Claude Code que permite dizer ''fuck'' e utilizar o thefuck CLI para corrigir erros de bash. Fuck - это навык Claude Code, который позволяет сказать ''fuck'' и использовать ИИ Агенты и thefuck CLI для исправления ошибок bash. Fuck هو مهارة من مهارات Claude Code التي تمكن من قول ''fuck'' واستخدام أداة سطر الأوامر thefuck لتصحيح أخطاء bash how to use fuck fuck alternative fuck setup guide thefuck CLI utility automated error correction bash command retry fuck AI技能 thefuck CLI实用程序 bash命令修正 AI工具 命令行实用程序 自动修正 Uses the thefuck CLI utility to correct and retry failed bash commands Automatically applies suggested fixes with `fuck --yeah` command Provides explanations for corrections made by thefuck utility Supports retrying failed commands with automated error handling fuck is a Claude Code skill that enables automated error correction and retry functionality for failed bash commands');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dyoshikawa/rulesync/rulesync', 'community', 'dyoshikawa', 'rulesync', 'dyoshikawa/rulesync', 'rulesync', 0, 0, 44, '2026-03-08T01:57:15.645Z', '2026-03-08T02:13:46.091Z', '5b26aded68d1eddc3f524368dc274e653cfe4052a1f4d07296c98a5c4a27c868', '{"id":"dyoshikawa/rulesync/rulesync","name":"rulesync","description":{"en":"rulesync is a Node.js CLI tool that generates configuration files for AI development tools from unified AI rule files, benefiting AI developers and teams.","zh":"Rulesync 是一款 Node.js CLI 工具，用于自动生成 AI 开发工具的配置文件。它支持多种 AI 开发工具，包括 Global Mode 和 Simulated Features","ja":"Rulesync は、AI 開発ツールの設定ファイルを自動生成する Node.js CLI ツールです。Global Mode や Simulated Features など、多種多様な機能をサポートしています","ko":"Rulesync는 AI 개발 도구의 구성 파일을 자동 생성하는 Node.js CLI 툴입니다. Global Mode와 Simulated Features 등을 포함한 다양한 기능을 지원합니다","es":"Rulesync es una herramienta de línea de comandos de Node.js que genera archivos de configuración para varias herramientas de desarrollo de IA","fr":"Rulesync est un outil de ligne de commande Node.js qui génère des fichiers de configuration pour divers outils de développement d''IA","de":"Rulesync ist ein Node.js-CLI-Tool, das Konfigurationsdateien für verschiedene KI-Entwicklungstools generiert","pt":"O Rulesync é uma ferramenta CLI que gera arquivos de configuração para ferramentas de desenvolvimento AI. Ele suporta configuração global e modo simulado","ru":"Rulesync - утилита CLI, которая генерирует файлы конфигурации для инструментов разработки ИИ. Она поддерживает глобальную конфигурацию и режим симуляции","ar":"Rulesync هو أداة سطر أوامر ي动生成 ملفات تعريف الإعدادات لأدوات تطوير الذكاء الاصطناعي. يدعم الوضع العالمي والسمات المحاكاة"},"seo":{"title":{"en":"rulesync: Setup Guide for AI Agents | CLI Tool","zh":"Rulesync Setup Guide: AI 编码代理工具配置","ja":"Rulesync 導入ガイド: AI エージェントのための CLI ツール","ko":"Rulesync 설정 가이드: