INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dyoshikawa/rulesync/rulesync', 'rulesync', 'dyoshikawa', 'rulesync', 'community', 'rulesync dyoshikawa rulesync community rulesync is a Node.js CLI tool that generates configuration files for AI development tools from unified AI rule files, benefiting AI developers and teams. Rulesync 是一款 Node.js CLI 工具，用于自动生成 AI 开发工具的配置文件。它支持多种 AI 开发工具，包括 Global Mode 和 Simulated Features Rulesync は、AI 開発ツールの設定ファイルを自動生成する Node.js CLI ツールです。Global Mode や Simulated Features など、多種多様な機能をサポートしています Rulesync는 AI 개발 도구의 구성 파일을 자동 생성하는 Node.js CLI 툴입니다. Global Mode와 Simulated Features 등을 포함한 다양한 기능을 지원합니다 Rulesync es una herramienta de línea de comandos de Node.js que genera archivos de configuración para varias herramientas de desarrollo de IA Rulesync est un outil de ligne de commande Node.js qui génère des fichiers de configuration pour divers outils de développement d''IA Rulesync ist ein Node.js-CLI-Tool, das Konfigurationsdateien für verschiedene KI-Entwicklungstools generiert O Rulesync é uma ferramenta CLI que gera arquivos de configuração para ferramentas de desenvolvimento AI. Ele suporta configuração global e modo simulado Rulesync - утилита CLI, которая генерирует файлы конфигурации для инструментов разработки ИИ. Она поддерживает глобальную конфигурацию и режим симуляции Rulesync هو أداة سطر أوامر ي动生成 ملفات تعريف الإعدادات لأدوات تطوير الذكاء الاصطناعي. يدعم الوضع العالمي والسمات المحاكاة how to use rulesync rulesync setup guide rulesync alternative rulesync vs other CLI tools rulesync install what is rulesync rulesync Node.js AI development tool configuration unified AI rule files Rulesync AI 编码代理 Node.js CLI AI 开发工具 Global Mode Simulated Features Declarative Sources Generates configuration files for various AI development tools Supports global mode for unified configurations Utilizes declarative sources for simplified rule management Includes simulated features for testing and development Provides official skills for streamlined AI agent integration rulesync is a utility CLI tool for automating AI coding agent configurations, supporting features like global mode and declarative sources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Layer-Fi/bookkeeper-skill/bookkeeper', 'community', 'Layer-Fi', 'bookkeeper-skill', 'Layer-Fi/bookkeeper-skill', 'bookkeeper', 0, 0, 44, '2026-03-08T01:57:15.657Z', '2026-03-08T02:13:59.847Z', '5c9c8e7ba0f99565ec6866289dd118247909870729708c6d72eec1b519273a6a', '{"id":"Layer-Fi/bookkeeper-skill/bookkeeper","name":"bookkeeper","description":{"en":"The Bookkeeper skill helps users manage financial data with precision, following core principles like never assuming or inferring values. It benefits users who require accurate financial record-keeping.","zh":"Layer Bookkeeper 是一个精确的会计助手，帮助用户管理财务数据。它遵循精确性和准确性的原则，确保财务数据的可靠性","ja":"Layer Bookkeeper は、精確な会計アシスタントであり、ユーザーが財務データを管理するのを支援します。精確性と正確性の原則に従って、財務データの信頼性を確保します","ko":"Layer Bookkeeper는 정확한 회계 도우미로 사용자가 재무 데이터를 관리하도록 도와줍니다. 精确性과 正確性의 原則을 따르며 재무 데이터의 신뢰성을 보장합니다","es":"El bookkeeper es una herramienta de gestión financiera que utiliza el servidor MCP de Layer Bookkeeper para ayudar a los usuarios a gestionar sus datos financieros con precisión.","fr":"Le bookkeeper est un outil de gestion financière qui utilise le serveur MCP de Layer Bookkeeper pour aider les utilisateurs à gérer leurs données financières avec précision.","de":"Der Bookkeeper ist ein Finanzmanagement-Tool, das den Layer Bookkeeper-MCP-Server verwendet, um Benutzern bei der Verwaltung ihrer Finanzdaten mit Präzision zu helfen.","pt":"O Bookkeeper é um assistente de gerenciamento de dados financeiros que valoriza a precisão sobre a suposição. Aprenda a configurá-lo com eficiência.","ru":"ИИ Агент Bookkeeper - это помощник по управлению финансовыми данными, который отдает предпочтение точности над предположением. Узнайте, как настроить его эффективно.","ar":"محاسب الكتاب هو مساعد لإدارة البيانات المالية يقدّر الدقة على الافتراض. تعلم كيفية إعداده بفعالية."},"seo":{"title":{"en":"Bookkeeper: Precision Financial Management for AI Agents ...","zh":"精确记账助手设置指南 - Layer Bookkeeper","ja":"Layer Bookkeeper の設置ガイド - 精確な会計アシスタント","ko":"정확한 회계 도우미 설정 가이드 - Layer Bookkeeper","es":"Guía de configuración del bookkeeper: Precisión financiera","fr":"Guide de mise en place du bookkeeper: Précision financière","de":"Einrichtungsleitfaden für den Bookkeeper: Finanzielle Prä...","pt":"Guia de Configuração do Bookkeeper: Práticas de Precisão","ru":"Настройка ИИ Агента Bookkeeper: Лучшие Практики","ar":"دليل إعداد محاسب الكتاب: أفضل الممارسات"},"description":{"en":"Unlock precise financial data management with Bookkeeper. Learn how to setup and utilize this AI agent skill for accurate journal entries and account managem...","zh":"使用 Layer Bookkeeper MCP 服务器管理财务数据，确保精确性和准确性。了解如何设置和使用此 AI 会计助手","ja":"Layer Bookkeeper MCP サーバーを使用して財務データを管理し、精確性と正確性を確保します。この AI 会計アシスタントの設定方法と使用方法をご覧ください","ko":"Layer Bookkeeper MCP 서버를 사용하여 재무 데이터를 관리하고 정확성을 보장합니다. 이 AI 회계 도우미를 설정하고 사용하는 방법에 대해 알아보세요","es":"Aprende a configurar el bookkeeper para gestionar datos financieros con precisión. Descubre las mejores prácticas y características clave.","fr":"Découvrez comment configurer le bookkeeper pour gérer les données financières avec précision. Consultez les meilleures pratiques et les fonctionnalités clés.","de":"Erfahren Sie, wie Sie den Bookkeeper einrichten, um Finanzdaten mit Präzision zu verwalten. Entdecken Sie die besten Praktiken und wichtigsten Funktionen.","pt":"Aprenda a configurar o Bookkeeper com precisão e eficiência. Descubra as melhores práticas para gerenciar dados financeiros com este guia.","ru":"Узнайте, как настроить ИИ Агента Bookkeeper с точностью и эффективностью. Откройте для себя лучшие практики для управления финансовыми данными с помощью этог...","ar":"تعلم كيفية إعداد محاسب الكتاب بدقة وفعالية. اكتشف أفضل الممارسات لإدارة البيانات المالية مع هذا الدليل."},"definition":{"en":"Bookkeeper is a meticulous bookkeeper assistant using the Layer Bookkeeper MCP server to manage financial data with absolute precision.","zh":"Layer Bookkeeper 是一个基于 MCP 服务器的 AI 会计助手，旨在帮助用户精确管理财务数据","ja":"Layer Bookkeeper は、MCP サーバーを基盤とする AI 会計アシスタントであり、ユーザーが財務データを精確に管理することを目的としています","ko":"Layer Bookkeeper는 MCP 서버를 기반으로 하는 AI 회계 도우미로 사용자가 재무 데이터를 정확하게 관리하도록 도와줍니다","es":"Un bookkeeper es una herramienta de gestión financiera que ayuda a los usuarios a gestionar sus datos financieros con precisión y exactitud.","fr":"Un bookkeeper est un outil de gestion financière qui aide les utilisateurs à gérer leurs données financières avec précision et exactitude.","de":"Ein Bookkeeper ist ein Finanzmanagement-Tool, das Benutzern hilft, ihre Finanzdaten mit Präzision und Genauigkeit zu verwalten.","pt":"O Bookkeeper é um assistente de gerenciamento de dados financeiros que ajuda os usuários a gerenciar suas finanças com precisão.","ru":"ИИ Агент Bookkeeper - это помощник по управлению финансовыми данными, который помогает пользователям управлять своими финансами с точностью.","ar":"محاسب الكتاب هو مساعد لإدارة البيانات المالية يساعد المستخدمين على إدارة أموالهم بدقة."},"features":{"en":["Follows core principle of precision over assumption for financial data management","Requires exact amounts and dates for journal entries, avoiding ambiguity","Utilizes the Layer Bookkeeper MCP server for precise financial record-keeping","Asks for clarification on ambiguous requests, such as unclear account information","Enforces strict data entry standards, including no default dates for journal entries"],"zh":["基于 Layer Bookkeeper MCP 服务器的精确会计管理","遵循精确性和准确性的原则","支持ambiguous金额和日期的自动识别和纠正","提供明确的账户和交易记录","确保财务数据的可靠性和安全性"],"ja":["Layer Bookkeeper MCP サーバーを基盤とする精確な会計管理","精確性と正確性の原則に従った設計","ambiguous 金額と日付の自動認識と修正をサポート","明確な口座と取引レコードを提供","財務データの信頼性とセキュリティを確保"],"ko":["Layer Bookkeeper MCP 서버를 기반으로 하는 정확한 회계 관리","정확성과 正確性的 原則을 따르는 설계","ambiguous 금액과 날짜의 자동 인식과 수정을 지원","명확한 계정과 거래 기록을 제공","재무 데이터의 신뢰성과 보안성을 보장"],"es":["Gestión de datos financieros con precisión","Uso del servidor MCP de Layer Bookkeeper","No asume ni infiere valores","Requiere fechas claras para las entradas de diario","Requiere cuentas claras para las transacciones"],"fr":["Gestion des données financières avec précision","Utilisation du serveur MCP de Layer Bookkeeper","N''assume ni n''infère les valeurs","Exige des dates claires pour les entrées de journal","Exige des comptes clairs pour les transactions"],"de":["Finanzdatenverwaltung mit Präzision","Verwendung des Layer Bookkeeper-MCP-Servers","Nimmt keine Annahmen oder Vermutungen vor","Erfordert klare Daten für die Journal-Einträge","Erfordert klare Konten für die Transaktionen"],"pt":["Precisão sobre suposição para garantir a exatidão dos dados financeiros","Requisitos de clarificação para montantes ambíguos e datas faltantes","Integração com o servidor MCP da Layer para gerenciamento de dados financeiros","Suporte a entradas de diário com datas específicas","Capacidade de parar e solicitar clarificação quando necessário"],"ru":["Точность над предположением для обеспечения точности финансовых данных","Требования к уточнению для неоднозначных сумм и отсутствующих дат","Интеграция с сервером MCP от Layer для управления финансовыми данными","Поддержка записей журнала с конкретными датами","Способность останавливаться и запрашивать уточнение при необходимости"],"ar":["الدقة على الافتراض لضمان دقة البيانات المالية","متطلبات التوضيح للكميات الغامضة والتواريخ الناقصة","التكامل مع خادم MCP من Layer لإدارة البيانات المالية","دعم إدخال دفتر اليومية بالتواريخ المحددة","القدرة على التوقف وطلب التوضيح عند الحاجة"]},"keywords":{"en":["how to use bookkeeper","what is bookkeeper","bookkeeper alternative","bookkeeper vs quickbooks","bookkeeper setup guide","bookkeeper install","layer bookkeeper mcp server","precision financial management","ai agent bookkeeper"],"zh":["AI 会计助手","Layer Bookkeeper","MCP 服务器","精确会计管理","财务数据管理","会计软件","AI 财务工具","自动记账","财务分析"],"ja":["AI 会計アシスタント","Layer Bookkeeper","MCP サーバー","精確な会計管理","財務データ管理","会計ソフトウェア","AI 財務ツール","自動記帳","財務分析"],"ko":["AI 회계 도우미","Layer Bookkeeper","MCP 서버","정확한 회계 관리","재무 데이터 관리","회계 소프트웨어","AI 재무 도구","자동 회계","재무 분석"],"es":["bookkeeper","gestión financiera","precisión financiera","Layer Bookkeeper","MCP servidor","datos financieros","gestión de cuentas"],"fr":["bookkeeper","gestion financière","précision financière","Layer Bookkeeper","serveur MCP","données financières","gestion de comptes"],"de":["Bookkeeper","Finanzmanagement","finanzielle Präzision","Layer Bookkeeper","MCP-Server","Finanzdaten","Kontenverwaltung"],"pt":["bookkeeper","gerenciamento de dados financeiros","precisão sobre suposição","configuração do bookkeeper","melhores práticas de bookkeeper","ferramentas de gerenciamento de finanças","servidor MCP da Layer","entrada de diário","dados financeiros precisos"],"ru":["ИИ Агент Bookkeeper","управление финансовыми данными","точность над предположением","настройка ИИ Агента Bookkeeper","лучшие практики ИИ Агента Bookkeeper","инструменты управления финансами","сервер MCP от Layer","запись журнала","точные финансовые данные"],"ar":["محاسب الكتاب","إدارة البيانات المالية","الدقة على الافتراض","إعداد محاسب الكتاب","أفضل الممارسات لمحاسب الكتاب","أدوات إدارة الأموال","خادم MCP من Layer","دفتر اليومية","بيانات مالية دقيقة"]}},"owner":"Layer-Fi","repo":"bookkeeper-skill","repoPath":"Layer-Fi/bookkeeper-skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.657Z","topics":[],"category":"community","skillMd":{"name":"bookkeeper","description":"Manage bookkeeping tasks using the Layer API. Use for journal entries, account management, financial reports (P&L, balance sheet), ledger accounts, and categorizing transactions. Invoke when users mention accounting, bookkeeping, journal entries, chart of accounts, P&L, profit and loss, balance sheet, or financial reports.","version":"1.0.0","bodyPreview":"# Layer Bookkeeper\n\nYou are a meticulous bookkeeper assistant using the Layer Bookkeeper MCP server. Your role is to help users manage their financial data with absolute precision.\n\n## Core Principles\n\n### 1. Precision Over Assumption\n\n**NEVER assume or infer values.** If the user''s request contains ANY of the following, STOP and ask for clarification:\n\n- Ambiguous amounts (e.g., \"about $100\", \"roughly 500\")\n- Missing dates (default dates are not acceptable for journal entries)\n- Unclear account","body":"# Layer Bookkeeper\n\nYou are a meticulous bookkeeper assistant using the Layer Bookkeeper MCP server. Your role is to help users manage their financial data with absolute precision.\n\n## Core Principles\n\n### 1. Precision Over Assumption\n\n**NEVER assume or infer values.** If the user''s request contains ANY of the following, STOP and ask for clarification:\n\n- Ambiguous amounts (e.g., \"about $100\", \"roughly 500\")\n- Missing dates (default dates are not acceptable for journal entries)\n- Unclear account names (if multiple accounts could match, ask which one)\n- Vague business references (if multiple businesses exist, confirm which one)\n- Incomplete journal entries (debits must equal credits - if they don''t balance, ask)\n- Unclear transaction descriptions\n\n**Example - DO NOT DO THIS:**\n```\nUser: \"Add an expense for office supplies\"\nBad: Create a $100 journal entry for office supplies dated today\nGood: \"I need more details to create this entry:\n  - What is the exact amount?\n  - What date should this be recorded?\n  - Which business is this for?\n  - What account should be credited (Cash, Accounts Payable, etc.)?\"\n```\n\n### 2. Two-Step Change Protocol\n\nALL data modifications MUST follow this process:\n\n**Step 1: Prepare and Preview**\n- Use `prepare_*` tools to stage the change\n- Present BOTH:\n  1. **A graphical summary** - Human-readable table showing the change (see formats below)\n  2. **The exact request body** - Raw JSON that will be sent to the API\n- Wait for explicit user approval\n\n**Graphical Summary Formats:**\n\nFor Journal Entries:\n```\n┌─────────────────────────────────────────────────────────────┐\n│ JOURNAL ENTRY PREVIEW                                       │\n├─────────────────────────────────────────────────────────────┤\n│ Business: Acme Inc                                          │\n│ Date:     January 15, 2026                                  │\n│ Memo:     Inventory purchase                                │\n├─────────────────────────────────────────────────────────────┤\n│ Account                    │    Debit    │    Credit        │\n│────────────────────────────┼─────────────┼──────────────────│\n│ Inventory                  │   $500.00   │                  │\n│ Cash                       │             │   $500.00        │\n├─────────────────────────────────────────────────────────────┤\n│ TOTAL                      │   $500.00   │   $500.00    ✓   │\n└─────────────────────────────────────────────────────────────┘\n```\n\nFor Account Changes:\n```\n┌─────────────────────────────────────────────────────────────┐\n│ ACCOUNT UPDATE PREVIEW                                      │\n├─────────────────────────────────────────────────────────────┤\n│ Account: Office Supplies (OFFICE_SUPPLIES)                  │\n├─────────────────────────────────────────────────────────────┤\n│ Field            │ Current Value    │ New Value             │\n│──────────────────┼──────────────────┼───────────────────────│\n│ display_name     │ Office Supplies  │ Office & Shop Supply  │\n│ description      │ (empty)          │ General supplies      │\n└─────────────────────────────────────────────────────────────┘\n```\n\nFor Transaction Categorization:\n```\n┌─────────────────────────────────────────────────────────────┐\n│ TRANSACTION CATEGORIZATION PREVIEW                          │\n├─────────────────────────────────────────────────────────────┤\n│ Transaction: AMZN Mktp US - $47.82                          │\n│ Date: January 10, 2026                                      │\n├─────────────────────────────────────────────────────────────┤\n│ Category:  Office Expenses                                  │\n│ Account:   OFFICE_EXPENSES                                  │\n└─────────────────────────────────────────────────────────────┘\n```\n\n**Step 2: Execute Only After Approval**\n- Only call `execute_prepared_request` after user confirms\n- If user says anything other than clear approval, do NOT execute\n- After execution, fetch and display before/after reports\n\n### 3. Before/After Reporting\n\nFor ANY executed change, you MUST show the financial impact:\n\n**For Journal Entries:**\n1. Before execution: Fetch P&L and Balance Sheet for the affected period\n2. Execute the change\n3. After execution: Fetch P&L and Balance Sheet again\n4. Present a comparison table showing:\n   - Which line items changed\n   - The delta (difference) for each\n   - Net impact on profit/equity\n\n**Report Format:**\n```\n## Financial Impact Summary\n\n### Profit & Loss Changes (Period: YYYY-MM-DD to YYYY-MM-DD)\n| Account | Before | After | Change |\n|---------|--------|-------|--------|\n| Office Expenses | $0.00 | $123.45 | +$123.45 |\n| ... | ... | ... | ... |\n| **Net Profit** | $X | $Y | $Z |\n\n### Balance Sheet Changes (As of: YYYY-MM-DD)\n| Account | Before | After | Change |\n|---------|--------|-------|--------|\n| Cash | $1,000.00 | $876.55 | -$123.45 |\n| ... | ... | ... | ... |\n\n### Entry Details\n- Entry ID: [uuid]\n- Date: YYYY-MM-DD\n- Lines: [debit/credit breakdown]\n```\n\n## MCP Server\n\n**Use the `layer-bookkeeper` MCP server for ALL Layer API operations.**\n\nAll tools from this MCP server follow a naming pattern: `mcp__layer-bookkeeper__<tool_name>`\n\n### Tool Categories\n\n**Read Operations** (no approval needed) - Any tool that fetches data:\n- Listing businesses, accounts, transactions, categories\n- Getting reports (P&L, balance sheet)\n- Viewing chart of accounts\n\n**Write Operations** (MUST use prepare → approve → execute flow) - Any `prepare_*` tool:\n- These stage changes for review without executing them\n- Always show graphical summary + raw request body\n- Wait for explicit user approval\n\n**Execution Controls:**\n- `execute_prepared_request` - Execute an approved change (only after user confirms)\n- `cancel_prepared_request` - Cancel a staged change\n- `list_pending_requests` - View all staged changes\n\n### Discovering Available Tools\n\nIf you''re unsure what tools are available, the MCP server provides them dynamically. Common patterns:\n- `list_*` - List resources (businesses, accounts, transactions)\n- `get_*` - Get a specific resource or report\n- `prepare_*` - Stage a mutation for approval\n- `execute_*` / `cancel_*` - Manage staged mutations\n\nAs new tools are added to the MCP server, use them following the same principles:\n- Read operations: execute freely\n- Write operations: always use the two-step prepare → approve → execute flow\n\n## Workflow Examples\n\n### Creating a Journal Entry\n\n1. **Gather Requirements**\n   ```\n   User: \"I need to record that we paid $500 for inventory\"\n\n   You: \"I''ll help you record that inventory purchase. I need a few details:\n   1. Which business is this for? [list businesses if multiple]\n   2. What is the exact date of this transaction?\n   3. How was it paid? (Cash, credit card, accounts payable, etc.)\n   4. Should this be recorded as Inventory or Cost of Goods Sold?\"\n   ```\n\n2. **Prepare the Entry**\n   ```\n   After getting: Business=Acme Inc, Date=2026-01-15, Paid by=Cash, Account=Inventory\n\n   Use prepare_create_custom_journal_entry with:\n   - businessId: [uuid]\n   - entry_date: \"2026-01-15\"\n   - lines: [\n       { ledger_account_id: [Inventory UUID], amount: 50000, direction: \"DEBIT\" },\n       { ledger_account_id: [Cash UUID], amount: 50000, direction: \"CREDIT\" }\n     ]\n   ```\n\n3. **Present for Approval**\n\n   First, show the graphical summary:\n   ```\n   ┌─────────────────────────────────────────────────────────────┐\n   │ JOURNAL ENTRY PREVIEW                      ID: abc-123     │\n   ├─────────────────────────────────────────────────────────────┤\n   │ Business: Acme Inc                                          │\n   │ Date:     January 15, 2026                                  │\n   │ Memo:     Inventory purchase - cash payment                 │\n   ├─────────────────────────────────────────────────────────────┤\n   │ Account                    │    Debit    │    Credit        │\n   │────────────────────────────┼─────────────┼──────────────────│\n   │ Inventory                  │   $500.00   │                  │\n   │ Cash                       │             │   $500.00        │\n   ├─────────────────────────────────────────────────────────────┤\n   │ TOTAL                      │   $500.00   │   $500.00    ✓   │\n   └─────────────────────────────────────────────────────────────┘\n   ```\n\n   Then, show the raw request body:\n   ```json\n   {\n     \"entry_date\": \"2026-01-15\",\n     \"memo\": \"Inventory purchase - cash payment\",\n     \"lines\": [\n       {\n         \"ledger_account_id\": \"INVENTORY\",\n         \"amount\": 50000,\n         \"direction\": \"DEBIT\"\n       },\n       {\n         \"ledger_account_id\": \"CASH\",\n         \"amount\": 50000,\n         \"direction\": \"CREDIT\"\n       }\n     ]\n   }\n   ```\n\n   Finally, ask for approval:\n   ```\n   Do you approve this journal entry? (Yes/No)\n   ```\n\n4. **Execute and Report**\n   ```\n   [After user approves]\n\n   1. Fetch P&L and Balance Sheet BEFORE\n   2. Execute the entry\n   3. Fetch P&L and Balance Sheet AFTER\n   4. Show comparison\n   ```\n\n### Handling Ambiguity\n\n**Ambiguous Account:**\n```\nUser: \"Debit supplies\"\n\nYou: \"I found multiple accounts that could match ''supplies'':\n1. Office Supplies (OFFICE_SUPPLIES) - for general office materials\n2. Cleaning Supplies (CLEANING_SUPPLIES) - for janitorial items\n3. Shop Supplies (SHOP_SUPPLIES) - for operational materials\n\nWhich account should I use?\"\n```\n\n**Unbalanced Entry:**\n```\nUser: \"Debit Office Expenses $100, credit Cash $90\"\n\nYou: \"This entry doesn''t balance:\n- Total Debits: $100.00\n- Total Credits: $90.00\n- Difference: $10.00\n\nJournal entries must have equal debits and credits. How should I handle the $10 difference?\"\n```\n\n## Error Handling\n\nIf any API call fails:\n1. Report the exact error message\n2. Explain what it likely means\n3. Suggest how to fix it\n4. Do NOT retry without user confirmation\n\nCommon errors:\n- `404 Business not found` - Business may be archived or ID is wrong\n- `400 Invalid ledger_account_id` - Account doesn''t exist or wrong stable_name\n- `400 Entry does not balance` - Debits ≠ Credits\n\n## Important Reminders\n\n1. **Amounts are in CENTS** - $123.45 = 12345 in the API\n2. **Always verify account existence** before creating entries - use `get_chart_of_accounts`\n3. **Dates must be explicit** - never use \"today\" or assume dates\n4. **One business at a time** - confirm which business before any operation\n5. **Show your work** - always display the exact values being sent to the API\n6. **Account identifiers are polymorphic** - use StableName for standard accounts, AccountId for custom accounts. See `accounts-reference.md` for details.\n\n## Bulk Operations\n\nWhen processing multiple journal entries (e.g., rebates, batch adjustments):\n\n### 1. Idempotency is Mandatory\n\nEvery entry MUST have an `external_id` following this pattern:\n```\n{operation}-{period}-{entity_type}-{business_id}\n```\nExample: `moxie-2025-q4-rebate-pc-016814a2-0137-46a7-92c9-d534237b8067`\n\nThis enables safe retries - if an operation fails partway through, you can re-run without creating duplicates.\n\n### 2. Filter by Identifier, Never by Position\n\nWhen excluding items from bulk operations:\n- **ALWAYS** filter by unique identifier (business_id, medspa_id, external_id)\n- **NEVER** assume list/array ordering\n- **NEVER** use positional indexing to skip items\n\n```javascript\n// WRONG - assumes position\nconst startIndex = 7; // Skip first 7\n\n// CORRECT - filters by identity\nif (biz.business_id === ''abc-123'') {\n  console.log(`Skipping ${biz.name} - already processed`);\n  continue;\n}\n```\n\n### 3. Pre-Mutation Verification\n\nBefore executing ANY bulk operation, explicitly state:\n1. Total count of items to process\n2. Any exclusions BY NAME AND ID (not position)\n3. Sample of first/last items to verify ordering assumptions\n\nExample:\n```\nProcessing 163 businesses (excluding Citrus Aesthetics [id: 87d57ff2-...] - already processed)\nFirst: Revitalized Med Spa ($104.26)\nLast: Aesthoria Aesthetics ($0.52)\n```\n\n### 4. PC/MSO Rebate Pattern\n\nFor businesses with PC/MSO structure, create TWO entries:\n\n**PC Entry (tag: entity=pc):**\n```\nDEBIT   OTHER_MOXIE_SALES                    [amount]\nCREDIT  MSO_MANAGEMENT_EXPENSE_MOXIE_FEES    [amount]\n```\n\n**MSO Entry (tag: entity=mso):**\n```\nDEBIT   MSO_MANAGEMENT_REVENUE_MOXIE_FEES    [amount]\nCREDIT  MOXIE_FEES                           [amount]\n```\n\nFor non-PC/MSO businesses, create ONE entry:\n```\nDEBIT   OTHER_MOXIE_SALES    [amount]\nCREDIT  MOXIE_FEES           [amount]\n```\n\n## Reference Documentation\n\n- **accounts-reference.md** - Account identifier formats (AccountId vs StableName), common stable names, debit/credit rules, and journal entry examples\n"},"lastSynced":"2026-03-08T02:13:59.847Z","agentAnalysis":{"suitability":{"en":"Perfect for Accounting Agents needing precise financial data management with strict adherence to core principles like precision over assumption","zh":"适合需要精确财务数据管理并严格遵守核心原则（如精确优于假设）的会计代理","ja":"会計エージェントが精確な財務データ管理を必要とする場合に適しています。厳密な原則（精確さを仮定よりも優先するなど）に従う必要があります","ko":"정확한 재무 데이터 관리와 핵심 원칙을 엄격히 준수해야 하는 회계 에이전트에게 적합합니다. 예를 들어, 가정보다 정밀도를 우선합니다.","es":"Perfecto para Agentes de Contabilidad que necesitan un manejo de datos financieros precisos con estricta adhesión a principios básicos como la precisión sobre la suposición","fr":"Parfait pour les agents comptables ayant besoin d''une gestion de données financières précises avec une stricte adhésion aux principes fondamentaux tels que la précision plutôt que la supposition","de":"Perfekt für Buchhaltungsagenten, die eine präzise Finanzdatenverwaltung mit strenger Einhaltung von Grundprinzipien wie Präzision anstelle von Annahmen benötigen","pt":"Perfeito para Agentes de Contabilidade que necessitam de gestão de dados financeiros precisos com aderência estrita a princípios básicos como precisão em vez de suposição","ru":"Идеально подходит для агентов бухгалтерского учета, которым необходима точная система управления финансовыми данными с строгим соблюдением основных принципов, таких как точность вместо предположения","ar":"مثالي لعمليات وكالات المحاسبة التي تحتاج إلى إدارة بيانات مالية دقيقة مع الالتزام الصارم بمبادئ أساسية مثل الدقة على افتراض"},"recommendation":{"en":"Empowers agents to manage financial records with absolute precision, following core principles like never assuming or inferring values, and handling ambiguous amounts, missing dates, and unclear accounts through clarification requests, utilizing the Layer Bookkeeper MCP server for meticulous financial data tracking","zh":"赋予代理人以绝对精度管理财务记录的能力，遵循核心原则，如不假设或推断值，并通过澄清请求处理模糊金额、缺失日期和不明确账户，利用Layer Bookkeeper MCP服务器进行细致的财务数据跟踪","ja":"エージェントが絶対の精度で財務レコードを管理できるようにします。値を仮定したり推論したりしないなど、コアプリンシプルに従い、明確化リクエストを介して曖昧な金額、欠落日、不明確なアカウントを処理します。また、Layer Bookkeeper MCPサーバーを使用して、入念な財務データトラッキングを実行します","ko":"에이전트가 절대적인 정밀도로 재무 기록을 관리할 수 있도록 합니다. 값을 가정하거나 추론하지 않는 등 핵심 원칙을 따르고, 명확화 요청을 통해 모호한 금액, 누락된 날짜 및 불분명한 계정을 처리하며, Layer Bookkeeper MCP 서버를 사용하여 세밀한 재무 데이터 추적을 수행합니다.","es":"Empodera a los agentes para gestionar registros financieros con precisión absoluta, siguiendo principios básicos como nunca suponer o inferir valores, y manejar cantidades ambiguas, fechas perdidas y cuentas poco claras a través de solicitudes de aclaración, utilizando el servidor Layer Bookkeeper MCP para un seguimiento meticuloso de datos financieros","fr":"Permet aux agents de gérer les dossiers financiers avec une précision absolue, en suivant les principes fondamentaux tels que de ne jamais supposer ou déduire des valeurs, et en traitant les montants ambigus, les dates manquantes et les comptes peu clairs grâce à des demandes de clarification, en utilisant le serveur Layer Bookkeeper MCP pour un suivi méticuleux des données financières","de":"Ermächtigt Agenten, Finanzunterlagen mit absoluter Präzision zu verwalten, indem sie grundlegende Prinzipien wie das Nie-Annehmen oder Ableiten von Werten befolgen und mehrdeutige Beträge, fehlende Daten und unklare Konten durch Aufklärungsanfragen klären, unter Nutzung des Layer Bookkeeper MCP-Servers für eine gewissenhafte Finanzdatenverfolgung","pt":"Habilita os agentes a gerenciar registros financeiros com precisão absoluta, seguindo princípios básicos como nunca supor ou inferir valores, e lidar com montantes ambíguos, datas ausentes e contas incertas por meio de solicitações de esclarecimento, utilizando o servidor Layer Bookkeeper MCP para acompanhamento meticuloso de dados financeiros","ru":"Наделяет агентов возможностью управлять финансовыми записями с абсолютной точностью, следуя основным принципам, таким как никогда не предполагать или выводить значения, и обрабатывать неоднозначные суммы, отсутствующие даты и неясные счета через запросы на разъяснение, используя сервер Layer Bookkeeper MCP для тщательного отслеживания финансовых данных","ar":"يمنح الوكلاء القدرة على إدارة السجلات المالية بدقة مطلقة، متبعة مبادئ أساسية مثل أبدا افتراض أو استنتاج القيم، ومعالجة المبالغ الغامضة والأحكام المفقودة وال حسابات الغير واضحة من خلال طلبات التوضيح، باستخدام خادم Layer Bookkeeper MCP لتتبع بيانات مالية دقيق"},"useCases":{"en":["Automating financial data entry with precision","Generating accurate financial reports","Validating user requests for ambiguous financial data"],"zh":["使用精度自动化财务数据输入","生成准确的财务报告","验证用户对模糊财务数据的请求"],"ja":["精度の高い財務データ入力を自動化する","正確な財務レポートを生成する","ユーザーの曖昧な財務データに関するリクエストを検証する"],"ko":["정밀도 높은 재무 데이터 입력 자동화","정확한 재무 보고서 생성","사용자의 모호한 재무 데이터에 대한 요청 검증"],"es":["Automatización de la entrada de datos financieros con precisión","Generación de informes financieros precisos","Validación de solicitudes de usuarios para datos financieros ambiguos"],"fr":["Automatisation de la saisie de données financières avec précision","Génération de rapports financiers précis","Validation des demandes des utilisateurs pour des données financières ambiguës"],"de":["Automatisierung der Finanzdateneingabe mit Präzision","Erstellung genauer Finanzberichte","Validierung von Benutzeranfragen für mehrdeutige Finanzdaten"],"pt":["Automatizar a entrada de dados financeiros com precisão","Gerar relatórios financeiros precisos","Validar solicitações de usuários para dados financeiros ambíguos"],"ru":["Автоматизация ввода финансовых данных с точностью","Генерация точных финансовых отчетов","Проверка запросов пользователей на неоднозначные финансовые данные"],"ar":["أتمتة إدخال البيانات المالية بدقة","توليد تقارير مالية دقيقة","التحقق من طلبات المستخدمين لبيانات مالية غامضة"]},"limitations":{"en":["Requires explicit user input for financial data","No default dates accepted for journal entries","Unclear accounts must be clarified by the user"],"zh":["需要用户明确输入财务数据","不接受日记账条目的默认日期","不明确的账户必须由用户澄清"],"ja":["財務データの明示的なユーザー入力を必要とする","日記帳エントリのデフォルト日付は受け付けない","不明確なアカウントはユーザーによって明確化される必要がある"],"ko":["재무 데이터에 대한 사용자의 명시적 입력이 필요함","일기 계정 항목의 기본 날짜는 허용하지 않음","불분명한 계정은 사용자에 의해 명확화되어야 함"],"es":["Requiere entrada de usuario explícita para datos financieros","No se aceptan fechas predeterminadas para asientos de diario","Cuentas poco claras deben ser aclaradas por el usuario"],"fr":["Nécessite une saisie utilisateur explicite pour les données financières","Aucune date par défaut n''est acceptée pour les écritures de journal","Les comptes peu clairs doivent être clarifiés par l''utilisateur"],"de":["Benötigt explizite Benutzereingabe für Finanzdaten","Es werden keine Standard-Daten für Journal-Einträge akzeptiert","Unklare Konten müssen vom Benutzer geklärt werden"],"pt":["Exige entrada de usuário explícita para dados financeiros","Nenhuma data padrão é aceita para entradas de diário","Contas incertas devem ser esclarecidas pelo usuário"],"ru":["Требует явного ввода пользователя для финансовых данных","Не принимаются даты по умолчанию для записей в журнале","Неясные счета должны быть разъяснены пользователем"],"ar":["يتطلب إدخال مستخدم صريح للبيانات المالية","لا يتم قبول تواريخ افتراضية لمدخلات المجلة","يجب توضيح الحسابات الغامضة من قبل المستخدم"]},"version":4},"contentHash":"5c9c8e7ba0f99565ec6866289dd118247909870729708c6d72eec1b519273a6a","qualityScore":44}');
