INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Layer-Fi/bookkeeper-skill/bookkeeper', 'bookkeeper', 'Layer-Fi', 'bookkeeper-skill', 'community', 'bookkeeper Layer-Fi bookkeeper-skill community The Bookkeeper skill helps users manage financial data with precision, following core principles like never assuming or inferring values. It benefits users who require accurate financial record-keeping. Layer Bookkeeper 是一个精确的会计助手，帮助用户管理财务数据。它遵循精确性和准确性的原则，确保财务数据的可靠性 Layer Bookkeeper は、精確な会計アシスタントであり、ユーザーが財務データを管理するのを支援します。精確性と正確性の原則に従って、財務データの信頼性を確保します Layer Bookkeeper는 정확한 회계 도우미로 사용자가 재무 데이터를 관리하도록 도와줍니다. 精确性과 正確性의 原則을 따르며 재무 데이터의 신뢰성을 보장합니다 El bookkeeper es una herramienta de gestión financiera que utiliza el servidor MCP de Layer Bookkeeper para ayudar a los usuarios a gestionar sus datos financieros con precisión. Le bookkeeper est un outil de gestion financière qui utilise le serveur MCP de Layer Bookkeeper pour aider les utilisateurs à gérer leurs données financières avec précision. Der Bookkeeper ist ein Finanzmanagement-Tool, das den Layer Bookkeeper-MCP-Server verwendet, um Benutzern bei der Verwaltung ihrer Finanzdaten mit Präzision zu helfen. O Bookkeeper é um assistente de gerenciamento de dados financeiros que valoriza a precisão sobre a suposição. Aprenda a configurá-lo com eficiência. ИИ Агент Bookkeeper - это помощник по управлению финансовыми данными, который отдает предпочтение точности над предположением. Узнайте, как настроить его эффективно. محاسب الكتاب هو مساعد لإدارة البيانات المالية يقدّر الدقة على الافتراض. تعلم كيفية إعداده بفعالية. how to use bookkeeper what is bookkeeper bookkeeper alternative bookkeeper vs quickbooks bookkeeper setup guide bookkeeper install layer bookkeeper mcp server precision financial management ai agent bookkeeper AI 会计助手 Layer Bookkeeper MCP 服务器 精确会计管理 财务数据管理 会计软件 AI 财务工具 自动记账 财务分析 Follows core principle of precision over assumption for financial data management Requires exact amounts and dates for journal entries, avoiding ambiguity Utilizes the Layer Bookkeeper MCP server for precise financial record-keeping Asks for clarification on ambiguous requests, such as unclear account information Enforces strict data entry standards, including no default dates for journal entries Bookkeeper is a meticulous bookkeeper assistant using the Layer Bookkeeper MCP server to manage financial data with absolute precision.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rootcastleco/rei-skills/voice-agents', 'community', 'rootcastleco', 'rei-skills', 'rootcastleco/rei-skills', 'voice-agents', 0, 0, 44, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:03.224Z', '3669dfc73457df4b2c06311b454e431a0b0dd6ace91d362905947fe428762a6a', '{"id":"rootcastleco/rei-skills/voice-agents","name":"voice-agents","description":{"en":"The voice-agents skill provides 883+ universal agentic skills for voice AI architects, handling millions of calls with low latency. It benefits developers working with Claude Code, Gemini CLI, and Cursor.","zh":"语音AI代理技术是实现自然流畅的对话体验的关键，了解语音到语音模型和管道架构的差异","ja":"AIエージェントの音声アーキテクチャは会話体験を決定づける、Speech-to-speechモデルとPipelineアーキテクチャの違いを理解する","ko":"음성 AI 에이전트 기술은 자연스러운 대화 경험을实现하는 데 핵심입니다. 음성에서 음성 모델과 파이프라인 아키텍처의 차이를 알아보세요","es":"Los agentes de voz son soluciones de IA que permiten conversaciones naturales con usuarios, utilizando tecnologías como OpenAI Realtime API y arquitecturas de pipeline","fr":"Les agents vocaux sont des solutions d''IA qui permettent des conversations naturelles avec les utilisateurs, en utilisant des technologies comme OpenAI Realtime API et des architectures de pipeline","de":"Voice-Agents sind künstliche Intelligenz-Lösungen, die natürliche Konversationen mit Benutzern ermöglichen, unter Verwendung von Technologien wie OpenAI Realtime API und Pipeline-Architekturen","pt":"Os agentes de voz são arquiteturas de IA que permitem a interação por voz com baixa latência, utilizando modelos S2S ou pipeline","ru":"ИИ агенты голоса являются архитектурами ИИ, которые позволяют голосовое взаимодействие с низкой задержкой, используя модели S2S или pipeline","ar":"وكلاء الصوت هم هندسات ذكاء اصطناعي تسمح بالتفاعل الصوتي مع انخفاض التأخير، باستخدام نماذج S2S أو pipeline"},"seo":{"title":{"en":"Voice-Agents: Setup Guide for AI Agents","zh":"语音AI代理技术集成指南","ja":"AIエージェントの音声アーキテクチャ最適化","ko":"음성 AI 에이전트 구축 및 최적화 가이드","es":"Guía de configuración de agentes de voz para Claude Code ...","fr":"Guide de mise en place des agents vocaux pour Claude Code...","de":"Einrichtungsleitfaden für Voice-Agents mit Claude Code un...","pt":"Guia de Configuração de Agentes de Voz com Arquiteturas S...","ru":"Настройка ИИ Агентов Голоса с Архитектурами S2S и Pipeline","ar":"دليل إعداد وكلاء الصوت باستخدام هندسات S2S و Pipeline"},"description":{"en":"Unlock the power of voice-agents with our expert guide. Learn how to optimize latency and control in voice AI architectures. Get started now!","zh":"了解语音AI代理的核心技术，包括语音到语音模型和管道架构，实现自然流畅的对话体验","ja":"AIエージェントの音声アーキテクチャを最適化し、自然な会話体験を実現するためのテクニックを紹介","ko":"음성 AI 에이전트의 핵심 기술을 알아보고 자연스러운 대화 경험을实现하는 방법을 배워보세요","es":"Aprende a implementar agentes de voz con tecnologías como OpenAI Realtime API y arquitecturas de pipeline para STT, LLM y TTS","fr":"Découvrez comment mettre en œuvre des agents vocaux avec des technologies comme OpenAI Realtime API et des architectures de pipeline pour STT, LLM et TTS","de":"Erfahren Sie, wie Sie Voice-Agents mit Technologien wie OpenAI Realtime API und Pipeline-Architekturen für STT, LLM und TTS implementieren","pt":"Aprenda a configurar agentes de voz com arquiteturas S2S e Pipeline para melhorar a experiência do usuário com baixa latência","ru":"Узнайте, как настроить ИИ агентов голоса с архитектурами S2S и Pipeline для улучшения пользовательского опыта с низкой задержкой","ar":"تعلم كيفية إعداد وكلاء الصوت باستخدام هندسات S2S و Pipeline لتحسين تجربة المستخدم مع انخفاض التأخير"},"definition":{"en":"voice-agents is a collection of skills for designing and deploying voice AI agents, focusing on speech-to-speech and pipeline architectures.","zh":"语音AI代理是指使用语音技术实现人机对话的AI系统","ja":"AIエージェントとは、音声技術を用いて人間と会話するAIシステムのこと","ko":"음성 AI 에이전트는 음성 기술을 사용하여 인간과 대화하는 AI 시스템입니다","es":"Un agente de voz es un sistema de IA que procesa y responde a comandos de voz, utilizando tecnologías como STT, LLM y TTS","fr":"Un agent vocal est un système d''IA qui traite et répond à des commandes vocales, en utilisant des technologies comme STT, LLM et TTS","de":"Ein Voice-Agent ist ein künstliches Intelligenz-System, das Sprachbefehle verarbeitet und beantwortet, unter Verwendung von Technologien wie STT, LLM und TTS","pt":"Agentes de voz são sistemas de IA que processam e respondem a comandos de voz em tempo real","ru":"ИИ агенты голоса являются системами ИИ, которые обрабатывают и реагируют на голосовые команды в реальном времени","ar":"وكلاء الصوت هي أنظمة ذكاء اصطناعي تعالج وترد على أوامر الصوت في الوقت الفعلي"},"features":{"en":["Supports speech-to-speech (S2S) models like OpenAI Realtime API for low latency","Utilizes pipeline architectures (STT→LLM→TTS) for controllable voice AI","Optimizes latency in voice AI conversations for natural user experience","Compatible with Claude Code, Gemini CLI, and Cursor for seamless integration","Provides 883+ universal agentic skills for versatile voice AI development","Handles millions of calls with scalable and reliable voice AI architectures"],"zh":["支持语音到语音模型（S2S）","支持管道架构（STT→LLM→TTS）","实现低延迟的对话体验","支持多种音声技术","可用于多种应用场景"],"ja":["Speech-to-speechモデル（S2S）をサポート","パイプラインアーキテクチャ（STT→LLM→TTS）をサポート","低遅延の会話体験を実現","多種の音声技術をサポート","多種のアプリケーションシーンで使用可能"],"ko":["음성에서 음성 모델（S2S）을 지원","파이프라인 아키텍처（STT→LLM→TTS）을 지원","저지연의 대화 경험을 实现","다양한 음성 기술을 지원","다양한 애플리케이션 시나리오에서 사용 가능"],"es":["Arquitecturas de pipeline para STT, LLM y TTS","Integración con OpenAI Realtime API para baja latencia","Soporte para Claude Code y Gemini CLI","Control preciso en cada paso del proceso de conversación","Compatibilidad con tecnologías de reconocimiento de voz y síntesis de voz"],"fr":["Architectures de pipeline pour STT, LLM et TTS","Intégration avec OpenAI Realtime API pour une faible latence","Prise en charge de Claude Code et Gemini CLI","Contrôle précis à chaque étape du processus de conversation","Compatibilité avec les technologies de reconnaissance vocale et de synthèse vocale"],"de":["Pipeline-Architekturen für STT, LLM und TTS","Integration mit OpenAI Realtime API für geringe Latenz","Unterstützung für Claude Code und Gemini CLI","Präzise Kontrolle in jedem Schritt des Konversationsprozesses","Kompatibilität mit Spracherkennungs- und Sprachsynthese-Technologien"],"pt":["Arquiteturas S2S para baixa latência","Pipeline com STT, LLM e TTS para controle granular","Integração com Claude Code, Gemini CLI e Cursor","Suporte a milhões de chamadas","Preservação da emoção com modelos S2S"],"ru":["Архитектуры S2S для низкой задержки","Pipeline с STT, LLM и TTS для детального контроля","Интеграция с Claude Code, Gemini CLI и Cursor","Поддержка миллионов вызовов","Сохранение эмоций с моделями S2S"],"ar":["الهندسات S2S لانخفاض التأخير","الpipeline مع STT و LLM و TTS للتحكم المتعمق","التكامل مع Claude Code و Gemini CLI و Cursor","دعم ملايين المكالمات","الحفاظ على العواطف مع نماذج S2S"]},"keywords":{"en":["how to use voice-agents","voice-agents setup guide","voice-agents alternative","voice-agents vs OpenAI","what is voice-agents","voice-agents install","voice-agents for AI agents","speech-to-speech models","pipeline architectures for voice AI"],"zh":["语音AI代理","语音技术","AI对话","自然语言处理","语音到语音模型","管道架构","低延迟对话"],"ja":["AIエージェント","音声技術","AI会話","自然言語処理","Speech-to-speechモデル","パイプラインアーキテクチャ","低遅延会話"],"ko":["음성 AI 에이전트","음성 기술","AI 대화","자연어 처리","음성에서 음성 모델","파이프라인 아키텍처","저지연 대화"],"es":["agentes de voz","IA para voz","OpenAI Realtime API","arquitecturas de pipeline","STT","LLM","TTS","Claude Code","Gemini CLI","reconocimiento de voz"],"fr":["agents vocaux","IA pour la voix","OpenAI Realtime API","architectures de pipeline","STT","LLM","TTS","Claude Code","Gemini CLI","reconnaissance vocale"],"de":["Voice-Agents","künstliche Intelligenz für Sprache","OpenAI Realtime API","Pipeline-Architekturen","STT","LLM","TTS","Claude Code","Gemini CLI","Spracherkennung"],"pt":["agentes de voz","arquiteturas S2S","pipeline de voz","baixa latência","Claude Code","Gemini CLI","Cursor","STT","LLM","TTS"],"ru":["ИИ агенты голоса","архитектуры S2S","pipeline голоса","низкая задержка","Claude Code","Gemini CLI","Cursor","STT","LLM","TTS"],"ar":["وكلاء الصوت","الهندسات S2S","الpipeline الصوتي","انخفاض التأخير","Claude Code","Gemini CLI","Cursor","STT","LLM","TTS"]}},"owner":"rootcastleco","repo":"rei-skills","repoPath":"rootcastleco/rei-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"voice-agents","description":"Voice agents represent the frontier of AI interaction - humans speaking naturally with AI systems. The challenge isnt just speech recognition and synthesis, its achieving natural conversation flo...","bodyPreview":"# Voice Agents\n\nYou are a voice AI architect who has shipped production voice agents handling\nmillions of calls. You understand the physics of latency - every component\nadds milliseconds, and the sum determines whether conversations feel natural\nor awkward.\n\nYour core insight: Two architectures exist. Speech-to-speech (S2S) models like\nOpenAI Realtime API preserve emotion and achieve lowest latency but are less\ncontrollable. Pipeline architectures (STT→LLM→TTS) give you control at each\nstep but","body":"# Voice Agents\n\nYou are a voice AI architect who has shipped production voice agents handling\nmillions of calls. You understand the physics of latency - every component\nadds milliseconds, and the sum determines whether conversations feel natural\nor awkward.\n\nYour core insight: Two architectures exist. Speech-to-speech (S2S) models like\nOpenAI Realtime API preserve emotion and achieve lowest latency but are less\ncontrollable. Pipeline architectures (STT→LLM→TTS) give you control at each\nstep but add latency. Mos\n\n## Capabilities\n\n- voice-agents\n- speech-to-speech\n- speech-to-text\n- text-to-speech\n- conversational-ai\n- voice-activity-detection\n- turn-taking\n- barge-in-detection\n- voice-interfaces\n\n## Patterns\n\n### Speech-to-Speech Architecture\n\nDirect audio-to-audio processing for lowest latency\n\n### Pipeline Architecture\n\nSeparate STT → LLM → TTS for maximum control\n\n### Voice Activity Detection Pattern\n\nDetect when user starts/stops speaking\n\n## Anti-Patterns\n\n### ❌ Ignoring Latency Budget\n\n### ❌ Silence-Only Turn Detection\n\n### ❌ Long Responses\n\n## ⚠️ Sharp Edges\n\n| Issue | Severity | Solution |\n|-------|----------|----------|\n| Issue | critical | # Measure and budget latency for each component: |\n| Issue | high | # Target jitter metrics: |\n| Issue | high | # Use semantic VAD: |\n| Issue | high | # Implement barge-in detection: |\n| Issue | medium | # Constrain response length in prompts: |\n| Issue | medium | # Prompt for spoken format: |\n| Issue | medium | # Implement noise handling: |\n| Issue | medium | # Mitigate STT errors: |\n\n## Related Skills\n\nWorks well with: `agent-tool-builder`, `multi-agent-orchestration`, `llm-architect`, `backend`\n\n## When to Use\nThis skill is applicable to execute the workflow or actions described in the overview.\n\n---\n\n> 🏰 **Rei Skills** — Curated by [Rootcastle Engineering & Innovation](https://www.rootcastle.com) | Batuhan Ayrıbaş  \n> Engineering Beyond Boundaries | admin@rootcastle.com\n"},"lastSynced":"2026-03-08T02:14:03.224Z","agentAnalysis":{"suitability":{"en":"Ideal for Voice AI Architects handling millions of calls with low latency, particularly those working with Claude Code, Gemini CLI, and Cursor.","zh":"适合处理数百万通话且延迟低的语音AI架构师，特别是那些使用Claude Code、Gemini CLI和Cursor的开发者","ja":"数百万回の通話を低遅延で処理する必要があるVoice AIアーキテクト、特にClaude Code、Gemini CLI、Cursorを使用する開発者に最適","ko":"수백만 개의 통화를 낮은 지연 시간으로 처리해야 하는 음성 AI 아키텍트에게 적합하며, 특히 Claude Code, Gemini CLI 및 Cursor를 사용하는 개발자에게 적합","es":"Ideal para arquitectos de Voice AI que manejan millones de llamadas con baja latencia, particularmente aquellos que trabajan con Claude Code, Gemini CLI y Cursor.","fr":"Idéal pour les architectes Voice AI qui gèrent des millions d''appels avec une faible latence, en particulier ceux qui travaillent avec Claude Code, Gemini CLI et Cursor.","de":"Ideal für Voice-AI-Architekten, die Millionen von Anrufen mit geringer Latenz verwalten, insbesondere diejenigen, die mit Claude Code, Gemini CLI und Cursor arbeiten.","pt":"Ideal para Arquitetos de AI de Voz que lidam com milhões de chamadas com baixa latência, particularmente aqueles que trabalham com Claude Code, Gemini CLI e Cursor.","ru":"Идеально для Архитекторов Голосового ИИ, работающих с миллионами звонков и низкой задержкой, особенно тех, кто работает с Claude Code, Gemini CLI и Cursor.","ar":"مثالي لمهندسي الواجهة الصوتية للذكاء الاصطناعي الذين يتعاملون مع ملايين المكالمات مع انخفاض الزمن الفعلي، خاصة أولئك الذين يعملون مع Claude Code وGemini CLI وCursor."},"recommendation":{"en":"Empowers agents to develop voice AI solutions with ultra-low latency using Speech-to-Speech (S2S) models like OpenAI Realtime API, and pipeline architectures (STT→LLM→TTS) for controllable conversations, leveraging latency optimization techniques.","zh":"赋予代理开发人员使用语音转语音（S2S）模型（如OpenAI Realtime API）和管道架构（STT→LLM→TTS）开发超低延迟的语音AI解决方案的能力，用于可控对话，并利用延迟优化技术","ja":"エージェントに、OpenAI Realtime APIなどの音声対音声（S2S）モデルやパイプラインアーキテクチャ（STT→LLM→TTS）を使用して超低遅延の音声AIソリューションを開発する能力を与え、制御可能な会話を実現し、遅延最適化技術を利用","ko":"에이전트가 음성-음성(S2S) 모델(예: OpenAI Realtime API) 및 파이프라인 아키텍처(STT→LLM→TTS)를 사용하여 초저지연 음성 AI 솔루션을 개발할 수 있는 능력을 부여하여 제어 가능한 대화를 가능하게 하고 지연 시간 최적화 기술을 활용","es":"Permite a los agentes desarrollar soluciones de voz AI con una latencia ultrabaja utilizando modelos de Speech-to-Speech (S2S) como OpenAI Realtime API, y arquitecturas de tuberías (STT→LLM→TTS) para conversaciones controlables, aprovechando técnicas de optimización de latencia.","fr":"Permet aux agents de développer des solutions de voix IA avec une latence ultrabasse en utilisant des modèles Speech-to-Speech (S2S) tels que OpenAI Realtime API, et des architectures de pipeline (STT→LLM→TTS) pour des conversations contrôlables, en exploitant les techniques d''optimisation de la latence.","de":"Ermöglicht es Agenten, Sprach-AI-Lösungen mit ultraniedriger Latenz zu entwickeln, indem sie Speech-to-Speech-Modelle (S2S) wie OpenAI Realtime API und Pipeline-Architekturen (STT→LLM→TTS) für steuerbare Konversationen verwenden, die Latenzoptimierungstechniken nutzend.","pt":"Habilita os agentes a desenvolver soluções de AI de voz com latência ultra-baixa usando modelos de Fala-para-Fala (S2S) como OpenAI Realtime API e arquiteturas de pipeline (STT→LLM→TTS) para conversas controláveis, aproveitando técnicas de otimização de latência.","ru":"Наделяет агентов возможностью разрабатывать решения голосового ИИ с сверхнизкой задержкой с использованием моделей Speech-to-Speech (S2S), таких как OpenAI Realtime API, и архитектур конвейера (STT→LLM→TTS) для контролируемых разговоров, используя методы оптимизации задержки.","ar":"تمكّن الوكلاء من تطوير حلول الذكاء الاصطناعي الصوتي ذات الزمن الفعلي الفائق-المنخفض باستخدام نماذج الصوت إلى الصوت (S2S) مثل OpenAI Realtime API وعمليات بناء الأنابيب (STT→LLM→TTS) من أجل محادثات قابلة للتحكم، مستفيدة من تقنيات تحسين الزمن الفعلي."},"useCases":{"en":["Designing voice agents for natural conversations","Optimizing latency in voice AI pipelines","Developing controllable voice AI architectures with STT, LLM, and TTS"],"zh":["为自然对话设计语音代理","在语音AI管道中优化延迟","使用STT、LLM和TTS开发可控语音AI架构"],"ja":["自然な会話のための音声エージェントを設計","音声AIパイプラインでの遅延の最適化","STT、LLM、TTSを使用した制御可能な音声AIアーキテクチャの開発"],"ko":["자연스러운 대화에 대한 음성 에이전트 설계","음성 AI 파이프라인에서 지연 시간 최적화","STT, LLM 및 TTS를 사용한 제어 가능한 음성 AI 아키텍처 개발"],"es":["Diseñar agentes de voz para conversaciones naturales","Optimizar la latencia en tuberías de voz AI","Desarrollar arquitecturas de voz AI controlables con STT, LLM y TTS"],"fr":["Concevoir des agents vocaux pour des conversations naturelles","Optimiser la latence dans les pipelines de voix IA","Développer des architectures de voix IA contrôlables avec STT, LLM et TTS"],"de":["Entwerfen von Sprachagenten für natürliche Konversationen","Optimieren der Latenz in Sprach-AI-Pipelines","Entwickeln von steuerbaren Sprach-AI-Architekturen mit STT, LLM und TTS"],"pt":["Projetar agentes de voz para conversas naturais","Otimizar a latência em pipelines de AI de voz","Desenvolver arquiteturas de AI de voz controláveis com STT, LLM e TTS"],"ru":["Проектирование голосовых агентов для естественных разговоров","Оптимизация задержки в конвейерах голосового ИИ","Разработка контролируемых архитектур голосового ИИ с STT, LLM и TTS"],"ar":["تصميم وكلاء صوتيين للمحادثات الطبيعية","تحسين الزمن الفعلي في خطوط أنابيب الذكاء الاصطناعي الصوتي","تطوير هياكل الذكاء الاصطناعي الصوتي القابلة للتحكم مع STT وLLM وTTS"]},"limitations":{"en":["Requires understanding of latency physics","Trade-offs between controllability and latency in S2S models and pipeline architectures"],"zh":["需要理解延迟物理学","在S2S模型和管道架构中可控性和延迟之间的权衡"],"ja":["遅延物理学の理解が必要","S2Sモデルおよびパイプラインアーキテクチャにおける制御性と遅延のトレードオフ"],"ko":["지연 물리학을 이해해야 함","S2S 모델 및 파이프라인 아키텍처에서 제어 가능성과 지연 시간 사이의 트레이드 오프"],"es":["Requiere comprensión de la física de la latencia","Compromisos entre controlabilidad y latencia en modelos S2S y arquitecturas de tuberías"],"fr":["Nécessite une compréhension de la physique de la latence","Compromis entre contrôlabilité et latence dans les modèles S2S et les architectures de pipeline"],"de":["Erfordert Verständnis der Latenzphysik","Kompromisse zwischen Steuerbarkeit und Latenz in S2S-Modellen und Pipeline-Architekturen"],"pt":["Requer entendimento da física da latência","Compromissos entre controlabilidade e latência em modelos S2S e arquiteturas de pipeline"],"ru":["Требует понимания физики задержки","Компромиссы между контролируемостью и задержкой в моделях S2S и архитектурах конвейера"],"ar":["يتطلب فهم فيزياء الزمن الفعلي","التضحيات بين القابلية للتحكم والزمن الفعلي في نماذج S2S وعمليات بناء الأنابيب"]},"version":4},"contentHash":"3669dfc73457df4b2c06311b454e431a0b0dd6ace91d362905947fe428762a6a","qualityScore":44}');
