INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rootcastleco/rei-skills/voice-agents', 'voice-agents', 'rootcastleco', 'rei-skills', 'community', 'voice-agents rootcastleco rei-skills community The voice-agents skill provides 883+ universal agentic skills for voice AI architects, handling millions of calls with low latency. It benefits developers working with Claude Code, Gemini CLI, and Cursor. 语音AI代理技术是实现自然流畅的对话体验的关键，了解语音到语音模型和管道架构的差异 AIエージェントの音声アーキテクチャは会話体験を決定づける、Speech-to-speechモデルとPipelineアーキテクチャの違いを理解する 음성 AI 에이전트 기술은 자연스러운 대화 경험을实现하는 데 핵심입니다. 음성에서 음성 모델과 파이프라인 아키텍처의 차이를 알아보세요 Los agentes de voz son soluciones de IA que permiten conversaciones naturales con usuarios, utilizando tecnologías como OpenAI Realtime API y arquitecturas de pipeline Les agents vocaux sont des solutions d''IA qui permettent des conversations naturelles avec les utilisateurs, en utilisant des technologies comme OpenAI Realtime API et des architectures de pipeline Voice-Agents sind künstliche Intelligenz-Lösungen, die natürliche Konversationen mit Benutzern ermöglichen, unter Verwendung von Technologien wie OpenAI Realtime API und Pipeline-Architekturen Os agentes de voz são arquiteturas de IA que permitem a interação por voz com baixa latência, utilizando modelos S2S ou pipeline ИИ агенты голоса являются архитектурами ИИ, которые позволяют голосовое взаимодействие с низкой задержкой, используя модели S2S или pipeline وكلاء الصوت هم هندسات ذكاء اصطناعي تسمح بالتفاعل الصوتي مع انخفاض التأخير، باستخدام نماذج S2S أو pipeline how to use voice-agents voice-agents setup guide voice-agents alternative voice-agents vs OpenAI what is voice-agents voice-agents install voice-agents for AI agents speech-to-speech models pipeline architectures for voice AI 语音AI代理 语音技术 AI对话 自然语言处理 语音到语音模型 管道架构 低延迟对话 Supports speech-to-speech (S2S) models like OpenAI Realtime API for low latency Utilizes pipeline architectures (STT→LLM→TTS) for controllable voice AI Optimizes latency in voice AI conversations for natural user experience Compatible with Claude Code, Gemini CLI, and Cursor for seamless integration Provides 883+ universal agentic skills for versatile voice AI development Handles millions of calls with scalable and reliable voice AI architectures voice-agents is a collection of skills for designing and deploying voice AI agents, focusing on speech-to-speech and pipeline architectures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shalevamin/The-_Ultimate_agents/draft-nda', 'community', 'shalevamin', 'The-_Ultimate_agents', 'shalevamin/The-_Ultimate_agents', 'draft-nda', 0, 0, 44, '2026-03-07T17:44:27Z', '2026-03-08T02:17:50.931Z', 'e37a613bae8038220aac1e45f73596a419920015abe28d4a012d339a0e018247', '{"id":"shalevamin/The-_Ultimate_agents/draft-nda","name":"draft-nda","description":{"en":"The draft-nda skill helps draft detailed Non-Disclosure Agreements between parties, covering information types, jurisdiction, and clauses requiring legal review. It benefits legal document specialists and parties requiring confidentiality agreements.","zh":"draft-nda技能帮助生成专业保密协议，涵盖信息类型、管辖权等，提供清晰的说明","ja":"draft-ndaスキルは、情報タイプや管轄区域をカバーする包括的な非公開同意書を生成します","ko":"draft-nda 스킬은 정보 유형, 관할 권한 등을 포함하는 포괄적인 비공개 협약서를 생성합니다"},"seo":{"title":{"en":"draft-nda: NDA Drafting Setup Guide | AI Agent Skill","zh":"draft-nda Setup Guide: 生成专业保密协议","ja":"draft-nda ベストプラクティス: AIエージェントによる非公開同意書作成","ko":"draft-nda 설정 가이드: 전문적인 비공개 협약서 초안"},"description":{"en":"Discover how to create comprehensive Non-Disclosure Agreements with draft-nda. Get started with our expert guide and learn to draft clear, professional NDAs ...","zh":"了解draft-nda技能，使用AI工具生成详细、清晰的保密协议，涵盖信息类型、管辖权等","ja":"draft-ndaスキルを使用して、情報タイプや管轄区域をカバーする包括的な非公開同意書を生成します","ko":"draft-nda 스킬로 정보 유형, 관할 권한 등을 포함하는 포괄적인 비공개 협약서를 생성합니다"},"definition":{"en":"draft-nda is a skill for drafting comprehensive Non-Disclosure Agreements, providing plain-language explanations for accessibility and clarity.","zh":"draft-nda是生成保密协议的AI技能，帮助创建详细、清晰的协议","ja":"draft-ndaは、包括的な非公開同意書を生成するAIエージェントスキルです","ko":"draft-nda는 비공개 협약서를 생성하는 AI 스킬입니다"},"features":{"en":["Drafts comprehensive Non-Disclosure Agreements between two parties","Covers information types, jurisdiction, and clauses requiring legal review","Provides plain-language explanations for accessibility and clarity","Clearly marks clauses that require legal review","Generates detailed and professional NDAs"],"zh":["生成详细、清晰的保密协议","涵盖信息类型、管辖权等","提供清晰的说明","支持多方签署","包含法律审查要求"],"ja":["包括的な非公開同意書を生成","情報タイプや管轄区域をカバー","明確な説明を提供","複数の署名をサポート","法律レビューの要件を含む"],"ko":["포괄적인 비공개 협약서를 생성","정보 유형, 관할 권한 등을 포함","명확한 설명을 제공","다수의 서명을 지원","법률 검토 요구 사항을 포함"]},"keywords":{"en":["how to use draft-nda","what is draft-nda","draft-nda alternative","draft-nda vs contract drafting software","draft-nda install","draft-nda setup guide","non-disclosure agreement template","confidentiality agreement drafting","legal document specialist tools"],"zh":["draft-nda","保密协议","AI工具","生成保密协议","信息类型","管辖权","法律审查"],"ja":["draft-nda","非公開同意書","AIエージェント","包括的な非公開同意書を生成","情報タイプ","管轄区域","法律レビュー"],"ko":["draft-nda","비공개 협약서","AI 스킬","포괄적인 비공개 협약서를 생성","정보 유형","관할 권한","법률 검토"]}},"owner":"shalevamin","repo":"The-_Ultimate_agents","repoPath":"shalevamin/The-_Ultimate_agents","stars":0,"forks":0,"updatedAt":"2026-03-07T17:44:27Z","topics":[],"category":"community","skillMd":{"name":"draft-nda","description":"Draft a detailed Non-Disclosure Agreement between two parties covering information types, jurisdiction, and clauses needing legal review. Use when creating confidentiality agreements or preparing an NDA for a partnership.","bodyPreview":"# NDA (Non-Disclosure Agreement) Drafting\n\nYou are an experienced legal document specialist with expertise in confidentiality agreements. Your role is to help draft detailed, clear, and professional Non-Disclosure Agreements between parties.\n\n## Purpose\nDraft a comprehensive Non-Disclosure Agreement (NDA) between two parties. The NDA covers information types, jurisdiction, and clearly marks clauses that require legal review. Provide plain-language explanations to make the document accessible.\n\n#","body":"# NDA (Non-Disclosure Agreement) Drafting\n\nYou are an experienced legal document specialist with expertise in confidentiality agreements. Your role is to help draft detailed, clear, and professional Non-Disclosure Agreements between parties.\n\n## Purpose\nDraft a comprehensive Non-Disclosure Agreement (NDA) between two parties. The NDA covers information types, jurisdiction, and clearly marks clauses that require legal review. Provide plain-language explanations to make the document accessible.\n\n## Important Disclaimer\n**This is for informational purposes only and does not constitute legal advice. Always have a licensed attorney review the final document before execution. NDAs are legally binding contracts; professional legal review is essential.**\n\n## Input Arguments\n- `$COMPANY_ONE_NAME`: Name of the first party/company\n- `$COMPANY_ONE_ADDRESS`: Address of the first party/company\n- `$COMPANY_ONE_REPS`: Names and titles of representatives (e.g., \"John Smith, CEO; Jane Doe, General Counsel\")\n- `$COMPANY_TWO_NAME`: Name of the second party/company\n- `$COMPANY_TWO_ADDRESS`: Address of the second party/company\n- `$COMPANY_TWO_REPS`: Names and titles of representatives\n- `$INFORMATION_TYPES`: Types of information to be shared (e.g., \"business plans, customer lists, technical specifications, pricing data, source code\")\n- `$JURISDICTION`: Governing jurisdiction (e.g., \"State of California, United States\" or \"England and Wales\")\n\n## Process\n\n### Step 1: Clarify Requirements\nBefore drafting, note down:\n- Are both parties companies or is one an individual?\n- What specific types of information will be shared?\n- Is this one-way (only one party shares) or mutual (both parties share)?\n- What is the geographic jurisdiction?\n- What is the intended duration of the NDA?\n\n### Step 2: Structure the NDA\nOrganize the NDA in standard sections:\n\n1. **Preamble** (Parties, definitions, effective date)\n2. **Definitions** (What is \"Confidential Information\"?)\n3. **Obligation to Maintain Confidentiality** (Core obligation)\n4. **Permitted Disclosures** (Exceptions to confidentiality)\n5. **Term and Duration** (How long does the NDA last?)\n6. **Return or Destruction of Information** (What happens after?)\n7. **Remedies** (Consequences for breach)\n8. **General Provisions** (Governing law, jurisdiction, severability)\n\n### Step 3: Use Plain Language\nWrite each section in clear, accessible language. Avoid legal jargon where possible. Define terms the first time they''re used.\n\n### Step 4: Highlight Clauses Needing Legal Review\nMark sections with [⚠️ LEGAL REVIEW REQUIRED] where customization or specific legal expertise is needed. Include explanations of what should be reviewed.\n\n### Step 5: Provide Context\nInclude brief notes explaining:\n- Why each section is important\n- What decisions need to be made by the parties\n- Common pitfalls or considerations\n\n## NDA Template Structure\n\nPresent the draft NDA in this order:\n\n**[COVER NOTE]**\nA brief note explaining the NDA''s purpose, the parties involved, and key provisions.\n\n**[FULL NDA DOCUMENT]**\nThe complete agreement ready for customization.\n\n**[NOTES ON KEY CLAUSES]**\nExplanations of important sections and what may need legal customization.\n\n---\n\n## Key Sections to Include\n\n### Preamble\n- Introduce both parties clearly with full legal names and addresses\n- State the purpose: exploring a potential business relationship, partnership, merger, etc.\n- Define the \"Effective Date\"\n\n### Definitions\n- **Confidential Information**: Specify what is considered confidential (business plans, financial data, technical specs, customer lists, etc.). Include scope.\n- **Excluded Information**: Clarify what is NOT confidential (publicly available information, information independently developed, information received from third parties without confidentiality obligations)\n\n### Obligations\n- Describe the receiving party''s duty to keep information confidential\n- Specify approved uses of the information\n- Outline permitted disclosures (to employees, advisors, on a need-to-know basis)\n- [⚠️ LEGAL REVIEW REQUIRED] Standard of care (e.g., \"same care as own confidential information, but no less than reasonable care\")\n\n### Permitted Disclosures\n- Specify who can be told (employees, advisors, consultants on a need-to-know basis)\n- Include a requirement that recipients also agree to confidentiality\n- Add exception for legally required disclosures (with notice requirement, if possible)\n\n### Term and Duration\n- Define the period during which information is being shared\n- Define how long confidentiality obligations survive after the relationship ends\n- [⚠️ LEGAL REVIEW REQUIRED] Consider different durations for different information types (trade secrets may require longer protection)\n\n### Return or Destruction\n- Specify that the receiving party must return or securely destroy confidential information upon request or upon termination\n- Option to certify in writing that destruction is complete\n- Consider: does the receiving party keep one copy for legal compliance?\n\n### Remedies\n- [⚠️ LEGAL REVIEW REQUIRED] State that breach may cause irreparable harm and that injunctive relief is available\n- Clarify that remedies are in addition to other legal remedies available\n\n### General Provisions\n- **Governing Law and Jurisdiction**: Specify which state or country''s laws govern (e.g., California or England)\n- [⚠️ LEGAL REVIEW REQUIRED] Dispute resolution process (litigation, arbitration, mediation)\n- **Severability**: If one provision is invalid, others remain in force\n- **Entire Agreement**: This NDA supersedes prior discussions\n- **Amendments**: Specify that NDA can only be modified in writing, signed by both parties\n- **Counterparts**: Parties can sign separate copies\n\n---\n\n## Content Guidelines\n\n- **Plain Language**: Write for a primary-school-educated reader. Avoid Latin phrases, unnecessary legal terms.\n- **Clarity over Precision**: Choose clear language first. Legal precision can be refined by attorneys.\n- **Examples**: Where helpful, include examples of what is/isn''t confidential information.\n- **Specific Information Types**: Use the $INFORMATION_TYPES provided to make the agreement specific, not generic.\n- **Mutual or One-Way**: If $INFORMATION_TYPES suggests only one party is sharing, note this as a one-way NDA. If both, use mutual language.\n\n---\n\n## Output Format\n\nPresent the NDA in three parts:\n\n### Part 1: Summary\nBullet-point overview of:\n- Parties involved\n- Information types covered\n- Key duration and terms\n- Jurisdiction\n\n### Part 2: Full NDA Document\nA complete, ready-to-customize NDA document.\n\n### Part 3: Customization Notes\nGuidance on:\n- Sections marked for legal review\n- Decisions parties need to make\n- Common modifications based on situation\n- Next steps (legal review, signing process)\n\n---\n\n## Important Reminders\n\n- This is a starting point, not final legal advice\n- Jurisdictions vary widely; have a lawyer in the relevant jurisdiction review\n- Some industries (tech, pharma, finance) have specific NDA conventions\n- Consider mutual vs. one-way requirements\n- Think about duration: How long should the information be protected?\n- Always have an attorney review before any party signs\n"},"lastSynced":"2026-03-08T02:17:50.931Z","agentAnalysis":{"suitability":{"en":"Perfect for Contract Analysis Agents needing automated Non-Disclosure Agreement drafting capabilities.","zh":"适合需要自动化非披露协议草拟能力的合同分析代理","ja":"契約分析エージェントが自動化された非開示協約の草案作成機能を必要とする場合に適しています","ko":"계약 분석 에이전트가 자동화된 비공개 협약 초안 작성 기능을 필요로 하는 경우에 적합합니다","es":"Perfecto para Agentes de Análisis de Contratos que necesitan capacidades de redacción automatizada de Acuerdos de No Divulgación.","fr":"Parfait pour les Agents d''Analyse de Contrats ayant besoin de capacités de rédaction automatisée d''Accords de Non-Divulgation.","de":"Perfekt für Vertragsanalyse-Agenten, die automatisierte Fähigkeiten zur Erstellung von Geheimhaltungsvereinbarungen benötigen.","pt":"Perfeito para Agentes de Análise de Contrato que precisam de capacidades de criação automática de Acordos de Não Divulgação.","ru":"Идеально для Агентов Анализа Контрактов, которым необходимы автоматические возможности создания Соглашений о Неразглашении.","ar":"مثالي لعمليات تحليل العقد التي تحتاج إلى قدراتautomated لصياغة اتفاقيات عدم إفصاح."},"recommendation":{"en":"Empowers agents to generate comprehensive NDAs covering information types, jurisdiction, and clauses requiring legal review, utilizing plain-language explanations and marking sections that necessitate legal expertise, such as contract law and confidentiality agreements.","zh":"赋予代理生成全面性的非披露协议，涵盖信息类型、管辖权和需要法律审查的条款，利用平易的语言解释，并标记需要法律专业知识的部分，例如合同法和保密协议","ja":"エージェントに情報の種類、管轄区域、および法律のレビューが必要な条項を網羅した包括的な非開示協約を生成する能力を与え、平易な言語の説明を利用し、契約法や機密協約などの法律の専門知識が必要な部分をマークします","ko":"정보 유형, 관할 권한 및 법적 검토가 필요한 조항을 포함한 포괄적인 비공개 협약을 생성할 수 있는 에이전트에게 능력을 부여하며, 평이한 언어 설명을 활용하고, 계약법 및 기밀 협약과 같은 법률 전문 지식이 필요한 부분을 표시합니다","es":"Habilita a los agentes a generar Acuerdos de No Divulgación completos que cubren los tipos de información, la jurisdicción y las cláusulas que requieren revisión legal, utilizando explicaciones en lenguaje claro y marcando secciones que necesitan experiencia legal, como la ley de contratos y los acuerdos de confidencialidad.","fr":"Permet aux agents de générer des Accords de Non-Divulgation complets couvrant les types d''informations, la juridiction et les clauses nécessitant une révision juridique, en utilisant des explications en langage clair et en marquant les sections qui nécessitent une expertise juridique, telles que le droit des contrats et les accords de confidentialité.","de":"Ermächtigt Agenten, umfassende Geheimhaltungsvereinbarungen zu erstellen, die Informationen, Gerichtsbarkeit und Klauseln abdecken, die eine rechtliche Überprüfung erfordern, unter Verwendung von Erklärungen in einfacher Sprache und Markierung von Abschnitten, die juristisches Fachwissen erfordern, wie Vertragsrecht und Geheimhaltungsvereinbarungen.","pt":"Habilita os agentes a gerar NDAs abrangentes que cobrem tipos de informações, jurisdição e cláusulas que requerem revisão legal, utilizando explicações em linguagem simples e marcando seções que necessitam de especialização jurídica, como lei de contratos e acordos de confidencialidade.","ru":"Наделяет агентов возможностью создавать комплексные Соглашения о Неразглашении, охватывающие типы информации, юрисдикцию и положения, требующие юридического рассмотрения, используя объяснения на простом языке и помечая разделы, требующие юридической экспертизы, такие как контрактное право и соглашения о конфиденциальности.","ar":"تمكين الوكيل من إنتاج اتفاقيات عدم إفصاح شاملة تغطي أنواع المعلومات والولاية القضائية والشروط التي تتطلب استعراضًا قانونيًا، باستخدام شرح بلغة بسيطة وتحديد الأقسام التي تتطلب خبرة قانونية، مثل قانون العقود والاتفاقات السرية."},"useCases":{"en":["Drafting mutual NDAs between business partners","Generating one-way NDAs for employee onboarding","Reviewing and marking clauses for legal review in existing NDAs"],"zh":["为商业伙伴之间起草互惠的非披露协议","为员工入职生成单向非披露协议","审查和标记现有非披露协议中需要法律审查的条款"],"ja":["ビジネスパートナー間の相互非開示協約の草案作成","従業員の入職時に一方向の非開示協約を生成する","既存の非開示協約の中で法律のレビューが必要な条項をレビューおよびマークする"],"ko":["사업 파트너 사이의 상호 비공개 협약 초안 작성","직원 입사를 위한 일방적인 비공개 협약 생성","기존 비공개 협약에서 법적 검토가 필요한 조항을 검토 및 표시"],"es":["Redacción de Acuerdos de No Divulgación mutuos entre socios comerciales","Generación de Acuerdos de No Divulgación unidireccionales para la incorporación de empleados","Revisión y marcado de cláusulas para revisión legal en Acuerdos de No Divulgación existentes"],"fr":["Rédaction d''Accords de Non-Divulgation mutuels entre partenaires commerciaux","Génération d''Accords de Non-Divulgation unidirectionnels pour l''intégration des employés","Révision et marquage de clauses pour révision juridique dans les Accords de Non-Divulgation existants"],"de":["Erstellung von gegenseitigen Geheimhaltungsvereinbarungen zwischen Geschäftspartnern","Erzeugung von einseitigen Geheimhaltungsvereinbarungen für die Einstellung von Mitarbeitern","Überprüfung und Markierung von Klauseln für rechtliche Überprüfung in bestehenden Geheimhaltungsvereinbarungen"],"pt":["Criar NDAs mútuos entre parceiros de negócios","Gerar NDAs unidirecionais para integração de funcionários","Revisar e marcar cláusulas para revisão legal em NDAs existentes"],"ru":["Создание взаимных Соглашений о Неразглашении между деловыми партнерами","Генерация односторонних Соглашений о Неразглашении для интеграции сотрудников","Проверка и пометка положений для юридического рассмотрения в существующих Соглашениях о Неразглашении"],"ar":["صياغة اتفاقيات عدم إفصاح متقابل بين شركاء الأعمال","إنتاج اتفاقيات عدم إفصاح ذات اتجاه واحد لدمج الموظفين","مراجعة وتحديد الشروط الموجزة لاستعراض法يين في اتفاقيات عدم إفصاح موجودة"]},"limitations":{"en":["Requires legal knowledge integration","Limited to standard NDA templates","May necessitate human legal review for complex or specialized agreements"],"zh":["需要整合法律知识","仅限于标准非披露协议模板","可能需要人类的法律审查来处理复杂或专业的协议"],"ja":["法律知識の統合が必要","標準の非開示協約テンプレートに限られる","複雑または専門的な協約の場合、人間の法律のレビューが必要になる可能性がある"],"ko":["법률 지식 통합이 필요","표준 비공개 협약 템플릿에만 제한","복잡하거나 전문적인 협약의 경우 인간의 법적 검토가 필요할 수 있음"],"es":["Requiere integración de conocimientos jurídicos","Limitado a plantillas de Acuerdos de No Divulgación estándar","Puede necesitar revisión legal humana para acuerdos complejos o especializados"],"fr":["Nécessite une intégration de connaissances juridiques","Limité aux modèles d''Accords de Non-Divulgation standard","Peut nécessiter une révision juridique humaine pour des accords complexes ou spécialisés"],"de":["Benötigt die Integration von Rechtskenntnissen","Begrenzt auf Standard-Vorlagen für Geheimhaltungsvereinbarungen","Kann für komplexe oder spezialisierte Vereinbarungen eine menschliche rechtliche Überprüfung erfordern"],"pt":["Requer integração de conhecimento jurídico","Limitado a modelos de NDA padrão","Pode necessitar de revisão humana jurídica para acordos complexos ou especializados"],"ru":["Требует интеграции юридических знаний","Ограничен стандартными шаблонами Соглашений о Неразглашении","Может потребовать человеческого юридического рассмотрения для сложных или специализированных соглашений"],"ar":["يتطلب دمج معرفة قانونية","محدود بنماذج اتفاقيات عدم إفصاح قياسية","يمكن أن يتطلب مراجعة قانونية بشرية لاتفاقيات معقدة أو متخصصة"]},"version":4},"contentHash":"e37a613bae8038220aac1e45f73596a419920015abe28d4a012d339a0e018247","qualityScore":44}');
