INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shalevamin/The-_Ultimate_agents/draft-nda', 'draft-nda', 'shalevamin', 'The-_Ultimate_agents', 'community', 'draft-nda shalevamin The-_Ultimate_agents community The draft-nda skill helps draft detailed Non-Disclosure Agreements between parties, covering information types, jurisdiction, and clauses requiring legal review. It benefits legal document specialists and parties requiring confidentiality agreements. draft-nda技能帮助生成专业保密协议，涵盖信息类型、管辖权等，提供清晰的说明 draft-ndaスキルは、情報タイプや管轄区域をカバーする包括的な非公開同意書を生成します draft-nda 스킬은 정보 유형, 관할 권한 등을 포함하는 포괄적인 비공개 협약서를 생성합니다 how to use draft-nda what is draft-nda draft-nda alternative draft-nda vs contract drafting software draft-nda install draft-nda setup guide non-disclosure agreement template confidentiality agreement drafting legal document specialist tools draft-nda 保密协议 AI工具 生成保密协议 信息类型 管辖权 法律审查 Drafts comprehensive Non-Disclosure Agreements between two parties Covers information types, jurisdiction, and clauses requiring legal review Provides plain-language explanations for accessibility and clarity Clearly marks clauses that require legal review Generates detailed and professional NDAs draft-nda is a skill for drafting comprehensive Non-Disclosure Agreements, providing plain-language explanations for accessibility and clarity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ace-step/ACE-Step-1.5/acestep-docs', 'community', 'ace-step', 'ACE-Step-1.5', 'ace-step/ACE-Step-1.5', 'acestep-docs', 0, 0, 44, '2026-03-07T12:46:33.411Z', '2026-03-07T12:52:26.600Z', '32f02c5a183ae7026c1e3adc85604589d2b1430ebd799d554fb07be9dc0f3356', '{"id":"ace-step/ACE-Step-1.5/acestep-docs","name":"acestep-docs","description":{"en":"The acestep-docs skill is a local music generation model supporting Mac, AMD, Intel, and CUDA devices, providing a comprehensive documentation system for developers.","zh":"ACE-Step 文档提供了强大的本地音乐生成模型的设置和使用指南，支持多种设备和平台","ja":"ACE-Step ドキュメントは、最強のローカル音楽生成モデルを設定して使用するためのガイドを提供します。多くのデバイスとプラットフォームをサポートしています","ko":"ACE-Step 문서는 강력한 로컬 음악 생성 모델을 설정하고 사용하는 방법에 대한 가이드를 제공하며, 여러 장치와 플랫폼을 지원합니다","es":"ACE-Step Docs es un modelo de generación de música local que supera a la mayoría de las alternativas comerciales, compatible con Mac, AMD, Intel y dispositivos CUDA. Proporciona una guía de configuración y mejores prácticas para desarrolladores","fr":"ACE-Step Docs est un modèle de génération de musique local qui surpasse la plupart des alternatives commerciales, compatible avec Mac, AMD, Intel et appareils CUDA. Il propose un guide d''installation et des meilleures pratiques pour les développeurs","de":"ACE-Step Docs ist ein lokales Musikgenerierungsmodell, das die meisten kommerziellen Alternativen übertrifft, kompatibel mit Mac, AMD, Intel und CUDA-Geräten. Es bietet eine Einrichtungsanleitung und Best Practices für Entwickler","pt":"O acestep-docs é um modelo de geração de música local que supera a maioria das alternativas comerciais, com suporte a dispositivos Mac, AMD, Intel e CUDA.","ru":"Acestep-docs - это самый мощный местный модель генерации музыки, превосходящий большинство коммерческих альтернатив, с поддержкой устройств Mac, AMD, Intel и CUDA, используя ИИ Агенты","ar":"acestep-docs هو نظام توليد موسيقى محلي الأكثر قوة، يتجاوز معظم البديلات التجارية، مع دعم لأجهزة ماك، AMD، Intel وCUDA"},"seo":{"title":{"en":"acestep-docs: Local Music Generation Setup Guide | AI Age...","zh":"ACE-Step 文档：强大的本地音乐生成模型设置指南","ja":"ACE-Step ドキュメント：最強のローカル音楽生成モデル設定ガイド - AIエージェント","ko":"ACE-Step 문서: 가장 강력한 로컬 음악 생성 모델 설정 가이드 - AI 에이전트","es":"Guía de configuración de ACE-Step Docs - Modelo de genera...","fr":"Guide d''installation d''ACE-Step Docs - Modèle de générati...","de":"Einrichtungsanleitung für ACE-Step Docs - Lokales Musikge...","pt":"Guia de Configuração acestep-docs: Modelo de Geração de M...","ru":"Настройка acestep-docs: Мощный Местный Модель Генерации М...","ar":"دليل إعداد acestep-docs: نظام توليد الموسيقى المحلي الأكث..."},"description":{"en":"Unlock the full potential of acestep-docs, a cutting-edge local music generation model. Get started with our tutorial and README guide to outperform commerci...","zh":"了解 ACE-Step 文档，快速上手强大的本地音乐生成模型。支持 Mac、AMD、Intel 和 CUDA 设备，提供详细的设置和使用指南","ja":"ACE-Step ドキュメントを使用して、最強のローカル音楽生成モデルを設定しましょう。Mac、AMD、Intel、CUDA デバイスをサポートし、詳細な設定と使用方法のガイドを提供します - AIエージェント","ko":"ACE-Step 문서를 통해 강력한 로컬 음악 생성 모델을 설정하고 사용하는 방법을 알아보세요. Mac, AMD, Intel, CUDA 장치를 지원하며, 자세한 설정 및 사용 가이드를 제공합니다 - AI 에이전트","es":"Descubre cómo configurar ACE-Step Docs, el modelo de generación de música local más potente, compatible con Mac, AMD, Intel y dispositivos CUDA","fr":"Découvrez comment installer ACE-Step Docs, le modèle de génération de musique local le plus puissant, compatible avec Mac, AMD, Intel et appareils CUDA","de":"Erfahren Sie, wie Sie ACE-Step Docs einrichten, das leistungsstärkste lokale Musikgenerierungsmodell, kompatibel mit Mac, AMD, Intel und CUDA-Geräten","pt":"Aprenda a configurar o acestep-docs, o modelo de geração de música local mais poderoso, com suporte a Mac, AMD, Intel e dispositivos CUDA","ru":"Узнайте, как настроить acestep-docs, самый мощный местный модель генерации музыки, поддерживающий Mac, AMD, Intel и устройства CUDA, с помощью ИИ Агенты","ar":"تعرف على كيفية إعداد acestep-docs، نظام توليد الموسيقى المحلي الأكثر قوة، مع دعم لماك، AMD، Intel وأجهزة CUDA"},"definition":{"en":"acestep-docs is a documentation skill for the ACE-Step music generation system, offering guides, tutorials, and project overviews.","zh":"ACE-Step 文档是用于设置和使用强大的本地音乐生成模型的技术文档","ja":"ACE-Step ドキュメントは、最強のローカル音楽生成モデルを設定して使用するための技術文書です","ko":"ACE-Step 문서는 강력한 로컬 음악 생성 모델을 설정하고 사용하는 방법에 대한 기술 문서입니다","es":"ACE-Step Docs es un modelo de generación de música local que utiliza tecnologías como CUDA para proporcionar una experiencia de música de alta calidad","fr":"ACE-Step Docs est un modèle de génération de musique local qui utilise des technologies comme CUDA pour fournir une expérience musicale de haute qualité","de":"ACE-Step Docs ist ein lokales Musikgenerierungsmodell, das Technologien wie CUDA nutzt, um eine hochwertige Musik-Erfahrung zu bieten","pt":"O que é acestep-docs? É um modelo de geração de música local que fornece documentação e guias para configuração e uso","ru":"Что такое acestep-docs? Это мощный местный модель генерации музыки, предоставляющий документацию и руководства для настройки и использования с помощью ИИ Агенты","ar":"ما هو acestep-docs؟ هو نظام توليد موسيقى محلي يقدم وثائق وإرشادات لإعداد واستخدام"},"features":{"en":["Supports installation and model download via README.md","Provides a getting started tutorial with best practices in Tutorial.md","Offers project overview, architecture, and model zoo information in ABOUT.md","Compatible with Mac, AMD, Intel, and CUDA devices for music generation","Includes quick reference guides for easy navigation and setup"],"zh":["支持 Mac、AMD、Intel 和 CUDA 设备","提供详细的设置和使用指南","包括 README.md、Tutorial.md 和 ABOUT.md 文档","支持多种音乐生成模型","提供项目概述和架构信息"],"ja":["Mac、AMD、Intel、CUDA デバイスをサポート","詳細な設定と使用方法のガイドを提供","README.md、Tutorial.md、ABOUT.md ドキュメントを含む","多くの音楽生成モデルをサポート","プロジェクト概要とアーキテクチャ情報を提供"],"ko":["Mac, AMD, Intel, CUDA 장치를 지원","자세한 설정 및 사용 가이드를 제공","README.md