INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('videojs/v10/api', 'api', 'videojs', 'v10', 'community', 'api videojs v10 community Video.js v10 是一个开源媒体播放器框架，适用于 Web 和 React 开发，提供技术预览和 AI 智能代理功能 Video.js v10 は、Web と React 向けのオープンソース メディア プレーヤー フレームワークです。テクニカル プレビューと AI エージェント機能を提供します Video.js v10 는 웹과 리액트를 위한 오픈소스 미디어 플레이어 프레임워크입니다. 기술 프리뷰와 AI 에이전트 기능을 제공합니다 Video.js v10 es una vista previa técnica del popular framework de reproductor multimedia de código abierto. Ofrece mejoras significativas para desarrolladores que trabajan con Web y React, incluyendo nuevas herramientas de IA para optimización de medios. Video.js v10 est un aperçu technique du populaire framework open source de lecteur multimédia. Il offre des améliorations significatives pour les développeurs travaillant avec Web et React, incluant de nouveaux outils IA pour l''optimisation média. Video.js v10 ist eine technische Vorschau des beliebten Open-Source-Medienplayer-Frameworks. Es bietet bedeutende Verbesserungen für Entwickler, die mit Web und React arbeiten, einschließlich neuer KI-Tools für die Medienoptimierung. O Video.js v10 é um framework de mídia aberto para Web e React, permitindo a criação de experiências de usuário personalizadas. Video.js v10 - это открытый фреймворк медиа-плеера для Web и React, позволяющий создавать индивидуальные пользовательские trải nghiệm. Video.js v10 هو إطار الوسائط المفتوح للويب و React، مما يسمح بإنشاء تجارب مستخدم مخصصة. Technical preview of Video.js v10 - open source media player framework for Web and React. 如何使用 Video.js 什么是 AI 智能代理 Video.js 替代品 React 媒体播放器 Video.js 安装 Video.js 教程 Technical preview of Video.js v10 - open source media player framework for Web and React.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MythologIQ/Zo-Qore/vercel-composition-patterns', 'community', 'MythologIQ', 'Zo-Qore', 'MythologIQ/Zo-Qore', 'vercel-composition-patterns', 0, 0, 44, '2026-02-24T18:00:55Z', '2026-02-26T13:17:04.548Z', '2a0efb55f7933cf9fe23585d0874abc60ef088b8e22a2168c5704466c89a71e4', '{"id":"MythologIQ/Zo-Qore/vercel-composition-patterns","name":"vercel-composition-patterns","description":{"zh":"Vercel 组合模式是一种用于构建原生集成的 AI 智能代理，具有 Agentic Mesh 和 Qorelogic 治理","ja":"Vercel コンポジションパターンは、ネイティブ統合の AI エージェントを構築するための方法です","ko":"Vercel 컴포지션 패턴은 네이티브 통합 AI 에이전트를 구축하는 데 사용됩니다","es":"El patrón de composición de Vercel permite una integración nativa con Zo.computer y Agentic Mesh con capacidades de gobernanza de Qorelogic","fr":"Le modèle de composition Vercel permet une intégration native avec Zo.computer et Agentic Mesh avec des capacités de gouvernance Qorelogic","de":"Das Vercel-Zusammensetzungs-Muster ermöglicht eine native Integration mit Zo.computer und Agentic Mesh mit Qorelogic-Governance-Funktionen","pt":"O Vercel-composition-patterns é um agente de IA que utiliza Agentic Mesh e Qorelogic para integração nativa com Zo.computer","ru":"Vercel-composition-patterns - это ИИ агент, который использует Agentic Mesh и Qorelogic для родной интеграции с Zo.computer","ar":"Vercel-composition-patterns هو وكيل ذكي يستخدم Agentic Mesh و Qorelogic للدمج الأصلي مع Zo.computer","en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"seo":{"title":{"zh":"Vercel 组合模式 - AI智能代理","ja":"Vercel コンポジションパターン - AIエージェント","ko":"Vercel 컴포지션 패턴 - AI 에이전트","es":"Patrones de composición de Vercel para Agentes de IA","fr":"Modèles de composition Vercel pour les outils d''IA","de":"Vercel-Zusammensetzungs-Muster für KI-Agents","pt":"Padrões de Composição Vercel para Agentes de IA","ru":"ИИ Агенты: Шаблоны Комpositions Vercel","ar":"نماذج تركيبية Vercel للوكلاء الذكيين","en":"vercel-composition-patterns"},"description":{"zh":"Vercel 组合模式是一种用于构建原生集成的 AI 智能代理，具有 Agentic Mesh 和 Qorelogic 治理","ja":"Vercel コンポジションパターンは、ネイティブ統合の AI エージェントを構築するための方法です","ko":"Vercel 컴포지션 패턴은 네이티브 통합 AI 에이전트를 구축하는 데 사용됩니다","es":"El patrón de composición de Vercel permite una integración nativa con Zo.computer y Agentic Mesh con capacidades de gobernanza de Qorelogic","fr":"Le modèle de composition Vercel permet une intégration native avec Zo.computer et Agentic Mesh avec des capacités de gouvernance Qorelogic","de":"Das Vercel-Zusammensetzungs-Muster ermöglicht eine native Integration mit Zo.computer und Agentic Mesh mit Qorelogic-Governance-Funktionen","pt":"O Vercel-composition-patterns é um agente de IA que utiliza Agentic Mesh e Qorelogic para integração nativa com Zo.computer","ru":"Vercel-composition-patterns - это ИИ агент, который использует Agentic Mesh и Qorelogic для родной интеграции с Zo.computer","ar":"Vercel-composition-patterns هو وكيل ذكي يستخدم Agentic Mesh و Qorelogic للدمج الأصلي مع Zo.computer","en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"definition":{"en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"features":{"zh":["Agentic Mesh 集成","Qorelogic 治理","原生集成支持","递归学习协议","Zo.computer 支持"],"ja":["Agentic Mesh 統合","Qorelogic ガバナンス","ネイティブ統合サポート","再帰学習プロトコル","Zo.computer サポート"],"ko":["Agentic Mesh 통합","Qorelogic 거버넌스","네이티브 통합 지원","재귀 학습 프로토콜","Zo.computer 지원"],"es":["Integración nativa con Zo.computer","Capacidades de gobernanza de Qorelogic","Protocolo de aprendizaje recursivo","Agentic Mesh para desarrollo de Agentes de IA","Compatibilidad con Agent OS"],"fr":["Intégration native avec Zo.computer","Capacités de g